def get_special_gauge():
    return special_gauge
def consume_special_gauge(amount):
    """Deduct special gauge while keeping readiness state in sync."""
    global special_gauge, special_ready
    special_gauge = max(0, special_gauge - amount)
    special_ready = special_gauge >= 350

    # GameState-backed UIs expect live values; update when available.
    try:
        game_state.special_gauge = special_gauge
        game_state.special_ready = special_ready
    except Exception:
        # During early bootstrap or tests the singleton might be absent.
        pass


def store_bgm_volume(value: float) -> float:
    """오디오 상태 모듈과 전역 변수 모두에 BGM 볼륨을 반영."""

    global bgm_volume
    bgm_volume = set_bgm_volume_state(value)
    return bgm_volume


def play_sound_with_volume(sound, volume=None):
    """효과음을 지정된 볼륨으로 재생"""
    global sfx_volume
    if volume is None:
        volume = sfx_volume
    sound.set_volume(volume)
    return sound.play()

def play_dash_sound():
    #  버스트업 스킬이 있으면 bustup.wav 재생
    if acceleration_skill_level > 0:  # 버스트업 스킬 레벨이 1 이상이면
        try:
            play_sound_with_volume(SOUND_BURST_UP)
        except:
            play_sound_with_volume(SOUND_DASH)  # bustup.wav가 없으면 기본 대쉬 사운드 재생
    else:
        play_sound_with_volume(SOUND_DASH)

