# 코만도 패들 이미지 생성 (고퀄리티 개선 버전)


def create_soldier_paddle_surface(
    step_phase: float = 0.0,
    swing_strength: float = 0.0,
    right_hook_strength: float = 0.0,
    *,
    include_right_arm: bool = True,
) -> pygame.Surface:
    surface = pygame.Surface((320, 108), pygame.SRCALPHA)
    block = 7
    center_x = surface.get_width() // 2
    torso_base_y = 48

    # 내부 헬퍼 함수 정의
    def rotate_point(origin: tuple[float, float], point: tuple[float, float], degrees: float) -> tuple[float, float]:
        """주어진 점을 화면 좌표계 기준으로 시계 방향 회전"""
        radians = math.radians(degrees)
        cos_v = math.cos(radians)
        sin_v = math.sin(radians)
        ox, oy = origin
        px, py = point
        translated_x = px - ox
        translated_y = py - oy
        rotated_x = translated_x * cos_v - translated_y * sin_v
        rotated_y = translated_x * sin_v + translated_y * cos_v
        return ox + rotated_x, oy + rotated_y

    def lerp_point(start: tuple[float, float], end: tuple[float, float], t: float) -> tuple[float, float]:
        return start[0] + (end[0] - start[0]) * t, start[1] + (end[1] - start[1]) * t

    def to_int_point(point: tuple[float, float]) -> tuple[int, int]:
        return int(round(point[0])), int(round(point[1]))

    phase = _resolve_mecha_phase(step_phase)
    wave = math.sin(phase * math.tau)
    torso_bob = int(math.sin(phase * math.tau) * 2)
    arm_sway = int(wave * 4)
    shoulder_shift = int(wave * 2)
    hip_sway = int(wave * 2)
    left_leg_lift = -int(max(0.0, wave) * 3)
    right_leg_lift = -int(max(0.0, -wave) * 3)

    torso_y = torso_base_y + torso_bob
    swing_strength = max(0.0, min(1.0, swing_strength))
    right_hook_strength = max(0.0, min(1.0, right_hook_strength))

    palette = {
        "helmet_base": (78, 108, 68),
        "helmet_shadow": (46, 66, 40),
        "helmet_high": (148, 180, 110),
        "goggle_strap": (52, 62, 72),
        "pack_dark": (60, 76, 48),
        "pack_light": (110, 134, 86),
        "face": (214, 188, 158),
        "skin_shadow": (178, 150, 126),
        "uniform_mid": (94, 116, 74),
        "uniform_dark": (72, 90, 58),
        "uniform_light": (140, 168, 112),
        "trim": (186, 204, 142),
        "accent": (208, 220, 156),
        "strap": (74, 54, 36),
        "strap_high": (108, 78, 50),
        "plate": (66, 82, 54),
        "plate_high": (118, 142, 96),
        "belt": (92, 62, 40),
        "belt_high": (130, 94, 60),
        "paddle_face": (220, 58, 50),
        "paddle_core": (244, 198, 164),
        "paddle_grip": (98, 60, 40),
        "arm": (124, 108, 74),
        "arm_shadow": (96, 84, 54),
        "glove": (206, 182, 150),
        "glove_shadow": (172, 144, 118),
        "pants": (98, 122, 80),
        "pants_shadow": (80, 98, 68),
        "boot": (62, 48, 34),
        "boot_high": (110, 90, 68),
        "kneepad": (112, 130, 92),
        "kneepad_trim": (178, 190, 146),
    }

    upper_camo = [(94, 118, 78), (82, 102, 68), (120, 142, 92)]
    lower_camo = [(88, 110, 74), (74, 92, 62), (104, 128, 84)]

    def draw_camo_rect(rect: pygame.Rect, base_color, overlays, density=0.32, target=None):
        target_surface = surface if target is None else target
        pygame.draw.rect(target_surface, base_color, rect, border_radius=rect.width if rect.height < 4 else 0)
        if rect.width < 3 or rect.height < 2:
            return
        patches = max(1, int(rect.width * rect.height * density / 90))
        for _ in range(patches):
            patch_w = random.randint(3, min(7, rect.width))
            patch_h = random.randint(2, min(5, rect.height))
            x = random.randint(rect.left, rect.right - patch_w)
            y = random.randint(rect.top, rect.bottom - patch_h)
            pygame.draw.rect(target_surface, random.choice(overlays), pygame.Rect(x, y, patch_w, patch_h))

    def to_int_point(point: tuple[float, float]) -> tuple[int, int]:
        return int(round(point[0])), int(round(point[1]))

    def draw_tapered_camo(rect: pygame.Rect, base_color, overlays, taper_top: int, taper_bottom: int, density=0.32):
        """Draw a trapezoidal camo block to keep the waist silhouette natural."""
        local = pygame.Surface(rect.size, pygame.SRCALPHA)
        draw_camo_rect(pygame.Rect(0, 0, rect.width, rect.height), base_color, overlays, density=density, target=local)
        mask = pygame.Surface(rect.size, pygame.SRCALPHA)
        polygon = [
            (taper_top, 0),
            (rect.width - taper_top, 0),
            (rect.width - taper_bottom, rect.height),
            (taper_bottom, rect.height),
        ]
        pygame.draw.polygon(mask, (255, 255, 255, 255), polygon)
        local.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        surface.blit(local, rect.topleft)
        outline = [
            (rect.left + taper_top, rect.top),
            (rect.right - taper_top, rect.top),
            (rect.right - taper_bottom, rect.bottom),
            (rect.left + taper_bottom, rect.bottom),
        ]
        pygame.draw.lines(surface, palette["trim"], True, outline, 1)

    helmet_rect = pygame.Rect(center_x - int(2.6 * block), torso_y - int(3.5 * block), int(5.4 * block), int(2.8 * block))
    pygame.draw.ellipse(surface, palette["helmet_shadow"], helmet_rect)
    pygame.draw.ellipse(surface, palette["helmet_base"], helmet_rect.inflate(-int(0.6 * block), -int(0.4 * block)))
    pygame.draw.arc(surface, palette["helmet_high"], helmet_rect.inflate(-int(0.4 * block), -int(0.4 * block)), math.radians(210), math.radians(330), 2)

    back_panel = helmet_rect.inflate(-int(0.8 * block), -int(0.6 * block))
    pygame.draw.ellipse(surface, palette["helmet_base"], back_panel)
    pygame.draw.ellipse(surface, palette["helmet_high"], back_panel.inflate(-int(0.6 * block), -int(0.6 * block)), 1)

    strap_rect = pygame.Rect(center_x - int(2.4 * block), helmet_rect.centery - int(0.25 * block), int(4.8 * block), int(0.5 * block))
    pygame.draw.rect(surface, palette["goggle_strap"], strap_rect, border_radius=3)
    pygame.draw.rect(surface, palette["helmet_high"], strap_rect.inflate(-2, -2), 1, border_radius=3)

    pack_rect = pygame.Rect(center_x - int(2.1 * block), torso_y - int(0.1 * block), int(4.2 * block), int(2.4 * block))
    draw_camo_rect(pack_rect, palette["pack_dark"], upper_camo, density=0.28)
    flap_rect = pygame.Rect(pack_rect.left + int(0.2 * block), pack_rect.top + int(0.2 * block), pack_rect.width - int(0.4 * block), int(0.9 * block))
    pygame.draw.rect(surface, palette["pack_light"], flap_rect, border_radius=4)
    pygame.draw.line(surface, palette["trim"], (flap_rect.left + 3, flap_rect.bottom - 2), (flap_rect.right - 3, flap_rect.bottom - 2), 1)

    torso_width = int(6.0 * block)
    torso_height = int(2.6 * block)
    torso_rect = pygame.Rect(center_x - torso_width // 2, torso_y - int(0.4 * block), torso_width, torso_height)
    top_taper = int(0.4 * block)
    waist_taper = int(1.1 * block)
    draw_tapered_camo(torso_rect, palette["uniform_mid"], upper_camo, top_taper, waist_taper)

    plate_rect = pygame.Rect(center_x - int(2.8 * block), torso_rect.top + int(0.45 * block), int(5.6 * block), int(1.3 * block))
    pygame.draw.rect(surface, palette["plate"], plate_rect, border_radius=6)
    pygame.draw.rect(surface, palette["plate_high"], plate_rect.inflate(-int(0.45 * block), -int(0.25 * block)), 1, border_radius=5)

    molle_spacing = int(0.75 * block)
    for row in range(2):
        strap_y = plate_rect.top + int(0.35 * block) + row * molle_spacing
        pygame.draw.line(surface, palette["strap_high"], (plate_rect.left + int(0.6 * block), strap_y), (plate_rect.right - int(0.6 * block), strap_y), 2)

    pocket_size = (int(1.6 * block), int(0.7 * block))
    for offset in (-int(2.15 * block), int(0.55 * block)):
        pocket = pygame.Rect(center_x + offset, torso_rect.top + int(0.85 * block), *pocket_size)
        draw_camo_rect(pocket, palette["uniform_mid"], upper_camo, density=0.25)
        pygame.draw.rect(surface, palette["accent"], pocket, 1, border_radius=3)

    strap_width = int(0.7 * block)
    for offset in (-int(3.0 * block), int(2.4 * block)):
        strap = pygame.Rect(center_x + offset, torso_rect.top + int(0.05 * block), strap_width, torso_height - int(0.1 * block))
        pygame.draw.rect(surface, palette["strap"], strap, border_radius=4)
        pygame.draw.rect(surface, palette["strap_high"], strap.inflate(-int(0.25 * block), -int(0.3 * block)), 1, border_radius=3)

    rank_patch = pygame.Rect(center_x + int(2.8 * block), torso_rect.top + int(0.1 * block), int(1.0 * block), int(1.0 * block))
    pygame.draw.rect(surface, palette["uniform_light"], rank_patch, border_radius=2)
    pygame.draw.line(surface, palette["trim"], rank_patch.midleft, rank_patch.midright, 1)

    belt_rect = pygame.Rect(center_x - int(3.4 * block), torso_rect.bottom - int(0.15 * block), int(6.8 * block), int(0.7 * block))
    pygame.draw.rect(surface, palette["belt"], belt_rect, border_radius=4)
    pygame.draw.rect(surface, palette["belt_high"], belt_rect.inflate(-int(0.6 * block), -int(0.2 * block)), border_radius=3)

    left_shoulder = (center_x - int(3.0 * block), torso_y + shoulder_shift - 1)
    left_elbow_point = (
        left_shoulder[0] - int(1.85 * block) - arm_sway,
        torso_y - int(0.15 * block) - arm_sway // 3,
    )
    left_wrist_point = (
        left_elbow_point[0] - int(1.65 * block),
        torso_y - int(0.68 * block) - arm_sway,
    )
    upper_arm_rect = pygame.Rect(left_shoulder[0] - int(1.0 * block), torso_y - int(0.25 * block), int(1.8 * block), int(1.7 * block))
    draw_camo_rect(upper_arm_rect, palette["uniform_mid"], upper_camo, density=0.22)
    if swing_strength > 0:
        elbow_target = rotate_point(left_shoulder, left_elbow_point, -58.0)
        wrist_target = rotate_point(left_elbow_point, left_wrist_point, -82.0)
        wrist_target = (wrist_target[0] - swing_strength * 0.68 * block, wrist_target[1] - swing_strength * 0.6 * block)
        left_elbow_point = lerp_point(left_elbow_point, elbow_target, swing_strength)
        left_wrist_point = lerp_point(left_wrist_point, wrist_target, swing_strength)

    left_elbow = to_int_point(left_elbow_point)
    left_wrist = to_int_point(left_wrist_point)
    pygame.draw.line(surface, palette["arm_shadow"], left_shoulder, left_elbow, block)
    pygame.draw.line(surface, palette["arm"], left_shoulder, left_elbow, block - 2)
    pygame.draw.line(surface, palette["arm_shadow"], left_elbow, left_wrist, block - 1)
    pygame.draw.line(surface, palette["arm"], left_elbow, left_wrist, block - 3)
    pygame.draw.circle(surface, palette["glove"], left_wrist, max(2, block // 2))
    pygame.draw.circle(surface, palette["glove_shadow"], left_wrist, max(1, block // 2 - 1), 1)

    paddle_rect = pygame.Rect(left_wrist[0] - int(2.1 * block), left_wrist[1] - int(1.9 * block), int(3.6 * block), int(2.6 * block))
    pygame.draw.ellipse(surface, palette["paddle_face"], paddle_rect)
    pygame.draw.ellipse(surface, palette["paddle_core"], paddle_rect.inflate(-int(0.4 * block), -int(0.4 * block)))
    grip_rect = pygame.Rect(left_wrist[0] - int(0.4 * block), left_wrist[1] - int(0.12 * block), int(0.8 * block), int(1.35 * block))
    pygame.draw.rect(surface, palette["paddle_grip"], grip_rect, border_radius=2)

    if include_right_arm:
        right_shoulder = (center_x + int(3.05 * block), torso_y - shoulder_shift - 1)
        right_elbow_point: list[float] = [
            right_shoulder[0] + int(2.55 * block) + arm_sway // 2,
            torso_y - int(0.32 * block) - arm_sway // 3,
        ]
        right_wrist_point: list[float] = [
            right_elbow_point[0] - int(1.45 * block),
            right_elbow_point[1] - int(1.65 * block),
        ]

        if right_hook_strength > 0.0:
            if soldier_right_hook_phase == 0.0:
                print("[DEBUG] Soldier hook frame start")
            progress = soldier_right_hook_phase
            hook = right_hook_strength

            windup = max(0.0, min(1.0, progress / 0.45))
            release = max(0.0, min(1.0, (progress - 0.45) / 0.55))
            extension = pow(min(1.0, progress * 1.6), 0.8)

            windup_elbow = (
                right_shoulder[0] - (1.2 + 0.5 * windup) * block,
                torso_y - (0.6 + 1.3 * windup) * block,
            )
            windup_wrist = (
                right_shoulder[0] - (1.8 + 1.0 * windup) * block,
                torso_y - (0.9 + 1.6 * windup) * block,
            )

            release_elbow = (
                right_shoulder[0] + (2.2 + 1.1 * release) * block,
                torso_y - (0.05 + 0.4 * release) * block,
            )
            release_wrist = (
                right_shoulder[0] + (4.2 + 1.6 * release) * block,
                torso_y - (0.3 + 0.2 * release) * block,
            )

            elbow_target = (
                windup_elbow[0] * (1.0 - release) + release_elbow[0] * release,
                windup_elbow[1] * (1.0 - release) + release_elbow[1] * release,
            )
            wrist_target = (
                windup_wrist[0] * (1.0 - release) + release_wrist[0] * release,
                windup_wrist[1] * (1.0 - release) + release_wrist[1] * release,
            )

            elbow_target = (
                elbow_target[0] + (right_shoulder[0] - elbow_target[0]) * (1.0 - extension) * 0.15,
                elbow_target[1] - extension * 0.35 * block,
            )
            wrist_target = (
                wrist_target[0] + (right_shoulder[0] - wrist_target[0]) * (1.0 - extension) * 0.2,
                wrist_target[1] - extension * 0.25 * block,
            )

            blend = min(1.0, progress * 2.0)
            right_elbow_point[0] += (elbow_target[0] - right_elbow_point[0]) * blend
            right_elbow_point[1] += (elbow_target[1] - right_elbow_point[1]) * blend
            right_wrist_point[0] += (wrist_target[0] - right_wrist_point[0]) * blend
            right_wrist_point[1] += (wrist_target[1] - right_wrist_point[1]) * blend

            swing_angle = -(28.0 * windup) + (34.0 * release)
            rotated_elbow = rotate_point(right_shoulder, tuple(right_elbow_point), swing_angle)
            right_elbow_point[0], right_elbow_point[1] = rotated_elbow

            wrist_angle = swing_angle + 22.0 * release - 10.0 * windup
            rotated_wrist = rotate_point(tuple(right_elbow_point), tuple(right_wrist_point), wrist_angle)
            right_wrist_point[0], right_wrist_point[1] = rotated_wrist

            if hook > 0.08:
                swoosh_surface = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
                sweep_tail = rotate_point(
                    right_shoulder,
                    (
                        right_shoulder[0] + 3.6 * block,
                        torso_y - 0.1 * block,
                    ),
                    -(65.0 * release + 20.0 * windup),
                )
                sweep_mid = (
                    (right_elbow_point[0] + sweep_tail[0]) / 2,
                    (right_elbow_point[1] + sweep_tail[1]) / 2,
                )
                trail_points = [
                    to_int_point(right_shoulder),
                    to_int_point(sweep_tail),
                    to_int_point(tuple(right_wrist_point)),
                    to_int_point(sweep_mid),
                ]
                swoosh_alpha = int(135 * min(1.0, extension * 1.4))
                pygame.draw.polygon(
                    swoosh_surface,
                    (210, 180, 130, swoosh_alpha),
                    trail_points,
                )
                pygame.draw.polygon(
                    swoosh_surface,
                    (245, 225, 190, max(60, swoosh_alpha // 2)),
                    trail_points,
                    width=2,
                )
                surface.blit(swoosh_surface, (0, 0))

        sleeve_rect = pygame.Rect(right_shoulder[0] - int(0.65 * block), torso_y - int(0.25 * block), int(1.6 * block), int(1.5 * block))
        draw_camo_rect(sleeve_rect, palette["uniform_mid"], upper_camo, density=0.22)
        right_elbow = to_int_point(tuple(right_elbow_point))
        right_wrist = to_int_point(tuple(right_wrist_point))
        pygame.draw.line(surface, palette["arm_shadow"], right_shoulder, right_elbow, block + 1)
        pygame.draw.line(surface, palette["arm"], right_shoulder, right_elbow, block - 1)
        pygame.draw.line(surface, palette["arm_shadow"], right_elbow, right_wrist, block)
        pygame.draw.line(surface, palette["arm"], right_elbow, right_wrist, block - 2)
        forearm_guard = pygame.Rect(min(right_elbow[0], right_wrist[0]) - int(0.5 * block), right_wrist[1] - int(0.4 * block), int(1.1 * block), int(2.2 * block))
        pygame.draw.rect(surface, palette["strap"], forearm_guard, border_radius=4)
        pygame.draw.rect(surface, palette["strap_high"], forearm_guard.inflate(-2, -3), 1, border_radius=3)
        pygame.draw.circle(surface, palette["glove"], right_wrist, max(3, block // 2 + 1))
        pygame.draw.circle(surface, palette["glove_shadow"], right_wrist, max(2, block // 2), 1)
        knuckle_rect = pygame.Rect(right_wrist[0] - int(0.5 * block), right_wrist[1] - int(0.35 * block), int(1.0 * block), int(0.6 * block))
        pygame.draw.rect(surface, palette["strap_high"], knuckle_rect, border_radius=3)

    hip_y = torso_y + int(2.15 * block)
    hip_rect = pygame.Rect(center_x - int(3.2 * block) + hip_sway, hip_y, int(6.4 * block), int(0.85 * block))
    draw_tapered_camo(hip_rect, palette["pants"], lower_camo, int(0.5 * block), int(0.9 * block), density=0.3)
    pygame.draw.ellipse(surface, palette["pants_shadow"], hip_rect.inflate(-int(1.4 * block), int(0.6 * block)))

    thigh_width = int(1.5 * block)
    thigh_height = int(2.4 * block)
    leg_spacing = int(2.1 * block)
    left_leg_x = center_x - leg_spacing + hip_sway
    right_leg_x = center_x + leg_spacing + hip_sway

    left_thigh = pygame.Rect(left_leg_x - thigh_width // 2, hip_y + left_leg_lift, thigh_width, thigh_height)
    right_thigh = pygame.Rect(right_leg_x - thigh_width // 2, hip_y + right_leg_lift, thigh_width, thigh_height)
    draw_camo_rect(left_thigh, palette["pants"], lower_camo, density=0.3)
    draw_camo_rect(right_thigh, palette["pants"], lower_camo, density=0.3)

    calf_height = int(1.15 * block)
    left_calf = pygame.Rect(left_thigh.left + int(0.1 * block), left_thigh.bottom - 1, left_thigh.width - int(0.2 * block), calf_height)
    right_calf = pygame.Rect(right_thigh.left + int(0.1 * block), right_thigh.bottom - 1, right_thigh.width - int(0.2 * block), calf_height)
    draw_camo_rect(left_calf, palette["pants"], lower_camo, density=0.28)
    draw_camo_rect(right_calf, palette["pants"], lower_camo, density=0.28)

    kneepad_height = max(6, int(0.75 * block))
    for calf in (left_calf, right_calf):
        pad_rect = pygame.Rect(calf.left, calf.top + int(0.2 * block), calf.width, kneepad_height)
        pygame.draw.rect(surface, palette["kneepad"], pad_rect, border_radius=3)
        pygame.draw.rect(surface, palette["kneepad_trim"], pad_rect.inflate(-2, -2), 1, border_radius=3)

    boot_height = int(1.1 * block)
    left_boot = pygame.Rect(left_calf.left, left_calf.bottom - 1, left_calf.width, boot_height)
    right_boot = pygame.Rect(right_calf.left, right_calf.bottom - 1, right_calf.width, boot_height)
    pygame.draw.rect(surface, palette["boot"], left_boot, border_radius=2)
    pygame.draw.rect(surface, palette["boot"], right_boot, border_radius=2)
    for boot in (left_boot, right_boot):
        pygame.draw.line(surface, palette["boot_high"], (boot.left + 2, boot.top + 2), (boot.right - 2, boot.top + 2), 1)
        sole_rect = pygame.Rect(boot.left, boot.bottom - 2, boot.width, 2)
        pygame.draw.rect(surface, palette["boot_high"], sole_rect)

    return surface


SOLDIER_PADDLE_IMG = create_soldier_paddle_surface()
SOLDIER_PADDLE_IMG_NO_RIGHT_ARM = create_soldier_paddle_surface(include_right_arm=False)


def _crop_surface_alpha(surface: pygame.Surface) -> pygame.Surface:
    """알파 채널 기준으로 내용 영역만 잘라 반환."""
    rect = surface.get_bounding_rect(min_alpha=1)
    if rect.width == 0 or rect.height == 0:
        return surface.copy()
    return surface.subsurface(rect).copy()


def get_soldier_right_hook_strength() -> float:
    global soldier_right_hook_phase
    if not soldier_right_hook_active or SOLDIER_RIGHT_HOOK_DURATION <= 0 or soldier_right_hook_timer <= 0:
        soldier_right_hook_phase = 0.0
        return 0.0
    progress = 1.0 - (soldier_right_hook_timer / SOLDIER_RIGHT_HOOK_DURATION)
    progress = max(0.0, min(1.0, progress))
    soldier_right_hook_phase = progress
    base = math.sin(progress * math.pi)
    strength = max(0.0, min(1.0, base ** 0.75))
    if strength > 0:
        print(f"[DEBUG] Soldier hook strength: progress={progress:.2f}, strength={strength:.2f}, timer={soldier_right_hook_timer}")
    return strength


BLACKSMITH_CENTER_X = 122
BLACKSMITH_CENTER_Y = 44
BLACKSMITH_SCALE = 0.8
BLACKSMITH_LEFT_LEG_X = BLACKSMITH_CENTER_X - 12
BLACKSMITH_RIGHT_LEG_X = BLACKSMITH_CENTER_X + 12
BLACKSMITH_HIP_Y = BLACKSMITH_CENTER_Y + 20
BLACKSMITH_LEG_LENGTH = 15
BLACKSMITH_BASELINE_Y = BLACKSMITH_HIP_Y + BLACKSMITH_LEG_LENGTH + 6
BLACKSMITH_BASELINE_OFFSET = 10  # 스케일 후 추가로 내려 붙일 픽셀 오프셋
BLACKSMITH_SHIELD_SHIFT_X = -6  # 팔을 더 뻗어 자연스럽게 방패를 잡도록 하는 오프셋
BLACKSMITH_EMBLEM_RADIUS = 17    # 발토르 엠블럼 표준 반경 (게이지/카드 공유)


def get_blacksmith_emblem_state(time_now=None):
    """발토르 엠블럼 애니메이션 파라미터를 공유한다."""
    if time_now is None:
        time_now = pygame.time.get_ticks()
    pulse_scale = 1.0 + math.sin(time_now * 0.003) * 0.1
    rotation_angle = time_now * 0.001
    glow_intensity = abs(math.sin(time_now * 0.002))
    swing_phase = (math.sin(time_now * 0.004) + 1.0) * 0.5  # 0(복귀)~1(상승)
    rune_pulse = abs(math.sin(time_now * 0.01))
    hammer_angle = -1.05 + swing_phase * 0.45
    return {
        "time": time_now,
        "pulse_scale": pulse_scale,
        "rotation_angle": rotation_angle,
        "glow_intensity": glow_intensity,
        "swing_phase": swing_phase,
        "rune_pulse": rune_pulse,
        "hammer_angle": hammer_angle,
        "hammer_cos": math.cos(hammer_angle),
        "hammer_sin": math.sin(hammer_angle),
    }


def draw_blacksmith_emblem(surface, center_x, center_y, state, *,
                           radius=BLACKSMITH_EMBLEM_RADIUS,
                           gauge_value=None, gauge_max=None,
                           show_gauge_fx=False):
    """발토르 엠블럼 공통 렌더링 (게이지/카드 공용)."""
    pulse_scale = state["pulse_scale"]
    rotation_angle = state["rotation_angle"]
    glow_intensity = state["glow_intensity"]
    swing_phase = state["swing_phase"]
    rune_pulse = state["rune_pulse"]
    cos_a = state["hammer_cos"]
    sin_a = state["hammer_sin"]
    time_now = state["time"]

    scaled_radius = max(1, int(radius * pulse_scale))
    outer_radius = scaled_radius + 2
    outer_color = (230, 170, 110)
    base_color = (70, 45, 35)
    border_color = (200, 130, 75)
    pygame.draw.circle(surface, outer_color, (center_x, center_y), outer_radius)
    pygame.draw.circle(surface, base_color, (center_x, center_y), scaled_radius)
    pygame.draw.circle(surface, border_color, (center_x, center_y), scaled_radius, 3)

    ring_radius = max(4, int((radius - 4) * pulse_scale))
    pygame.draw.circle(surface, (115, 80, 55), (center_x, center_y), ring_radius, 1)

    gear_outer = (radius - 1) * pulse_scale
    gear_inner = gear_outer * 0.72
    tooth_count = 8
    gear_points = []
    for idx in range(tooth_count * 2):
        angle = rotation_angle + idx * math.pi / tooth_count
        length = gear_outer if idx % 2 == 0 else gear_inner
        gear_points.append(
            (
                center_x + math.cos(angle) * length,
                center_y + math.sin(angle) * length
            )
        )
    if gear_points:
        pygame.draw.polygon(surface, (150, 95, 60), gear_points)
        pygame.draw.polygon(surface, (230, 170, 110), gear_points, 2)

    hub_radius = max(2, int(gear_inner * 0.55))
    pygame.draw.circle(surface, (90, 55, 35), (center_x, center_y), hub_radius)
    pygame.draw.circle(surface, (200, 150, 90), (center_x, center_y), hub_radius, 2)

    hammer_pivot = (center_x - 4, center_y + 2)
    handle_length = 13
    handle_end = (
        hammer_pivot[0] + cos_a * handle_length,
        hammer_pivot[1] + sin_a * handle_length,
    )
    pygame.draw.line(surface, (150, 105, 70), hammer_pivot, handle_end, 3)
    pygame.draw.line(surface, (200, 160, 110), hammer_pivot, handle_end, 1)

    wrap_offset = 4
    wrap_center = (
        hammer_pivot[0] + cos_a * wrap_offset,
        hammer_pivot[1] + sin_a * wrap_offset,
    )
    pygame.draw.circle(surface, (195, 150, 95), (int(wrap_center[0]), int(wrap_center[1])), 3)

    head_length = 4
    head_half = 4
    head_center = (
        handle_end[0] + cos_a * head_length * 0.35,
        handle_end[1] + sin_a * head_length * 0.35,
    )
    perp_x = -sin_a
    perp_y = cos_a
    hammer_head_points = [
        (head_center[0] + perp_x * head_half, head_center[1] + perp_y * head_half),
        (head_center[0] - perp_x * head_half, head_center[1] - perp_y * head_half),
        (head_center[0] - perp_x * head_half + cos_a * head_length,
         head_center[1] - perp_y * head_half + sin_a * head_length),
        (head_center[0] + perp_x * head_half + cos_a * head_length,
         head_center[1] + perp_y * head_half + sin_a * head_length),
    ]
    pygame.draw.polygon(surface, (220, 185, 130), hammer_head_points)
    pygame.draw.polygon(surface, (130, 100, 70), hammer_head_points, 1)

    rune_start = (
        head_center[0] + perp_x * (head_half - 0.8),
        head_center[1] + perp_y * (head_half - 0.8),
    )
    rune_end = (
        head_center[0] - perp_x * (head_half - 0.8) + cos_a * (head_length * 0.7),
        head_center[1] - perp_y * (head_half - 0.8) + sin_a * (head_length * 0.7),
    )
    rune_color = (
        int(255 - rune_pulse * 30),
        int(205 - rune_pulse * 50),
        int(125 + rune_pulse * 30),
    )
    pygame.draw.line(surface, rune_color, rune_start, rune_end, 2)

    impact_strength = max(0.0, 0.35 - swing_phase) / 0.35
    if impact_strength > 0:
        impact_point = (center_x + 1, center_y + 4)
        spark_color = (255, 210, 140)
        for i in range(4):
            angle = time_now * 0.02 + i * (math.pi / 2)
            length = 3 + impact_strength * 5
            end_x = impact_point[0] + math.cos(angle) * length
            end_y = impact_point[1] + math.sin(angle) * length
            pygame.draw.line(surface, spark_color, impact_point, (end_x, end_y), 2)
        pygame.draw.circle(surface, (255, 240, 180), (int(impact_point[0]), int(impact_point[1])), 2 + int(impact_strength * 2))

    if show_gauge_fx and gauge_value is not None and gauge_max:
        if gauge_value > gauge_max * 0.5:
            spark_count = 3 if gauge_value < gauge_max else 5
            for i in range(spark_count):
                spark_angle = time_now * 0.015 + i * (math.tau / spark_count)
                spark_radius = radius + 6 + math.sin(time_now * 0.02 + i) * 2
                spark_x = center_x + math.cos(spark_angle) * spark_radius
                spark_y = center_y + math.sin(spark_angle) * spark_radius
                pygame.draw.circle(surface, (255, 200, 120), (int(spark_x), int(spark_y)), 2)

        if gauge_value >= 350:
            forge_ring = int(radius * 1.35 + math.sin(time_now * 0.01) * 2)
            pygame.draw.circle(surface, (255, 210, 140), (center_x, center_y), forge_ring, 1)


def _scale_blacksmith_point(point, scale=BLACKSMITH_SCALE):
    """중심 기준으로 좌표를 축소."""
    cx, cy = BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y
    px, py = point
    return (
        int(round(cx + (px - cx) * scale)),
        int(round(cy + (py - cy) * scale))
    )


def _scale_blacksmith_sprite(surface, anchor, scale=BLACKSMITH_SCALE):
    if abs(scale - 1.0) < 1e-3:
        return surface.copy(), anchor

    scaled_size = (
        max(1, int(round(surface.get_width() * scale))),
        max(1, int(round(surface.get_height() * scale)))
    )
    scaled_surface = pygame.transform.smoothscale(surface, scaled_size)
    result_surface = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    placement_rect = scaled_surface.get_rect(center=(BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))

    scaled_baseline_point = _scale_blacksmith_point(
        (BLACKSMITH_CENTER_X, BLACKSMITH_BASELINE_Y), scale
    )
    baseline_delta = BLACKSMITH_BASELINE_Y - (
        scaled_baseline_point[1] + (placement_rect.centery - BLACKSMITH_CENTER_Y)
    )
    baseline_delta += BLACKSMITH_BASELINE_OFFSET
    placement_rect.y += baseline_delta
    result_surface.blit(scaled_surface, placement_rect)

    scaled_anchor = _scale_blacksmith_point(anchor, scale)
    offset_x = placement_rect.centerx - BLACKSMITH_CENTER_X
    offset_y = placement_rect.centery - BLACKSMITH_CENTER_Y
    scaled_anchor = (scaled_anchor[0] + offset_x, scaled_anchor[1] + offset_y)
    return result_surface, scaled_anchor

SMASHER_CARD_IMG = _crop_surface_alpha(SMASHER_PADDLE_IMG)


def _draw_blacksmith_shield(surface, shield_center, angle_deg=-4):
    """발토르 방패를 별도 서피스로 생성해 손에 붙인다."""

    shield_surface = pygame.Surface((88, 110), pygame.SRCALPHA)
    pivot_x = shield_surface.get_width() // 2
    pivot_y = 22

    outer_rect = pygame.Rect(pivot_x - 22, pivot_y - 20, 44, 96)
    pygame.draw.ellipse(shield_surface, (66, 70, 78), outer_rect)
    pygame.draw.ellipse(shield_surface, (140, 148, 160), outer_rect, width=4)

    middle_rect = outer_rect.inflate(-6, -12)
    pygame.draw.ellipse(shield_surface, (95, 102, 120), middle_rect)
    pygame.draw.ellipse(shield_surface, (55, 60, 74), middle_rect, width=3)

    boss_rect = middle_rect.inflate(-10, -26)
    pygame.draw.ellipse(shield_surface, (210, 170, 80), boss_rect)
    pygame.draw.ellipse(shield_surface, (120, 90, 40), boss_rect.inflate(-6, -10))

    pygame.draw.line(shield_surface, (225, 200, 120), (pivot_x, middle_rect.top + 6), (pivot_x, middle_rect.bottom - 8), 2)
    pygame.draw.line(shield_surface, (225, 200, 120), (middle_rect.left + 8, pivot_y + 2), (middle_rect.right - 8, pivot_y + 2), 2)

    rivet_rx = (outer_rect.width // 2) - 4
    rivet_ry = (outer_rect.height // 2) - 10
    for i in range(6):
        rad = i * (math.pi / 3)
        rx = pivot_x + int(math.cos(rad) * rivet_rx)
        ry = pivot_y + int(math.sin(rad) * rivet_ry)
        pygame.draw.circle(shield_surface, (180, 186, 198), (rx, ry), 3)
        pygame.draw.circle(shield_surface, (120, 130, 142), (rx, ry), 1)

    strap_rect = pygame.Rect(pivot_x - 6, pivot_y - 18, 12, 36)
    pygame.draw.rect(shield_surface, (70, 42, 28), strap_rect, border_radius=4)
    pygame.draw.rect(shield_surface, (110, 72, 48), strap_rect.inflate(-4, -10), border_radius=3)

    rotated = pygame.transform.rotate(shield_surface, angle_deg)
    surface.blit(rotated, rotated.get_rect(center=shield_center))

def _draw_blacksmith_upper(surface, shield_swing=0.0, hammer_swing=0.0, walk_wave=0.0, walk_bob=0.0, walk_lean=0.0):
    cx = BLACKSMITH_CENTER_X
    cy = BLACKSMITH_CENTER_Y
    shield_amount = max(0.0, min(1.0, shield_swing))
    lift_curve = shield_amount ** 1.1  # 0~1 범위, 후반부에서 더 많이 들어 올리기

    hammer_amount = max(0.0, min(1.0, hammer_swing))
    hammer_prepare_phase = min(1.0, hammer_amount * 1.35)
    hammer_prepare_curve = math.sin(hammer_prepare_phase * (math.pi / 2)) if hammer_prepare_phase > 0 else 0.0
    hammer_release_phase = 0.0
    if hammer_amount > 0.3:
        hammer_release_phase = min(1.0, (hammer_amount - 0.3) / 0.7)
    hammer_release_curve = math.sin(hammer_release_phase * (math.pi / 2)) if hammer_release_phase > 0 else 0.0
    hammer_raise = max(0.0, min(1.0, hammer_prepare_curve))
    hammer_drop = max(0.0, min(1.0, hammer_release_curve))

    # 방패를 들며 몸 쪽으로 끌어당기는 느낌을 위해 팔 좌표 보정
    arm_dx = int(round(-3 * lift_curve))
    arm_dy = int(round(-4 * lift_curve))

    walk_wave = max(-1.0, min(1.0, walk_wave))
    walk_bob = max(-1.0, min(1.0, walk_bob))
    walk_lean = max(-1.0, min(1.0, walk_lean))
    body_bob = int(round(walk_bob * 3))
    lean_push = int(round(walk_lean * 2))
    shoulder_roll = int(round(walk_wave * 2))
    left_arm_offset_x = int(round(-walk_wave * 6)) + lean_push
    right_arm_offset_x = int(round(walk_wave * 6)) + lean_push
    left_arm_offset_y = int(round(-walk_wave * 2))
    right_arm_offset_y = int(round(walk_wave * 2))
    elbow_sway = int(round(-walk_wave))
    wrist_pitch = int(round(walk_wave * 3))

    head_top = cy - 26 + body_bob
    torso_y = cy - 2 + body_bob
    shoulder_span = 46

    # 뒤통수 머리와 헬멧 베이스
    pygame.draw.ellipse(surface, (70, 48, 28), (cx - 20, head_top + 6, 40, 32))
    pygame.draw.ellipse(surface, (148, 158, 170), (cx - 16, head_top, 32, 24))

    # 바이킹 헬멧 장식
    pygame.draw.rect(surface, (110, 120, 135), (cx - 18, head_top + 12, 36, 8), border_radius=3)
    for i in range(4):
        pygame.draw.circle(surface, (210, 210, 215), (cx - 12 + i * 8, head_top + 16), 2)
    left_horn = [(cx - 14, head_top + 6), (cx - 26, head_top + 2), (cx - 32, head_top - 10), (cx - 20, head_top - 14), (cx - 10, head_top - 4)]
    right_horn = [(cx + 14, head_top + 6), (cx + 26, head_top + 2), (cx + 32, head_top - 10), (cx + 20, head_top - 14), (cx + 10, head_top - 4)]
    pygame.draw.polygon(surface, (220, 216, 205), left_horn)
    pygame.draw.polygon(surface, (150, 130, 110), left_horn, 2)
    pygame.draw.polygon(surface, (220, 216, 205), right_horn)
    pygame.draw.polygon(surface, (150, 130, 110), right_horn, 2)

    # 얼굴과 수염
    face_rect = pygame.Rect(cx - 11, head_top + 10, 22, 16)
    pygame.draw.ellipse(surface, (212, 192, 162), face_rect)
    pygame.draw.arc(surface, (90, 70, 55), (cx - 10, head_top + 12, 20, 10), math.pi, 2 * math.pi, 2)
    nose = [(cx - 2, head_top + 16), (cx, head_top + 10), (cx + 2, head_top + 16)]
    pygame.draw.polygon(surface, (198, 168, 138), nose)
    beard_poly = [
        (cx - 18, head_top + 20), (cx - 16, head_top + 32), (cx - 10, head_top + 40),
        (cx, head_top + 46), (cx + 10, head_top + 40), (cx + 16, head_top + 32), (cx + 18, head_top + 20)
    ]
    pygame.draw.polygon(surface, (120, 70, 35), beard_poly)
    for braid_offset in (-8, 8):
        braid_top = head_top + 28
        pygame.draw.ellipse(surface, (105, 60, 30), (cx + braid_offset - 3, braid_top, 6, 10))
        pygame.draw.ellipse(surface, (150, 95, 55), (cx + braid_offset - 2, braid_top + 6, 4, 8))
    pygame.draw.line(surface, (70, 45, 25), (cx - 8, head_top + 32), (cx - 6, head_top + 38), 2)
    pygame.draw.line(surface, (70, 45, 25), (cx + 8, head_top + 32), (cx + 6, head_top + 38), 2)

    pygame.draw.polygon(surface, (96, 74, 52), [
        (cx - shoulder_span, torso_y + 6 - shoulder_roll),
        (cx - 22 + lean_push // 2, torso_y - 10 - shoulder_roll),
        (cx + 22 + lean_push // 2, torso_y - 10 + shoulder_roll),
        (cx + shoulder_span, torso_y + 6 + shoulder_roll),
        (cx + 30 + lean_push, torso_y + 28),
        (cx - 30 + lean_push, torso_y + 28)
    ])

    # 겹겹이 입은 갑옷과 앞치마
    pygame.draw.rect(surface, (140, 145, 155), (cx - 18 + lean_push, torso_y - 2, 36, 26), border_radius=6)
    pygame.draw.rect(surface, (85, 62, 42), (cx - 24 + lean_push, torso_y + 12, 48, 22), border_radius=6)
    pygame.draw.rect(surface, (55, 40, 28), (cx - 20 + lean_push, torso_y + 18, 40, 18), border_radius=4)
    pygame.draw.arc(surface, (215, 200, 150), (cx - 22 + lean_push, torso_y + 10, 44, 22), math.pi, 2 * math.pi, 2)
    pygame.draw.line(surface, (70, 48, 32), (cx + lean_push, torso_y + 18), (cx + lean_push, torso_y + 32), 2)
    pygame.draw.circle(surface, (180, 180, 170), (cx - 26 + lean_push - shoulder_roll, torso_y + 6 - shoulder_roll), 6)
    pygame.draw.circle(surface, (180, 180, 170), (cx + 26 + lean_push + shoulder_roll, torso_y + 6 + shoulder_roll), 6)

    # === 왼팔과 방패 ===
    left_arm_x = cx - 20 + BLACKSMITH_SHIELD_SHIFT_X + arm_dx + left_arm_offset_x
    left_arm_y = torso_y - 10 + arm_dy + left_arm_offset_y
    elbow_x = left_arm_x - 8 + elbow_sway
    elbow_y = left_arm_y - 4 - elbow_sway

    arm_points = [
        (cx - 34 + arm_dx + left_arm_offset_x, torso_y - 4 + arm_dy + left_arm_offset_y),
        (cx - 36 + arm_dx + left_arm_offset_x, torso_y + 2 + arm_dy + left_arm_offset_y),
        (elbow_x - 4, elbow_y + 4),
        (elbow_x - 1, elbow_y - 4),
        (left_arm_x - 2, left_arm_y - 10),
        (left_arm_x + 4, left_arm_y - 14),
        (left_arm_x + 6, left_arm_y - 4),
        (cx - 24 + arm_dx + left_arm_offset_x, torso_y - 10 + arm_dy + left_arm_offset_y)
    ]
    pygame.draw.polygon(surface, (132, 108, 82), arm_points)

    # 팔 음영
    pygame.draw.polygon(surface, (115, 95, 65), [
        (elbow_x - 2, elbow_y - 2),
        (left_arm_x - 1, left_arm_y - 8),
        (left_arm_x + 4, left_arm_y - 2),
        (elbow_x + 3, elbow_y + 4)
    ])

    # 손 (더 정교하게)
    hand_rect = pygame.Rect(left_arm_x - 6, left_arm_y - 12, 14, 10)
    pygame.draw.ellipse(surface, (205, 185, 155), hand_rect)
    pygame.draw.ellipse(surface, (188, 168, 138), hand_rect.inflate(-2, -2))

    shield_forward = int(round(20 * lift_curve))
    shield_lift = int(round(12 * lift_curve))
    shield_diagonal_shift = int(round(8 * lift_curve))
    shield_center = (
        left_arm_x - 20 + shield_forward + shield_diagonal_shift + int(round(left_arm_offset_x * 0.3)),
        left_arm_y + 22 - shield_lift - shield_diagonal_shift + int(round(-walk_wave * 4))
    )
    swing_angle = -12 - 80 * lift_curve + walk_wave * 8 + lean_push * 2
    _draw_blacksmith_shield(surface, shield_center, angle_deg=swing_angle)

    # 오른팔과 망치 - 이동 시 자연스러운 기합 자세 유지
    hammer_arm_backward = int(round(18 * hammer_raise))
    hammer_arm_forward_hit = int(round(46 * hammer_drop))
    hammer_arm_forward = hammer_arm_forward_hit - hammer_arm_backward
    hammer_arm_drop = int(round(6 * hammer_raise)) + int(round(28 * hammer_drop))
    hammer_shoulder_lift = int(round(14 * hammer_raise))
    hammer_shoulder_dip = int(round(10 * hammer_drop))
    hammer_forward_twist = int(round(14 * hammer_drop))

    right_shoulder = (
        cx + 28 + hammer_forward_twist - hammer_arm_forward + right_arm_offset_x + lean_push,
        torso_y - hammer_shoulder_lift + hammer_shoulder_dip + right_arm_offset_y // 2 - shoulder_roll
    )
    right_elbow = (
        cx + 46 + hammer_forward_twist - hammer_arm_forward + right_arm_offset_x + lean_push,
        torso_y + 12 - int(round(8 * hammer_raise)) + hammer_arm_drop // 2 + right_arm_offset_y // 2
    )
    right_wrist = (
        cx + 56 + hammer_forward_twist - hammer_arm_forward // 2 + right_arm_offset_x + lean_push,
        torso_y + 24 - int(round(8 * hammer_raise)) + hammer_arm_drop + right_arm_offset_y + wrist_pitch + int(round(12 * hammer_drop))
    )
    pygame.draw.polygon(surface, (132, 108, 82), [
        (right_shoulder[0] - 6, right_shoulder[1] + 2),
        (right_elbow[0] - 10, right_elbow[1] - 2),
        (right_elbow[0] - 2, right_elbow[1] + 6),
        (right_shoulder[0] + 6, right_shoulder[1] + 8)
    ])
    pygame.draw.polygon(surface, (122, 98, 72), [
        (right_elbow[0] - 2, right_elbow[1] + 4),
        (right_wrist[0] - 6, right_wrist[1] + 2),
        (right_wrist[0] + 12, right_wrist[1] + 6),
        (right_elbow[0] + 4, right_elbow[1])
    ])
    pygame.draw.circle(surface, (205, 185, 155), (right_wrist[0] + 6, right_wrist[1] + 4), 6)

    hammer_ax = right_wrist[0] + 6 - int(round(10 * hammer_raise)) + int(round(16 * hammer_drop))

    grip_ratio = 0.5
    pivot = pygame.math.Vector2(right_wrist[0] + 6, right_wrist[1] + 4)
    swing_angle = -math.radians(110) + hammer_drop * math.radians(150)
    swing_angle += hammer_raise * math.radians(10)
    direction_vec = pygame.math.Vector2(math.cos(swing_angle), math.sin(swing_angle))
    if direction_vec.length_squared() == 0:
        direction_vec = pygame.math.Vector2(0, -1)
    forward_vec = direction_vec.normalize()
    perp_vec = pygame.math.Vector2(-forward_vec.y, forward_vec.x)

    handle_length = 46
    handle_half_width = 5
    top_offset = handle_length * (1.0 - grip_ratio)
    bottom_offset = handle_length * grip_ratio
    handle_top = pivot + forward_vec * top_offset
    handle_bottom_point = pivot - forward_vec * bottom_offset
    handle_dir = handle_bottom_point - handle_top
    if handle_dir.length_squared() == 0:
        handle_dir = pygame.math.Vector2(0, 1)
    handle_dir = handle_dir.normalize()

    if blacksmith_hammer_available or blacksmith_hammer_shock_charging:
        handle_poly = [
            _vec_to_int_pair(handle_top + perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_bottom_point - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_bottom_point + perp_vec * handle_half_width),
        ]
        pygame.draw.polygon(surface, (90, 60, 36), handle_poly)

        detail_poly = [
            _vec_to_int_pair(handle_top + perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_top - perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_bottom_point - perp_vec * (handle_half_width - 2)),
            _vec_to_int_pair(handle_bottom_point + perp_vec * (handle_half_width - 2)),
        ]
        pygame.draw.polygon(surface, (60, 35, 18), detail_poly, width=0)

        for stripe_pos in range(6, int(handle_length), 6):
            stripe_center = handle_top + handle_dir * stripe_pos
            stripe_start = _vec_to_int_pair(stripe_center - perp_vec * (handle_half_width - 2))
            stripe_end = _vec_to_int_pair(stripe_center + perp_vec * (handle_half_width - 2))
            pygame.draw.line(surface, (110, 82, 52), stripe_start, stripe_end, 2)

        cap_length = 10
        cap_vec = forward_vec * cap_length
        cap_poly = [
            _vec_to_int_pair(handle_top + perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top + cap_vec - perp_vec * handle_half_width),
            _vec_to_int_pair(handle_top + cap_vec + perp_vec * handle_half_width),
        ]
        pygame.draw.polygon(surface, (112, 76, 48), cap_poly)

        head_offset_along = 20
        head_center = handle_top + forward_vec * head_offset_along
        head_half_long = 20
        head_half_short = 11
        head_long_vec = perp_vec * head_half_long
        head_short_vec = forward_vec * head_half_short
        head_corners = [
            _vec_to_int_pair(head_center + head_long_vec + head_short_vec),
            _vec_to_int_pair(head_center - head_long_vec + head_short_vec),
            _vec_to_int_pair(head_center - head_long_vec - head_short_vec),
            _vec_to_int_pair(head_center + head_long_vec - head_short_vec),
        ]
        pygame.draw.polygon(surface, (176, 182, 196), head_corners)

        inner_scale = 0.7
        inner_center = head_center - forward_vec * 2
        inner_long_vec = head_long_vec * inner_scale
        inner_short_vec = head_short_vec * inner_scale
        inner_corners = [
            _vec_to_int_pair(inner_center + inner_long_vec + inner_short_vec),
            _vec_to_int_pair(inner_center - inner_long_vec + inner_short_vec),
            _vec_to_int_pair(inner_center - inner_long_vec - inner_short_vec),
            _vec_to_int_pair(inner_center + inner_long_vec - inner_short_vec),
        ]
        pygame.draw.polygon(surface, (210, 215, 228), inner_corners)

        ridge_start = _vec_to_int_pair(head_center - head_long_vec * 0.7 + head_short_vec * 0.6)
        ridge_end = _vec_to_int_pair(head_center + head_long_vec * 0.7 + head_short_vec * 0.6)
        pygame.draw.line(surface, (120, 130, 142), ridge_start, ridge_end, 2)

        spike_tip = head_center + head_long_vec + head_short_vec * 0.1
        spike_poly = [
            _vec_to_int_pair(spike_tip),
            _vec_to_int_pair(spike_tip - head_long_vec * 0.3 + head_short_vec * 0.3),
            _vec_to_int_pair(spike_tip - head_long_vec * 0.3 - head_short_vec * 0.3),
        ]
        pygame.draw.polygon(surface, (140, 155, 168), spike_poly)

        emblem_center = head_center + head_short_vec * 0.1
        pygame.draw.circle(surface, (230, 215, 130), (int(emblem_center.x), int(emblem_center.y)), 5)
        pygame.draw.line(
            surface,
            (240, 160, 60),
            _vec_to_int_pair(emblem_center - head_long_vec * 0.3 - head_short_vec * 0.2),
            _vec_to_int_pair(emblem_center + head_long_vec * 0.3 + head_short_vec * 0.2),
            2,
        )
    else:
        empty_hand = pygame.Rect(0, 0, 10, 18)
        empty_hand.center = (right_wrist[0] + 6, right_wrist[1])
        pygame.draw.ellipse(surface, (205, 185, 155), empty_hand)

    # 어깨 장식
    left_shoulder_center = (cx - 32 + lean_push - shoulder_roll, torso_y + 8 - shoulder_roll)
    right_shoulder_center = (cx + 32 + lean_push + shoulder_roll, torso_y + 8 + shoulder_roll)
    pygame.draw.circle(surface, (195, 200, 210), left_shoulder_center, 7)
    pygame.draw.circle(surface, (195, 200, 210), right_shoulder_center, 7)
    pygame.draw.circle(surface, (110, 120, 135), left_shoulder_center, 3)
    pygame.draw.circle(surface, (110, 120, 135), right_shoulder_center, 3)

def _draw_blacksmith_legs(surface, step=0):
    hip_y = BLACKSMITH_HIP_Y
    leg_len = BLACKSMITH_LEG_LENGTH
    knee_y = hip_y + 7
    base_boot_y = hip_y + leg_len + 2

    left_base = BLACKSMITH_LEFT_LEG_X
    right_base = BLACKSMITH_RIGHT_LEG_X

    sway = max(-8, min(8, step))
    left_sway = -sway
    right_sway = sway

    left_thigh_x = left_base + left_sway // 3
    left_shin_x = left_base + left_sway
    right_thigh_x = right_base + right_sway // 3
    right_shin_x = right_base + right_sway

    left_boot_lift = max(0, left_sway) // 2
    right_boot_lift = max(0, right_sway) // 2
    left_boot_y = base_boot_y - left_boot_lift
    right_boot_y = base_boot_y - right_boot_lift

    # 왼쪽 다리 (앞뒤로 움직임)
    left_thigh = [
        (left_thigh_x - 5, hip_y),
        (left_thigh_x - 6, hip_y + 4),
        (left_thigh_x - 5, knee_y),
        (left_thigh_x + 5, knee_y),
        (left_thigh_x + 6, hip_y + 4),
        (left_thigh_x + 5, hip_y)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), left_thigh)

    left_shin = [
        (left_shin_x - 4, knee_y + 1),
        (left_shin_x - 5, hip_y + leg_len),
        (left_shin_x - 2, left_boot_y + 2),
        (left_shin_x + 2, left_boot_y + 2),
        (left_shin_x + 5, hip_y + leg_len),
        (left_thigh_x + 4, knee_y + 1)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), left_shin)

    pygame.draw.polygon(surface, (68, 52, 36), [
        (left_shin_x - 6, left_boot_y),
        (left_shin_x - 6, left_boot_y + 6),
        (left_shin_x + 6, left_boot_y + 6),
        (left_shin_x + 6, left_boot_y)
    ])

    # 오른쪽 다리 (반대 방향 스윙)
    right_thigh = [
        (right_thigh_x - 5, hip_y),
        (right_thigh_x - 6, hip_y + 4),
        (right_thigh_x - 5, knee_y),
        (right_thigh_x + 5, knee_y),
        (right_thigh_x + 6, hip_y + 4),
        (right_thigh_x + 5, hip_y)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), right_thigh)

    right_shin = [
        (right_shin_x - 4, knee_y + 1),
        (right_shin_x - 5, hip_y + leg_len),
        (right_shin_x - 2, right_boot_y + 2),
        (right_shin_x + 2, right_boot_y + 2),
        (right_shin_x + 5, hip_y + leg_len),
        (right_thigh_x + 4, knee_y + 1)
    ]
    pygame.draw.polygon(surface, (108, 88, 64), right_shin)

    pygame.draw.polygon(surface, (68, 52, 36), [
        (right_shin_x - 6, right_boot_y),
        (right_shin_x - 6, right_boot_y + 6),
        (right_shin_x + 6, right_boot_y + 6),
        (right_shin_x + 6, right_boot_y)
    ])

    # 무릎 보호대와 스타드
    pygame.draw.circle(surface, (150, 130, 110), (left_thigh_x, knee_y + 1), 5)
    pygame.draw.circle(surface, (95, 80, 62), (left_thigh_x, knee_y + 1), 3)
    pygame.draw.circle(surface, (150, 130, 110), (right_thigh_x, knee_y + 1), 5)
    pygame.draw.circle(surface, (95, 80, 62), (right_thigh_x, knee_y + 1), 3)

def create_blacksmith_paddle_base():
    surface = pygame.Surface((250, 120), pygame.SRCALPHA)
    _draw_blacksmith_upper(surface, shield_swing=0.0, hammer_swing=0.0)
    _draw_blacksmith_legs(surface, 0)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface

def create_blacksmith_paddle_walking():
    global blacksmith_walking_timer, blacksmith_walk_direction
    surface = pygame.Surface((250, 120), pygame.SRCALPHA)
    progress = (blacksmith_walking_timer % BLACKSMITH_WALKING_CYCLE) / BLACKSMITH_WALKING_CYCLE
    walk_wave = math.sin(progress * 2 * math.pi)
    walk_bob = math.sin(progress * 2 * math.pi + math.pi / 2)
    walk_lean = blacksmith_walk_direction * 0.6
    _draw_blacksmith_upper(
        surface,
        shield_swing=0.0,
        hammer_swing=0.0,
        walk_wave=walk_wave,
        walk_bob=walk_bob,
        walk_lean=walk_lean,
    )
    step = int(walk_wave * 8)
    _draw_blacksmith_legs(surface, step)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface

def create_blacksmith_paddle_swinging():
    global blacksmith_shield_swing_timer

    surface = pygame.Surface((250, 120), pygame.SRCALPHA)

    if BLACKSMITH_SHIELD_SWING_DURATION > 0:
        progress = 1.0 - (blacksmith_shield_swing_timer / BLACKSMITH_SHIELD_SWING_DURATION)
        progress = max(0.0, min(1.0, progress))
    else:
        progress = 0.0
    swing_amount = math.sin(progress * math.pi)

    _draw_blacksmith_upper(surface, shield_swing=swing_amount, hammer_swing=0.0)
    _draw_blacksmith_legs(surface, 0)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface


def create_blacksmith_paddle_hammering():
    global blacksmith_hammer_swing_phase

    surface = pygame.Surface((250, 120), pygame.SRCALPHA)

    if BLACKSMITH_HAMMER_SWING_DURATION > 0:
        phase_ratio = blacksmith_hammer_swing_phase / BLACKSMITH_HAMMER_SWING_DURATION
    else:
        phase_ratio = 0.0
    phase_ratio = max(0.0, min(1.0, phase_ratio))
    _draw_blacksmith_upper(surface, shield_swing=0.0, hammer_swing=phase_ratio)
    _draw_blacksmith_legs(surface, 0)
    scaled_surface, _ = _scale_blacksmith_sprite(surface, (BLACKSMITH_CENTER_X, BLACKSMITH_CENTER_Y))
    return scaled_surface


def handle_blacksmith_turret_input(down_pressed, down_just_pressed, force_blueprint=False):
    """발토르 포탑 설치/건설 입력을 처리한다."""
    global blacksmith_turret_blueprint_active, blacksmith_turret_blueprint_rect
    global blacksmith_turret_build_progress, blacksmith_turret_active
    global blacksmith_turret_state, special_gauge, special_ready
    global is_waiting_for_serve, is_player_serve
    global blacksmith_hammer_swing_active, blacksmith_hammer_swing_phase
    global blacksmith_manual_hammer_timer
    global blacksmith_turret_partial_drain, blacksmith_turret_xp_partial_drain
    global blacksmith_divine_blueprint_active, blacksmith_divine_blueprint_rect
    global blacksmith_divine_build_progress, blacksmith_divine_partial_drain
    global blacksmith_divine_stone_state
    global frame_counter
    global blacksmith_build_menu_active

    construction_active = False
    hammer_engaged_this_frame = False

    if selected_character_type != "blacksmith":
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if not blacksmith_hammer_available and not blacksmith_hammer_shock_charging:
        return down_just_pressed

    if is_waiting_for_serve or is_player_serve:
        stop_blacksmith_construction_sound()
        return down_just_pressed

    if blacksmith_build_menu_active:
        stop_blacksmith_construction_sound()
        return down_just_pressed

    # 포탑/청사진이 모두 없는 상태에서 ↓ 입력 시 청사진 생성
    if (
        force_blueprint
        and not blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
    ):
        blueprint_width = BLACKSMITH_TURRET_BLUEPRINT_WIDTH
        blueprint_height = BLACKSMITH_TURRET_BLUEPRINT_HEIGHT
        blueprint_rect = pygame.Rect(0, 0, blueprint_width, blueprint_height)
        base_x = max(blueprint_width // 2, min(WIDTH - blueprint_width // 2, PLAYER.centerx))
        base_y = HEIGHT - 5
        blueprint_rect.midbottom = (base_x, base_y)
        blacksmith_turret_blueprint_rect = blueprint_rect
        print(f"[DEBUG] Blueprint created: player_bottom={PLAYER.bottom}, blueprint_bottom={blueprint_rect.bottom}, top={blueprint_rect.top}")
        blacksmith_turret_build_progress = 0
        blacksmith_turret_blueprint_active = True
        blacksmith_turret_partial_drain = 0.0
        try:
            play_sound_with_volume(SOUND_ITEM_GET)
        except Exception:
            pass
        down_just_pressed = False
        blacksmith_hammer_swing_active = False
        blacksmith_hammer_swing_phase = 0
        blacksmith_manual_hammer_timer = 0
    elif (
        down_just_pressed
        and not blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
    ):
        stop_blacksmith_construction_sound()
        return down_just_pressed

    # 청사진이 설치된 상태에서 ↓키를 유지하면 건설 진행 (누적)
    if (
        blacksmith_turret_blueprint_active
        and not blacksmith_turret_active
        and blacksmith_turret_blueprint_rect is not None
    ):
        if down_pressed:
            distance = abs(PLAYER.centerx - blacksmith_turret_blueprint_rect.centerx)
            if distance <= BLACKSMITH_TURRET_BUILD_RADIUS:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_active = True
                blacksmith_hammer_swing_phase = (blacksmith_hammer_swing_phase + 1) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                drain_per_frame = BLACKSMITH_TURRET_GAUGE_DRAIN_PER_SEC / FPS
                gauge_spent = False
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_turret_partial_drain += drain_per_frame
                    gauge_spent = True
                    drain_units = int(blacksmith_turret_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_turret_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            construction_active = True
                        else:
                            gauge_spent = False
                else:
                    gauge_spent = False
                if gauge_spent:
                    blacksmith_turret_build_progress = min(
                        BLACKSMITH_TURRET_BUILD_TIME,
                        blacksmith_turret_build_progress + 1
                    )
                    if frame_counter % 4 == 0 and blacksmith_turret_blueprint_rect:
                        smoke_x = blacksmith_turret_blueprint_rect.centerx + random.uniform(-8, 8)
                        smoke_y = blacksmith_turret_blueprint_rect.top + random.uniform(-6, 4)
                        effects_manager.spawn_construction_smoke(smoke_x, smoke_y, count=2)
                    if blacksmith_turret_build_progress >= BLACKSMITH_TURRET_BUILD_TIME:
                        turret_rect = pygame.Rect(0, 0, BLACKSMITH_TURRET_BASE_WIDTH, BLACKSMITH_TURRET_BASE_HEIGHT)
                        turret_rect.midbottom = blacksmith_turret_blueprint_rect.midbottom
                        blacksmith_turret_state = {
                            "rect": turret_rect,
                            "fire_timer": BLACKSMITH_TURRET_FIRE_INTERVAL,
                            "fire_interval": BLACKSMITH_TURRET_FIRE_INTERVAL,
                            "hp": BLACKSMITH_TURRET_BASE_HP,
                            "max_hp": BLACKSMITH_TURRET_BASE_HP,
                            "level": BLACKSMITH_TURRET_BASE_LEVEL,
                            "xp": 0.0,
                            "xp_max": float(BLACKSMITH_TURRET_XP_REQUIRED),
                            "aim_angle": -math.pi / 2,
                            "display_angle": -math.pi / 2,
                            "recoil_timer": 0,
                            "recoil_offset": 0.0,
                        }
                        blacksmith_turret_active = True
                        blacksmith_turret_blueprint_active = False
                        blacksmith_turret_blueprint_rect = None
                        blacksmith_turret_build_progress = 0
                        blacksmith_turret_partial_drain = 0.0
                        try:
                            play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                        except Exception:
                            pass
                        blacksmith_hammer_swing_active = False
                        blacksmith_hammer_swing_phase = 0
                        blacksmith_manual_hammer_timer = 0
                    elif frame_counter % 30 == 0:
                        print(f"[DEBUG] Turret build: {blacksmith_turret_build_progress}/{BLACKSMITH_TURRET_BUILD_TIME}, gauge={special_gauge}, phase={blacksmith_hammer_swing_phase}")
                else:
                    if frame_counter % 45 == 0:
                        print(f"[DEBUG] Turret build paused (gauge={special_gauge}, partial={blacksmith_turret_partial_drain:.2f})")
        # ↓키를 누르지 않아도 진행도는 유지 (누적 빌드)
    else:
        if (
            blacksmith_turret_active
            and blacksmith_turret_state
            and down_pressed
            and blacksmith_turret_state.get("rect") is not None
        ):
            distance = abs(PLAYER.centerx - blacksmith_turret_state["rect"].centerx)
            if distance <= BLACKSMITH_TURRET_BUILD_RADIUS:
                hammer_engaged_this_frame = True

    if (
        blacksmith_divine_blueprint_active
        and blacksmith_divine_blueprint_rect is not None
        and blacksmith_divine_stone_state is None
    ):
        if down_pressed:
            distance = abs(PLAYER.centerx - blacksmith_divine_blueprint_rect.centerx)
            if distance <= BLACKSMITH_DIVINE_BUILD_RADIUS:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_active = True
                blacksmith_hammer_swing_phase = (
                    blacksmith_hammer_swing_phase + 1
                ) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                drain_per_frame = BLACKSMITH_DIVINE_GAUGE_DRAIN_PER_SEC / FPS
                gauge_spent = False
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_divine_partial_drain += drain_per_frame
                    drain_units = int(blacksmith_divine_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_divine_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            gauge_spent = True
                if gauge_spent:
                    blacksmith_divine_build_progress = min(
                        BLACKSMITH_DIVINE_BUILD_TIME,
                        blacksmith_divine_build_progress + 1,
                    )
                    if frame_counter % 6 == 0:
                        smoke_x = blacksmith_divine_blueprint_rect.centerx + random.uniform(-6, 6)
                        smoke_y = blacksmith_divine_blueprint_rect.bottom - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT + random.uniform(-6, 4)
                        effects_manager.spawn_construction_smoke(smoke_x, smoke_y, count=2)
                    if blacksmith_divine_build_progress >= BLACKSMITH_DIVINE_BUILD_TIME:
                        stone_width, stone_height = BLACKSMITH_DIVINE_STONE_SIZE
                        stone_rect = pygame.Rect(0, 0, stone_width, stone_height)
                        anchor_y = blacksmith_divine_blueprint_rect.bottom - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT
                        stone_rect.midbottom = (blacksmith_divine_blueprint_rect.centerx, anchor_y)
                        blacksmith_divine_stone_state = {
                            "rect": stone_rect,
                            "hp": BLACKSMITH_DIVINE_STONE_MAX_HP,
                            "pulse": 0,
                            "cooldown": 0,
                        }
                        effects_manager.spawn_star_particles(stone_rect.centerx, stone_rect.centery, count=12)
                        effects_manager.spawn_construction_smoke(stone_rect.centerx, stone_rect.bottom - 10, count=6, spread=18)
                        try:
                            play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
                        except Exception:
                            pass
                        blacksmith_divine_blueprint_active = False
                        blacksmith_divine_blueprint_rect = None
                        blacksmith_divine_build_progress = 0
                        blacksmith_divine_partial_drain = 0.0
                        blacksmith_hammer_swing_active = False
                        blacksmith_hammer_swing_phase = 0
                else:
                    if frame_counter % 45 == 0:
                        print(
                            f"[DEBUG] Divine build paused (gauge={special_gauge}, partial={blacksmith_divine_partial_drain:.2f})"
                        )
        else:
            blacksmith_divine_partial_drain = 0.0
    elif not blacksmith_divine_blueprint_active:
        blacksmith_divine_partial_drain = 0.0

    # 포탑이 완성된 후 ↓키를 눌러 경험치를 충전
    if blacksmith_turret_active and blacksmith_turret_state:
        level = blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL)
        turret_rect = blacksmith_turret_state.get("rect")
        xp_max = max(1.0, blacksmith_turret_state.get("xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED)))
        if level >= BLACKSMITH_TURRET_MAX_LEVEL:
            blacksmith_turret_state["xp"] = min(blacksmith_turret_state.get("xp", xp_max), xp_max)
            blacksmith_turret_xp_partial_drain = 0.0
        elif down_pressed and turret_rect is not None:
            distance = abs(PLAYER.centerx - turret_rect.centerx)
            engaged_for_upgrade = distance <= BLACKSMITH_TURRET_BUILD_RADIUS
            if engaged_for_upgrade:
                if not blacksmith_hammer_swing_active:
                    blacksmith_hammer_swing_phase = 0
                blacksmith_hammer_swing_active = True
                blacksmith_hammer_swing_phase = (blacksmith_hammer_swing_phase + 1) % max(1, BLACKSMITH_HAMMER_SWING_DURATION)
                hammer_engaged_this_frame = True
                drain_per_frame = BLACKSMITH_TURRET_GAUGE_DRAIN_PER_SEC / FPS
                xp_gain_units = 0
                if special_gauge > 0:
                    construction_active = True
                    blacksmith_turret_xp_partial_drain += drain_per_frame
                    drain_units = int(blacksmith_turret_xp_partial_drain)
                    if drain_units > 0:
                        actual_drain = min(drain_units, special_gauge)
                        if actual_drain > 0:
                            special_gauge -= actual_drain
                            blacksmith_turret_xp_partial_drain -= actual_drain
                            special_ready = special_gauge >= 350
                            xp_gain_units = actual_drain
                if xp_gain_units > 0:
                    current_xp = blacksmith_turret_state.get("xp", 0.0) + xp_gain_units
                    if current_xp >= xp_max:
                        blacksmith_turret_state["xp"] = xp_max
                        upgraded = upgrade_blacksmith_turret()
                        if upgraded:
                            blacksmith_turret_xp_partial_drain = 0.0
                    else:
                        blacksmith_turret_state["xp"] = current_xp
                        if frame_counter % 45 == 0:
                            print(f"[DEBUG] Turret XP: {current_xp:.1f}/{xp_max:.1f}")
                if xp_gain_units > 0:
                    construction_active = True
            else:
                blacksmith_turret_xp_partial_drain = 0.0
        else:
            blacksmith_turret_xp_partial_drain = 0.0
    else:
        blacksmith_turret_xp_partial_drain = 0.0

    if blacksmith_manual_hammer_timer > 0:
        if not hammer_engaged_this_frame:
            if not blacksmith_hammer_swing_active:
                blacksmith_hammer_swing_phase = 0
            blacksmith_hammer_swing_active = True
            if BLACKSMITH_HAMMER_SWING_DURATION > 0:
                blacksmith_hammer_swing_phase = min(
                    BLACKSMITH_HAMMER_SWING_DURATION,
                    blacksmith_hammer_swing_phase + 1,
                )
        blacksmith_manual_hammer_timer -= 1
        hammer_engaged_this_frame = True

    if not hammer_engaged_this_frame and blacksmith_hammer_swing_active:
        if blacksmith_hammer_swing_phase > 0:
            blacksmith_hammer_swing_phase = max(0, blacksmith_hammer_swing_phase - 2)
        if blacksmith_hammer_swing_phase <= 0:
            blacksmith_hammer_swing_active = False

    if construction_active:
        start_blacksmith_construction_sound()
    else:
        if (
            blacksmith_turret_blueprint_active
            or blacksmith_divine_blueprint_active
            or (
                blacksmith_turret_active
                and blacksmith_turret_state
                and blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL) < BLACKSMITH_TURRET_MAX_LEVEL
                and blacksmith_turret_state.get("xp", 0.0) < blacksmith_turret_state.get(
                    "xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED)
                )
            )
        ):
            pause_blacksmith_construction_sound()
        else:
            stop_blacksmith_construction_sound()

    return down_just_pressed


def _vec_to_int_pair(vec: pygame.math.Vector2 | tuple[float, float]) -> tuple[int, int]:
    if isinstance(vec, pygame.math.Vector2):
        return (int(round(vec.x)), int(round(vec.y)))
    return (int(round(vec[0])), int(round(vec[1])))


def _blacksmith_hammer_shock_stage_for_frames(frames: int) -> int:
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE3_FRAMES:
        return 3
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE2_FRAMES:
        return 2
    if frames >= BLACKSMITH_HAMMER_SHOCK_STAGE1_FRAMES:
        return 1
    return 0


def release_blacksmith_hammer_shock():
    global blacksmith_hammer_shock_charging, blacksmith_hammer_shock_charge_frames
    global blacksmith_hammer_shock_stage, blacksmith_hammer_shock_projectiles
    global blacksmith_hammer_available, blacksmith_hammer_shock_cooldown_timer
    global blacksmith_hammer_shock_anchor_x, blacksmith_hammer_shock_anchor_y
    global special_gauge, special_ready, special_gauge_max
    global PLAYER, SOUND_GRENADE

    if not blacksmith_hammer_shock_charging:
        return

    stage = _blacksmith_hammer_shock_stage_for_frames(blacksmith_hammer_shock_charge_frames)
    if stage == 0:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    if special_gauge < BLACKSMITH_HAMMER_SHOCK_COST:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    if 'PLAYER' not in globals() or PLAYER is None:
        blacksmith_hammer_shock_charging = False
        blacksmith_hammer_shock_charge_frames = 0
        blacksmith_hammer_shock_stage = 0
        return

    origin_x = PLAYER.right + 18
    origin_y = PLAYER.centery - 20

    projectile = {
        "x": float(origin_x),
        "y": float(origin_y),
        "vx": BLACKSMITH_HAMMER_SHOCK_PROJECTILE_SPEED,
        "vy": 0.0,
        "stage": stage,
        "life": int(1.5 * FPS),
        "rotation": 0.0,
    }
    blacksmith_hammer_shock_projectiles.append(projectile)

    special_gauge = max(0, special_gauge - BLACKSMITH_HAMMER_SHOCK_COST)
    special_ready = special_gauge >= special_gauge_max

    blacksmith_hammer_available = False
    blacksmith_hammer_shock_cooldown_timer = BLACKSMITH_HAMMER_SHOCK_NO_HAMMER_DURATION

    blacksmith_hammer_shock_charging = False
    blacksmith_hammer_shock_charge_frames = 0
    blacksmith_hammer_shock_stage = 0

    try:
        play_sound_with_volume(SOUND_GRENADE)
    except Exception:
        pass


def _trigger_blacksmith_hammer_shock_explosion(stage: int, centerx: float, centery: float):
    global BOSS
    radius = BLACKSMITH_HAMMER_SHOCK_BASE_RADIUS
    if stage == 2:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE2_RADIUS_SCALE
    elif stage >= 3:
        radius *= BLACKSMITH_HAMMER_SHOCK_STAGE3_RADIUS_SCALE

    try:
        effects_manager.create_impact_effect(int(centerx), int(centery), radius, is_player=False)
        effects_manager.spawn_star_particles(int(centerx), int(centery), count=12 + stage * 4)
        effects_manager.spawn_flame_particles(int(centerx), int(centery), count=6 + stage * 3)
    except Exception:
        pass

    knockback_speed = BLACKSMITH_HAMMER_SHOCK_STAGE1_KNOCKBACK
    if stage == 2:
        knockback_speed = BLACKSMITH_HAMMER_SHOCK_STAGE2_KNOCKBACK
    elif stage >= 3:
        knockback_speed = BLACKSMITH_HAMMER_SHOCK_STAGE3_KNOCKBACK

    if 'BOSS' in globals() and BOSS is not None:
        boss_rect = BOSS
        distance = abs(boss_rect.centerx - centerx)
        effective_radius = radius + boss_rect.width // 2
        if distance <= effective_radius:
            try:
                globals()["boss_knockback_timer"] = int(0.4 * FPS)
                globals()["boss_knockback_vel"] = knockback_speed
                globals()["boss_knockback_active"] = False
                globals()["boss_knockback_offset_x"] = 0
                globals()["boss_knockback_offset_y"] = 0
            except Exception:
                pass
            if stage >= 3:
                try:
                    globals()["boss_stunned_timer"] = max(globals().get("boss_stunned_timer", 0), int(3 * FPS))
                except Exception:
                    pass
            else:
                try:
                    globals()["boss_stunned_timer"] = max(globals().get("boss_stunned_timer", 0), int(2.0 * FPS))
                except Exception:
                    pass


def update_blacksmith_hammer_shock(keys):
    global blacksmith_hammer_shock_charging, blacksmith_hammer_shock_charge_frames
    global blacksmith_hammer_shock_stage, blacksmith_hammer_shock_projectiles
    global blacksmith_hammer_shock_cooldown_timer, blacksmith_hammer_available
    global blacksmith_hammer_shock_anchor_x, blacksmith_hammer_shock_anchor_y
    global PLAYER, special_gauge, special_ready, special_gauge_max

    if blacksmith_hammer_shock_cooldown_timer > 0:
        blacksmith_hammer_shock_cooldown_timer -= 1
        if blacksmith_hammer_shock_cooldown_timer <= 0 and not blacksmith_hammer_shock_projectiles:
            blacksmith_hammer_available = True

    if blacksmith_hammer_shock_charging:
        if 'PLAYER' in globals() and PLAYER is not None:
            PLAYER.centerx = int(blacksmith_hammer_shock_anchor_x)
            PLAYER.centery = int(blacksmith_hammer_shock_anchor_y)
        blacksmith_hammer_shock_charge_frames += 1
        blacksmith_hammer_shock_stage = _blacksmith_hammer_shock_stage_for_frames(blacksmith_hammer_shock_charge_frames)

        if special_gauge < BLACKSMITH_HAMMER_SHOCK_COST:
            blacksmith_hammer_shock_charging = False
            blacksmith_hammer_shock_charge_frames = 0
            blacksmith_hammer_shock_stage = 0
        else:
            try:
                if blacksmith_hammer_shock_stage >= 1 and blacksmith_hammer_shock_charge_frames % 6 == 0:
                    effects_manager.spawn_star_particles(PLAYER.centerx + 20, PLAYER.centery - 24, count=3 + blacksmith_hammer_shock_stage)
                if blacksmith_hammer_shock_stage >= 2 and blacksmith_hammer_shock_charge_frames % 10 == 0:
                    effects_manager.spawn_flame_particles(PLAYER.centerx + 16, PLAYER.centery - 30, count=2 + blacksmith_hammer_shock_stage)
            except Exception:
                pass
    else:
        blacksmith_hammer_shock_stage = 0
        blacksmith_hammer_shock_charge_frames = 0

    new_projectiles = []
    for proj in blacksmith_hammer_shock_projectiles:
        proj["x"] += proj["vx"]
        proj["y"] += proj.get("vy", 0.0)
        proj["rotation"] = (proj.get("rotation", 0.0) + 18.0) % 360
        proj["life"] -= 1

        exploded = False

        if 'BOSS' in globals() and BOSS is not None:
            boss_rect = BOSS
            if boss_rect.collidepoint(int(proj["x"]), int(proj["y"])):
                _trigger_blacksmith_hammer_shock_explosion(proj["stage"], proj["x"], proj["y"])
                exploded = True

        if not exploded:
            if proj["x"] >= WIDTH - 10 or proj["life"] <= 0:
                _trigger_blacksmith_hammer_shock_explosion(proj["stage"], min(proj["x"], WIDTH - 10), proj["y"])
                exploded = True

        if not exploded:
            new_projectiles.append(proj)

    blacksmith_hammer_shock_projectiles = new_projectiles


def draw_blacksmith_hammer_shock(surface):
    if selected_character_type != "blacksmith":
        return

    if blacksmith_hammer_shock_charging and 'PLAYER' in globals() and PLAYER is not None:
        cx = PLAYER.right + 20
        cy = PLAYER.centery - 24
        radius = 18 + blacksmith_hammer_shock_stage * 6
        color_inner = (140, 200, 255, 160)
        color_outer = (80, 140, 255, 100)
        pygame.draw.circle(surface, color_outer, (cx, cy), radius + 4)
        pygame.draw.circle(surface, color_inner, (cx, cy), radius, width=3)

    for proj in blacksmith_hammer_shock_projectiles:
        hammer_surface = pygame.Surface((32, 14), pygame.SRCALPHA)
        pygame.draw.rect(hammer_surface, (80, 60, 40), (0, 4, 12, 6))
        pygame.draw.rect(hammer_surface, (210, 220, 240), (12, 0, 20, 14), border_radius=4)
        pygame.draw.rect(hammer_surface, (255, 255, 255), (16, 4, 12, 6), border_radius=2)
        rotated = pygame.transform.rotate(hammer_surface, proj.get("rotation", 0.0))
        rect = rotated.get_rect(center=(int(proj["x"]), int(proj["y"])))
        surface.blit(rotated, rect)

def update_blacksmith_divine_stone():
    """디바인 스톤 상태 및 충돌 업데이트"""
    global blacksmith_divine_stone_state, ball_vel
    if blacksmith_divine_stone_state is None:
        return
    state = blacksmith_divine_stone_state
    rect = state["rect"]
    state["pulse"] = (state.get("pulse", 0) + 1) % 240
    cooldown = state.get("cooldown", 0)
    if cooldown > 0:
        state["cooldown"] = cooldown - 1
    if 'BALL' in globals() and BALL is not None:
        if rect.colliderect(BALL) and state.get("cooldown", 0) == 0:
            BALL.bottom = min(BALL.bottom, rect.top - 2)
            ball_vel[1] = -abs(ball_vel[1]) - 4
            ball_vel[0] *= 0.6
            state["hp"] = max(0, state.get("hp", BLACKSMITH_DIVINE_STONE_MAX_HP) - 1)
            state["cooldown"] = int(0.25 * FPS)
            effects_manager.spawn_star_particles(rect.centerx, rect.top, count=5)
            effects_manager.spawn_flame_particles(rect.centerx, rect.centery, count=4)
            if state["hp"] <= 0:
                effects_manager.create_impact_effect(rect.centerx, rect.centery, 70, is_player=False)
                blacksmith_divine_stone_state = None

def update_blacksmith_turret():
    """발토르 포탑의 발사 및 투사체 동작을 업데이트한다."""
    global blacksmith_turret_active, blacksmith_turret_state
    global blacksmith_turret_projectiles, player_collision_handled, last_hit_by
    global blacksmith_turret_blueprint_active, blacksmith_turret_partial_drain
    global blacksmith_turret_manual_cooldown, blacksmith_turret_xp_partial_drain
    global ball_vel, stopwatch_active, stopwatch_timer, game_vars, SCREEN

    update_blacksmith_divine_stone()

    if blacksmith_turret_manual_cooldown > 0:
        blacksmith_turret_manual_cooldown -= 1

    if not blacksmith_turret_active or not blacksmith_turret_state:
        blacksmith_turret_projectiles.clear()
        blacksmith_turret_manual_cooldown = 0
        blacksmith_turret_xp_partial_drain = 0.0
        if not blacksmith_turret_blueprint_active:
            stop_blacksmith_construction_sound()
        return

    turret_rect = blacksmith_turret_state.get("rect")
    if turret_rect is None:
        blacksmith_turret_active = False
        blacksmith_turret_projectiles.clear()
        blacksmith_turret_manual_cooldown = 0
        blacksmith_turret_xp_partial_drain = 0.0
        if not blacksmith_turret_blueprint_active:
            stop_blacksmith_construction_sound()
        return

    scale_factor = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
    boss_rect = BOSS if 'BOSS' in globals() else None
    target_angle = -math.pi / 2
    if boss_rect:
        target_angle = math.atan2(boss_rect.centery - turret_rect.centery,
                                  boss_rect.centerx - turret_rect.centerx)
    current_angle = blacksmith_turret_state.get("display_angle", target_angle)
    delta_angle = ((target_angle - current_angle + math.pi) % (2 * math.pi)) - math.pi
    current_angle += delta_angle * BLACKSMITH_TURRET_AIM_LERP
    blacksmith_turret_state["display_angle"] = current_angle
    blacksmith_turret_state["aim_angle"] = target_angle

    recoil_timer = blacksmith_turret_state.get("recoil_timer", 0)
    if recoil_timer > 0:
        recoil_timer -= 1
    blacksmith_turret_state["recoil_timer"] = recoil_timer
    if BLACKSMITH_TURRET_RECOIL_FRAMES > 0:
        blacksmith_turret_state["recoil_offset"] = (
            recoil_timer / BLACKSMITH_TURRET_RECOIL_FRAMES
        ) * BLACKSMITH_TURRET_RECOIL_DISTANCE * scale_factor
    else:
        blacksmith_turret_state["recoil_offset"] = 0.0

    if not (stopwatch_active and stopwatch_timer > 0) and turret_rect.colliderect(BALL):
        ball_rect = pygame.Rect(BALL)
        ball_owner = getattr(game_vars.ball, "last_hit_by", "player")
        if ball_owner != "player":
            if blacksmith_turret_state.get("hp", 0) > 0:
                blacksmith_turret_state["hp"] -= 1
                BALL.bottom = min(BALL.bottom, turret_rect.top - 4)
                speed_mag = max(7.0, math.hypot(ball_vel[0], ball_vel[1]))
                ball_vel[1] = -abs(speed_mag)
                ball_vel[0] *= 0.6
                last_hit_by = "player"
                game_vars.ball.last_hit_by = "player"
                player_collision_handled = True
                effects_manager.spawn_star_particles(turret_rect.centerx, turret_rect.top, count=6)
                try:
                    play_paddle_sound()
                except Exception:
                    pass

    if stopwatch_active and stopwatch_timer > 0:
        # 스톱워치 정지 중에는 포탑 발사도 중단
        pass
    else:
        blacksmith_turret_state["fire_timer"] -= 1
        if blacksmith_turret_state["fire_timer"] <= 0:
            display_angle = blacksmith_turret_state.get("display_angle", -math.pi / 2)
            direction = pygame.math.Vector2(math.cos(display_angle), math.sin(display_angle))
            if direction.length() == 0:
                direction = pygame.math.Vector2(0, -1)
            else:
                direction = direction.normalize()

            scale_x = turret_rect.width / BLACKSMITH_TURRET_DESIGN_WIDTH
            scale_y = turret_rect.height / BLACKSMITH_TURRET_DESIGN_HEIGHT
            blacksmith_turret_state["recoil_timer"] = BLACKSMITH_TURRET_RECOIL_FRAMES
            blacksmith_turret_state["recoil_offset"] = BLACKSMITH_TURRET_RECOIL_DISTANCE * scale_x
            pivot_point = pygame.math.Vector2(
                turret_rect.centerx,
                turret_rect.top + scale_y * BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET,
            )
            recoil_offset = blacksmith_turret_state.get("recoil_offset", 0.0)
            pivot_point -= direction * recoil_offset
            muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
            spawn_point = pivot_point + direction * (muzzle_distance + BLACKSMITH_TURRET_PROJECTILE_RADIUS + 2)

            projectile_speed = BLACKSMITH_TURRET_MISSILE_SPEED
            projectile = {
                "x": float(spawn_point.x),
                "y": float(spawn_point.y),
                "vx": direction.x * projectile_speed,
                "vy": direction.y * projectile_speed,
                "speed": projectile_speed,
                "life": BLACKSMITH_TURRET_MISSILE_LIFE,
                "radius": BLACKSMITH_TURRET_PROJECTILE_RADIUS,
                "grace_frames": 6,
            }
            blacksmith_turret_projectiles.append(projectile)
            blacksmith_turret_state["fire_timer"] = blacksmith_turret_state["fire_interval"]
            try:
                play_sound_with_volume(SOUND_THROW)
            except Exception:
                pass

    boss_rect = BOSS if 'BOSS' in globals() else None
    boss_target_x = boss_rect.centerx if boss_rect else WIDTH // 2
    boss_target_y = boss_rect.centery if boss_rect else HEIGHT // 3

    if blacksmith_turret_projectiles and not (stopwatch_active and stopwatch_timer > 0):
        new_projectiles = []
        for proj in blacksmith_turret_projectiles:
            speed = proj.get("speed", BLACKSMITH_TURRET_MISSILE_SPEED)
            turn_rate = BLACKSMITH_TURRET_MISSILE_TURN_RATE

            if boss_rect:
                to_target = pygame.math.Vector2(boss_target_x - proj["x"], boss_target_y - proj["y"])
                if to_target.length() > 0:
                    desired_dir = to_target.normalize()
                    desired_vx = desired_dir.x * speed
                    desired_vy = desired_dir.y * speed
                    proj["vx"] = (1 - turn_rate) * proj["vx"] + turn_rate * desired_vx
                    proj["vy"] = (1 - turn_rate) * proj["vy"] + turn_rate * desired_vy

            speed = min(BLACKSMITH_TURRET_MISSILE_MAX_SPEED, speed * (1 + BLACKSMITH_TURRET_MISSILE_ACCEL))
            proj["speed"] = speed
            current_speed = math.hypot(proj["vx"], proj["vy"])
            if current_speed > 0:
                scale = speed / current_speed
                proj["vx"] *= scale
                proj["vy"] *= scale

            proj["x"] += proj["vx"]
            proj["y"] += proj["vy"]
            proj["life"] -= 1

            radius = int(proj.get("radius", BLACKSMITH_TURRET_PROJECTILE_RADIUS))
            grace_frames = proj.get("grace_frames", 0)
            if grace_frames > 0:
                proj["grace_frames"] = grace_frames - 1
                grace_frames = proj["grace_frames"]

            if proj["life"] <= 0:
                continue

            if (
                proj["x"] < -radius * 2
                or proj["x"] > WIDTH + radius * 2
                or proj["y"] < -radius * 2
                or proj["y"] > HEIGHT + radius * 2
            ):
                continue

            projectile_rect = pygame.Rect(0, 0, radius * 2, radius * 2)
            projectile_rect.center = (proj["x"], proj["y"])

            if 'PLAYER' in globals() and PLAYER is not None:
                try:
                    if projectile_rect.colliderect(PLAYER):
                        new_projectiles.append(proj)
                        continue
                except Exception:
                    pass

            if boss_rect and projectile_rect.colliderect(boss_rect):
                try:
                    current_star_timer = globals().get("boss_stunned_timer", 0)
                    current_star_timer = max(current_star_timer, BLACKSMITH_TURRET_STUN_DURATION)
                    globals()["boss_stunned_timer"] = current_star_timer
                    globals()["boss_stun_timer"] = 0
                except Exception:
                    pass
                try:
                    edge_margin = max(10, boss_rect.width // 2)
                    if boss_rect.left <= edge_margin:
                        knockback_direction = 1
                    elif boss_rect.right >= WIDTH - edge_margin:
                        knockback_direction = -1
                    else:
                        knockback_direction = 1 if proj["x"] < boss_rect.centerx else -1
                    globals()["boss_knockback_timer"] = BLACKSMITH_TURRET_STUN_DURATION
                    globals()["boss_knockback_vel"] = knockback_direction * BLACKSMITH_TURRET_KNOCKBACK_SPEED
                    globals()["boss_knockback_active"] = False
                    globals()["boss_knockback_offset_x"] = 0
                    globals()["boss_knockback_offset_y"] = 0
                except Exception:
                    pass
                cx, cy = int(proj["x"]), int(proj["y"])
                try:
                    effects_manager.create_impact_effect(cx, cy, radius * 2.0, is_player=False)
                except Exception:
                    pass
                try:
                    effects_manager.spawn_star_particles(cx, cy, count=8)
                    effects_manager.spawn_flame_particles(cx, cy, count=7)
                    effects_manager.spawn_construction_smoke(cx, cy, count=5, spread=20)
                except Exception:
                    pass
                continue

            current_turret_rect = blacksmith_turret_state.get("rect") if blacksmith_turret_state else None
            if grace_frames <= 0 and current_turret_rect and current_turret_rect.colliderect(projectile_rect):
                if blacksmith_turret_state.get("hp", 0) > 0:
                    blacksmith_turret_state["hp"] -= 1
                    spark_surface = pygame.Surface((14, 14), pygame.SRCALPHA)
                    pygame.draw.circle(spark_surface, (255, 200, 100, 200), (7, 7), 6)
                    surface_target = pygame.Surface((14, 14), pygame.SRCALPHA)
                    pygame.draw.circle(surface_target, (255, 255, 255, 240), (7, 7), 3)
                    spark_surface.blit(surface_target, (0, 0))
                    SCREEN.blit(spark_surface, (projectile_rect.centerx - 7, projectile_rect.centery - 7))
                    try:
                        play_sound_with_volume(SOUND_DEFENSE_BLOCK)
                    except Exception:
                        pass
                continue

            new_projectiles.append(proj)

        blacksmith_turret_projectiles = new_projectiles

    if blacksmith_turret_active and blacksmith_turret_state and blacksmith_turret_state.get("hp", 0) <= 0:
        effects_manager.spawn_star_particles(turret_rect.centerx, turret_rect.centery, count=12)
        try:
            play_sound_with_volume(SOUND_STAGE6_BOSS_HIT)
        except Exception:
            pass
        blacksmith_turret_active = False
        blacksmith_turret_state = None
        blacksmith_turret_blueprint_active = False
        blacksmith_turret_projectiles.clear()
        blacksmith_turret_partial_drain = 0.0
        blacksmith_turret_xp_partial_drain = 0.0
        blacksmith_turret_manual_cooldown = 0
        stop_blacksmith_construction_sound()


def upgrade_blacksmith_turret():
    """포탑 레벨 상승과 능력치를 갱신한다."""
    global blacksmith_turret_state
    if not blacksmith_turret_active or not blacksmith_turret_state:
        return False

    level = blacksmith_turret_state.get("level", BLACKSMITH_TURRET_BASE_LEVEL)
    if level >= BLACKSMITH_TURRET_MAX_LEVEL:
        blacksmith_turret_state["xp"] = blacksmith_turret_state.get("xp_max", float(BLACKSMITH_TURRET_XP_REQUIRED))
        return False

    new_level = level + 1
    blacksmith_turret_state["level"] = new_level

    current_max_hp = blacksmith_turret_state.get("max_hp", BLACKSMITH_TURRET_BASE_HP)
    upgraded_max_hp = max(current_max_hp + 1, int(math.ceil(current_max_hp * BLACKSMITH_TURRET_LEVEL_HP_MULTIPLIER)))
    blacksmith_turret_state["max_hp"] = upgraded_max_hp
    blacksmith_turret_state["hp"] = upgraded_max_hp

    current_interval = blacksmith_turret_state.get("fire_interval", BLACKSMITH_TURRET_FIRE_INTERVAL)
    upgraded_interval = max(int(current_interval * BLACKSMITH_TURRET_LEVEL_FIRE_RATE_MULTIPLIER), int(2 * FPS))
    blacksmith_turret_state["fire_interval"] = upgraded_interval
    blacksmith_turret_state["fire_timer"] = min(blacksmith_turret_state.get("fire_timer", upgraded_interval), upgraded_interval)

    if new_level >= BLACKSMITH_TURRET_MAX_LEVEL:
        blacksmith_turret_state["xp_max"] = float(BLACKSMITH_TURRET_XP_REQUIRED)
        blacksmith_turret_state["xp"] = blacksmith_turret_state["xp_max"]
    else:
        scaling = 1.5 ** (new_level - 1)
        blacksmith_turret_state["xp_max"] = float(BLACKSMITH_TURRET_XP_REQUIRED * scaling)
        blacksmith_turret_state["xp"] = 0.0

    try:
        rect = blacksmith_turret_state.get("rect")
        if rect:
            effects_manager.spawn_star_particles(rect.centerx, rect.top - 10, count=18)
            effects_manager.spawn_flame_particles(rect.centerx, rect.centery, count=14)
    except Exception:
        pass
    try:
        play_sound_with_volume(SOUND_STAGE6_BEAM_CHARGE)
    except Exception:
        pass

    print(f"[DEBUG] Turret upgraded to Lv {new_level} (HP {upgraded_max_hp}, fire {upgraded_interval}f)")
    return True


def draw_blacksmith_turret_elements(surface):
    """발토르 포탑과 청사진, 투사체를 그린다."""
    draw_blacksmith_divine_stone(surface)
    if blacksmith_divine_blueprint_active and blacksmith_divine_blueprint_rect:
        blueprint_rect = blacksmith_divine_blueprint_rect
        progress_ratio = 0.0
        if BLACKSMITH_DIVINE_BUILD_TIME > 0:
            progress_ratio = blacksmith_divine_build_progress / BLACKSMITH_DIVINE_BUILD_TIME
        progress_ratio = max(0.0, min(1.0, progress_ratio))

        width = blueprint_rect.width
        height = blueprint_rect.height
        base_surface = pygame.Surface((width, height), pygame.SRCALPHA)

        base_center = pygame.math.Vector2(width / 2, height - BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT / 2)
        base_radius_x = max(18, width // 3)
        base_radius_y = max(12, BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT // 2)
        pygame.draw.ellipse(
            base_surface,
            (90, 70, 55, 220),
            pygame.Rect(
                int(base_center.x - base_radius_x),
                int(base_center.y - base_radius_y),
                int(base_radius_x * 2),
                int(base_radius_y * 2),
            ),
        )
        pygame.draw.ellipse(
            base_surface,
            (160, 130, 95, 160),
            pygame.Rect(
                int(base_center.x - base_radius_x + 6),
                int(base_center.y - base_radius_y + 6),
                int((base_radius_x - 6) * 2),
                int((base_radius_y - 6) * 2),
            ),
            2,
        )

        stage_float = progress_ratio * 3.0
        stage_index = min(2, int(stage_float))
        stage_alpha = stage_float - stage_index

        stone_width, stone_height = BLACKSMITH_DIVINE_STONE_SIZE
        stone_surface = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
        stone_color = (200, 210, 220)
        if stage_index >= 0:
            outline_alpha = int(110 + 100 * progress_ratio)
            pygame.draw.rect(
                stone_surface,
                (*stone_color, outline_alpha),
                pygame.Rect(8, 6, stone_width - 16, stone_height - 12),
                2,
                border_radius=10,
            )
            glyph_alpha = int(80 + 120 * stage_alpha) if stage_index >= 1 else int(70 * progress_ratio)
            for offset, radius in ((0, 10), (12, 6), (-12, 6)):
                pygame.draw.circle(
                    stone_surface,
                    (120, 160, 255, glyph_alpha),
                    (stone_width // 2 + offset, stone_height // 2),
                    radius,
                    1,
                )
        if stage_index >= 2:
            fill_alpha = int(190 * progress_ratio)
            pygame.draw.rect(
                stone_surface,
                (220, 230, 240, fill_alpha),
                pygame.Rect(10, 8, stone_width - 20, stone_height - 16),
                border_radius=8,
            )
            glow_surface = pygame.Surface((stone_width, stone_height), pygame.SRCALPHA)
            pygame.draw.ellipse(
                glow_surface,
                (120, 200, 255, int(130 * stage_alpha)),
                pygame.Rect(14, stone_height - 26, stone_width - 28, 18),
            )
            stone_surface.blit(glow_surface, (0, 0))

        placement_y = height - (BLACKSMITH_DIVINE_BLUEPRINT_EXTRA_HEIGHT + stone_height)
        base_surface.blit(stone_surface, ((width - stone_width) // 2, placement_y))

        surface.blit(base_surface, blueprint_rect.topleft)

        gauge_width = blueprint_rect.width
        gauge_height = 6
        gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
        pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
        if progress_ratio > 0:
            filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
            pygame.draw.rect(surface, (110, 200, 255), filled_rect, border_radius=3)
        pygame.draw.rect(surface, (150, 200, 255), gauge_rect, 1, border_radius=3)
    if blacksmith_turret_blueprint_active and blacksmith_turret_blueprint_rect:
        blueprint_rect = blacksmith_turret_blueprint_rect
        progress_ratio = 0.0
        if BLACKSMITH_TURRET_BUILD_TIME > 0:
            progress_ratio = blacksmith_turret_build_progress / BLACKSMITH_TURRET_BUILD_TIME
        progress_ratio = max(0.0, min(1.0, progress_ratio))

        stage_float = progress_ratio * 3.0
        stage_index = min(2, int(stage_float))
        stage_alpha = stage_float - stage_index

        width = blueprint_rect.width
        height = blueprint_rect.height
        base_surface = pygame.Surface((width, height), pygame.SRCALPHA)

        ground_rect = pygame.Rect(2, height - 10, width - 4, 10)
        pygame.draw.rect(base_surface, (90, 70, 55), ground_rect, border_radius=3)
        pygame.draw.rect(base_surface, (70, 55, 40), ground_rect.inflate(4, 2), 2, border_radius=4)

        stake_color = (110, 85, 65)
        rope_color = (160, 130, 95)

        if stage_index >= 0:
            # Stage 1: stake perimeter and dirt patch
            dirt_color = (120, 95, 70, 200)
            dirt_rect = pygame.Rect(6, height - 14, width - 12, 12)
            pygame.draw.rect(base_surface, dirt_color, dirt_rect, border_radius=3)
            for x in (6, width - 8):
                for y in (height - 12, height - 6):
                    pygame.draw.rect(base_surface, stake_color, (x, y, 4, 8))
            pygame.draw.line(base_surface, rope_color, (8, height - 8), (width - 8, height - 8), 2)

        if stage_index >= 1:
            # Stage 2: wooden frame
            frame_height = height - 16
            post_positions = [8, width // 2, width - 8]
            for px in post_positions:
                pygame.draw.rect(base_surface, (120, 100, 80), (px - 2, 4, 4, frame_height))
            pygame.draw.rect(base_surface, (150, 120, 90), (10, 8, width - 20, 6))
            pygame.draw.rect(base_surface, (135, 105, 80), (14, 20, width - 28, 4))
            for beam_y in (20, 28 + int(8 * stage_alpha)):
                pygame.draw.line(base_surface, (160, 125, 90), (10, beam_y), (width - 10, beam_y), 3)

        if stage_index >= 2:
            # Stage 3: partial walls and scaffolding
            wall_height = max(8, int(18 * (0.4 + 0.6 * stage_alpha)))
            wall_rect = pygame.Rect(12, height - 18 - wall_height, width - 24, wall_height)
            pygame.draw.rect(base_surface, (165, 140, 110), wall_rect)
            pygame.draw.rect(base_surface, (200, 180, 150), wall_rect, 2)
            # roof beams
            roof_y = wall_rect.top - 4
            pygame.draw.rect(base_surface, (145, 115, 85), (16, roof_y, width - 32, 4))
            for idx in range(3):
                beam_x = 18 + idx * ((width - 36) // 2)
                pygame.draw.line(base_surface, (110, 90, 70), (beam_x, roof_y), (beam_x - 6, roof_y - 10), 2)
                pygame.draw.line(base_surface, (110, 90, 70), (beam_x + (width - 36) // 2, roof_y), (beam_x + (width - 36) // 2 + 6, roof_y - 10), 2)

        surface.blit(base_surface, blueprint_rect.topleft)

        gauge_width = blueprint_rect.width
        gauge_height = 6
        gauge_rect = pygame.Rect(blueprint_rect.left, blueprint_rect.top - gauge_height - 6, gauge_width, gauge_height)
        pygame.draw.rect(surface, (40, 50, 70), gauge_rect.inflate(4, 4), border_radius=3)
        if progress_ratio > 0:
            filled_rect = pygame.Rect(gauge_rect.left, gauge_rect.top, int(gauge_width * progress_ratio), gauge_height)
            pygame.draw.rect(surface, (220, 180, 80), filled_rect, border_radius=3)
        pygame.draw.rect(surface, (110, 120, 140), gauge_rect, 1, border_radius=3)

    if blacksmith_turret_active and blacksmith_turret_state and blacksmith_turret_state.get("rect"):
        turret_rect = blacksmith_turret_state["rect"]
        cx = turret_rect.centerx
        top = turret_rect.top
        bottom = turret_rect.bottom
        left = turret_rect.left
        right = turret_rect.right
        width = turret_rect.width
        height = turret_rect.height

        scale_x = width / BLACKSMITH_TURRET_DESIGN_WIDTH
        scale_y = height / BLACKSMITH_TURRET_DESIGN_HEIGHT

        def sx_val(value):
            return value * scale_x

        def sy_val(value):
            return value * scale_y

        base_points = [
            (cx - sx_val(36), bottom - sy_val(6)),
            (cx + sx_val(36), bottom - sy_val(6)),
            (cx + sx_val(24), bottom + sy_val(8)),
            (cx - sx_val(24), bottom + sy_val(8))
        ]
        pygame.draw.polygon(surface, (66, 60, 92), [(int(x), int(y)) for x, y in base_points])
        pygame.draw.lines(surface, (130, 122, 170), True, [(int(x), int(y)) for x, y in base_points], max(1, int(sx_val(2))))

        left_leg = [
            (left + sx_val(2), bottom - sy_val(12)),
            (left - sx_val(12), bottom - sy_val(42)),
            (left - sx_val(6), bottom - sy_val(60)),
            (left + sx_val(10), bottom - sy_val(34))
        ]
        right_leg = [
            (right - sx_val(2), bottom - sy_val(12)),
            (right + sx_val(12), bottom - sy_val(42)),
            (right + sx_val(6), bottom - sy_val(60)),
            (right - sx_val(10), bottom - sy_val(34))
        ]
        pygame.draw.polygon(surface, (178, 182, 206), [(int(x), int(y)) for x, y in left_leg])
        pygame.draw.polygon(surface, (178, 182, 206), [(int(x), int(y)) for x, y in right_leg])
        pygame.draw.lines(surface, (82, 86, 120), False, [(int(x), int(y)) for x, y in left_leg], max(1, int(sx_val(2))))
        pygame.draw.lines(surface, (82, 86, 120), False, [(int(x), int(y)) for x, y in right_leg], max(1, int(sx_val(2))))

        left_claw = [
            (cx - sx_val(18), bottom - sy_val(26)),
            (cx - sx_val(40), bottom - sy_val(8)),
            (cx - sx_val(26), bottom + sy_val(4)),
            (cx - sx_val(10), bottom - sy_val(14))
        ]
        right_claw = [
            (cx + sx_val(18), bottom - sy_val(26)),
            (cx + sx_val(40), bottom - sy_val(8)),
            (cx + sx_val(26), bottom + sy_val(4)),
            (cx + sx_val(10), bottom - sy_val(14))
        ]
        pygame.draw.polygon(surface, (204, 68, 76), [(int(x), int(y)) for x, y in left_claw])
        pygame.draw.polygon(surface, (204, 68, 76), [(int(x), int(y)) for x, y in right_claw])
        pygame.draw.lines(surface, (255, 220, 130), True, [(int(x), int(y)) for x, y in left_claw], max(1, int(sx_val(2))))
        pygame.draw.lines(surface, (255, 220, 130), True, [(int(x), int(y)) for x, y in right_claw], max(1, int(sx_val(2))))

        torso_points = [
            (cx - sx_val(18), bottom - sy_val(46)),
            (cx - sx_val(28), top + sy_val(48)),
            (cx - sx_val(14), top + sy_val(22)),
            (cx - sx_val(6), top + sy_val(12)),
            (cx + sx_val(6), top + sy_val(12)),
            (cx + sx_val(14), top + sy_val(22)),
            (cx + sx_val(28), top + sy_val(48)),
            (cx + sx_val(18), bottom - sy_val(46))
        ]
        pygame.draw.polygon(surface, (228, 238, 255), [(int(x), int(y)) for x, y in torso_points])
        inner_torso = [
            (cx - sx_val(12), bottom - sy_val(44)),
            (cx - sx_val(20), top + sy_val(46)),
            (cx - sx_val(10), top + sy_val(26)),
            (cx - sx_val(2), top + sy_val(16)),
            (cx + sx_val(2), top + sy_val(16)),
            (cx + sx_val(10), top + sy_val(26)),
            (cx + sx_val(20), top + sy_val(46)),
            (cx + sx_val(12), bottom - sy_val(44))
        ]
        pygame.draw.polygon(surface, (210, 70, 78), [(int(x), int(y)) for x, y in inner_torso])
        pygame.draw.lines(surface, (70, 40, 60), True, [(int(x), int(y)) for x, y in torso_points], max(1, int(sx_val(2))))

        column_width = max(4, int(sx_val(14)))
        column_height = max(18, int(sy_val(24)))
        center_column = pygame.Rect(int(cx - column_width / 2), int(top + sy_val(26)), column_width, column_height)
        pygame.draw.rect(surface, (86, 96, 138), center_column, border_radius=int(max(2, sx_val(4))))
        inner_column = center_column.inflate(-max(2, int(sx_val(6))), -max(2, int(sy_val(8))))
        if inner_column.width > 0 and inner_column.height > 0:
            pygame.draw.rect(surface, (158, 198, 255), inner_column, border_radius=int(max(1, sx_val(3))))

        angle = blacksmith_turret_state.get("display_angle", -math.pi / 2)
        forward_vec = pygame.math.Vector2(math.cos(angle), math.sin(angle))
        if forward_vec.length() == 0:
            forward_vec = pygame.math.Vector2(0, -1)
        else:
            forward_vec = forward_vec.normalize()
        recoil_offset = blacksmith_turret_state.get("recoil_offset", 0.0)
        pivot_point = pygame.math.Vector2(
            cx,
            top + sy_val(BLACKSMITH_TURRET_HEAD_PIVOT_OFFSET)
        ) - forward_vec * recoil_offset

        head_width = max(24, int(sx_val(84)))
        head_height = max(24, int(sy_val(84)))
        head_surface = pygame.Surface((head_width, head_height), pygame.SRCALPHA)
        pivot_local = pygame.math.Vector2(head_width / 2, head_height * 0.7)

        def head_point(dx, dy):
            return (int(pivot_local.x + dx), int(pivot_local.y + dy))

        body_poly = [
            head_point(-sx_val(12), sy_val(12)),
            head_point(-sx_val(24), -sy_val(10)),
            head_point(-sx_val(10), -sy_val(34)),
            head_point(-sx_val(4), -sy_val(48)),
            head_point(0, -sy_val(54)),
            head_point(sx_val(4), -sy_val(48)),
            head_point(sx_val(10), -sy_val(34)),
            head_point(sx_val(24), -sy_val(10)),
            head_point(sx_val(12), sy_val(12)),
        ]
        pygame.draw.polygon(head_surface, (228, 238, 255), body_poly)
        pygame.draw.polygon(head_surface, (210, 70, 78), [
            head_point(-sx_val(10), sy_val(10)),
            head_point(-sx_val(18), -sy_val(8)),
            head_point(-sx_val(6), -sy_val(30)),
            head_point(0, -sy_val(40)),
            head_point(sx_val(6), -sy_val(30)),
            head_point(sx_val(18), -sy_val(8)),
            head_point(sx_val(10), sy_val(10)),
        ])
        pygame.draw.lines(head_surface, (70, 40, 60), True, body_poly, max(1, int(sx_val(2))))

        claw_left = [
            head_point(-sx_val(18), sy_val(8)),
            head_point(-sx_val(36), sy_val(18)),
            head_point(-sx_val(28), sy_val(30)),
            head_point(-sx_val(12), sy_val(20)),
        ]
        claw_right = [
            head_point(sx_val(18), sy_val(8)),
            head_point(sx_val(36), sy_val(18)),
            head_point(sx_val(28), sy_val(30)),
            head_point(sx_val(12), sy_val(20)),
        ]
        pygame.draw.polygon(head_surface, (204, 68, 76), claw_left)
        pygame.draw.polygon(head_surface, (204, 68, 76), claw_right)
        pygame.draw.lines(head_surface, (255, 220, 130), True, claw_left, max(1, int(sx_val(2))))
        pygame.draw.lines(head_surface, (255, 220, 130), True, claw_right, max(1, int(sx_val(2))))

        cannon_left = [
            head_point(-sx_val(16), -sy_val(14)),
            head_point(-sx_val(32), -sy_val(32)),
            head_point(-sx_val(26), -sy_val(48)),
            head_point(-sx_val(10), -sy_val(30)),
        ]
        cannon_right = [
            head_point(sx_val(16), -sy_val(14)),
            head_point(sx_val(32), -sy_val(32)),
            head_point(sx_val(26), -sy_val(48)),
            head_point(sx_val(10), -sy_val(30)),
        ]
        pygame.draw.polygon(head_surface, (242, 182, 62), cannon_left)
        pygame.draw.polygon(head_surface, (242, 182, 62), cannon_right)
        pygame.draw.lines(head_surface, (70, 40, 8), True, cannon_left, max(1, int(sx_val(2))))
        pygame.draw.lines(head_surface, (70, 40, 8), True, cannon_right, max(1, int(sx_val(2))))

        core_radius = max(3, int(sx_val(9)))
        pygame.draw.circle(head_surface, (40, 200, 255, 180), (int(pivot_local.x), int(pivot_local.y - sy_val(12))), core_radius)
        pygame.draw.circle(head_surface, (255, 255, 255, 200), (int(pivot_local.x), int(pivot_local.y - sy_val(12))), max(1, core_radius // 2))

        muzzle_rect = pygame.Rect(0, 0, max(3, int(sx_val(6))), max(4, int(sy_val(16))))
        muzzle_rect.center = head_point(0, -sy_val(54))
        pygame.draw.rect(head_surface, (94, 206, 255), muzzle_rect, border_radius=max(1, int(sx_val(2))))
        pygame.draw.rect(head_surface, (16, 36, 64), muzzle_rect, max(1, int(sx_val(1))), border_radius=max(1, int(sx_val(2))))

        heat_vent = pygame.Rect(0, 0, max(6, int(sx_val(18))), max(4, int(sy_val(10))))
        heat_vent.center = head_point(0, sy_val(2))
        pygame.draw.rect(head_surface, (150, 150, 168, 190), heat_vent, border_radius=max(1, int(sx_val(3))))

        angle_degrees = math.degrees(angle)
        rotated_head = pygame.transform.rotozoom(head_surface, -angle_degrees + 90, 1.0)
        rotated_rect = rotated_head.get_rect(center=(pivot_point.x, pivot_point.y))
        surface.blit(rotated_head, rotated_rect.topleft)

        muzzle_distance = BLACKSMITH_TURRET_MUZZLE_LENGTH * scale_x
        muzzle_world = pivot_point + forward_vec * muzzle_distance
        muzzle_tip = muzzle_world + forward_vec * max(4, sx_val(6))
        pygame.draw.line(surface, (180, 240, 255), (int(muzzle_world.x), int(muzzle_world.y)), (int(muzzle_tip.x), int(muzzle_tip.y)), max(1, int(sx_val(2))))

        glow_size = max(12, int(sx_val(32)))
        muzzle_glow = pygame.Surface((glow_size, glow_size), pygame.SRCALPHA)
        pygame.draw.circle(muzzle_glow, (24, 160, 220, 80), (glow_size // 2, glow_size // 2), glow_size // 2)
        pygame.draw.circle(muzzle_glow, (255, 255, 255, 120), (glow_size // 2, glow_size // 2), max(2, glow_size // 4))
        surface.blit(
            muzzle_glow,
            (int(muzzle_world.x - glow_size / 2), int(muzzle_world.y - glow_size / 2)),
            special_flags=pygame.BLEND_ADD,
        )

    for proj in blacksmith_turret_projectiles:
        proj_pos = (int(proj["x"]), int(proj["y"]))
        radius = int(proj.get("radius", BLACKSMITH_TURRET_PROJECTILE_RADIUS))
        if 'BLACKSMITH_MISSILE_IMG' in globals() and BLACKSMITH_MISSILE_IMG:
            velocity_angle = math.degrees(math.atan2(proj["vy"], proj["vx"])) - 180
            scale = max(0.6, radius / 12)
            missile_img = pygame.transform.rotozoom(BLACKSMITH_MISSILE_IMG, -velocity_angle, scale)
            missile_rect = missile_img.get_rect(center=proj_pos)
            surface.blit(missile_img, missile_rect.topleft)
        else:
            pygame.draw.circle(surface, (240, 210, 120), proj_pos, radius)
            pygame.draw.circle(surface, (110, 90, 60), proj_pos, int(radius * 1.5), 2)
    draw_blacksmith_build_menu(surface)


def draw_blacksmith_divine_stone(surface):
    if blacksmith_divine_stone_state is None:
        return
    rect = blacksmith_divine_stone_state["rect"]
    pulse = blacksmith_divine_stone_state.get("pulse", 0)
    hp = blacksmith_divine_stone_state.get("hp", BLACKSMITH_DIVINE_STONE_MAX_HP)
    tower_surface = pygame.Surface(rect.size, pygame.SRCALPHA)
    width, height = rect.size
    cx, cy = width // 2, height // 2

    base_height = max(12, height // 5)
    base_rect = pygame.Rect(6, height - base_height - 2, width - 12, base_height)
    pygame.draw.rect(tower_surface, (70, 60, 85), base_rect, border_radius=6)
    pygame.draw.rect(tower_surface, (140, 120, 170), base_rect.inflate(-6, -4), border_radius=4)
    pygame.draw.rect(tower_surface, (220, 200, 255), base_rect.inflate(-10, -8), border_radius=3, width=2)

    pillar_width = max(6, width // 6)
    pillar_height = height - base_height - 18
    left_pillar = pygame.Rect(8, height - base_height - pillar_height, pillar_width, pillar_height)
    right_pillar = pygame.Rect(width - pillar_width - 8, height - base_height - pillar_height, pillar_width, pillar_height)
    pygame.draw.rect(tower_surface, (120, 115, 150), left_pillar, border_radius=4)
    pygame.draw.rect(tower_surface, (120, 115, 150), right_pillar, border_radius=4)
    pygame.draw.rect(tower_surface, (200, 190, 240), left_pillar.inflate(-4, -4), border_radius=3, width=2)
    pygame.draw.rect(tower_surface, (200, 190, 240), right_pillar.inflate(-4, -4), border_radius=3, width=2)

    cap_height = max(10, height // 6)
    cap_rect = pygame.Rect(left_pillar.left - 6, left_pillar.top - cap_height + 4, right_pillar.right - left_pillar.left + 12, cap_height)
    pygame.draw.rect(tower_surface, (90, 80, 120), cap_rect, border_radius=6)
    pygame.draw.rect(tower_surface, (150, 140, 200), cap_rect.inflate(-6, -4), border_radius=5)
    pygame.draw.rect(tower_surface, (210, 200, 255), cap_rect.inflate(-10, -6), border_radius=4, width=2)

    arch_rect = pygame.Rect(left_pillar.left - 4, left_pillar.top - cap_height - 4, right_pillar.right - left_pillar.left + 8, cap_height + 12)
    pygame.draw.arc(tower_surface, (130, 120, 200), arch_rect, math.pi, 2 * math.pi, 3)

    float_height = left_pillar.top + (left_pillar.height // 2)
    orbital_radius = max(6, width // 5)
    float_offset = math.sin(pulse * 0.08) * 3
    mana_center = pygame.math.Vector2(cx, float_height + float_offset)
    core_radius = max(8, width // 6)
    glow_radius = core_radius + 6
    pygame.draw.circle(tower_surface, (110, 170, 255, 90), (int(mana_center.x), int(mana_center.y)), glow_radius + 6)
    pygame.draw.circle(tower_surface, (160, 200, 255, 140), (int(mana_center.x), int(mana_center.y)), glow_radius)
    pygame.draw.circle(tower_surface, (255, 255, 255, 220), (int(mana_center.x), int(mana_center.y)), core_radius)
    rune_progress = (pulse % 180) / 180.0
    for angle_deg in range(0, 360, 60):
        angle = math.radians(angle_deg + rune_progress * 120)
        orb_pos = mana_center + pygame.math.Vector2(math.cos(angle), math.sin(angle)) * orbital_radius
        pygame.draw.circle(tower_surface, (120, 200, 255, 180), _vec_to_int_pair(orb_pos), 3)

    spark_count = 4
    for idx in range(spark_count):
        spark_angle = math.radians((360 / spark_count) * idx + pulse * 4)
        outer = mana_center + pygame.math.Vector2(math.cos(spark_angle), math.sin(spark_angle)) * (orbital_radius + 10)
        inner = mana_center + pygame.math.Vector2(math.cos(spark_angle), math.sin(spark_angle)) * (orbital_radius - 2)
        pygame.draw.line(tower_surface, (150, 220, 255, 180), _vec_to_int_pair(inner), _vec_to_int_pair(outer), 2)

    chain_y = mana_center.y - core_radius - 6
    pygame.draw.line(tower_surface, (180, 190, 240), (left_pillar.centerx, int(chain_y)), (right_pillar.centerx, int(chain_y)), 2)

    halo_surface = pygame.Surface(rect.size, pygame.SRCALPHA)
    halo_radius = max(width // 2, height // 2)
    halo_alpha = 40 + int(30 * math.sin(pulse * 0.04))
    pygame.draw.circle(halo_surface, (90, 140, 240, halo_alpha), (cx, cy), halo_radius)
    tower_surface.blit(halo_surface, (0, 0))

    surface.blit(tower_surface, rect.topleft)

    hp_font = FontStyle.tiny()
    hp_text = hp_font.render(f"HP {hp}", True, (230, 240, 255))
    surface.blit(hp_text, hp_text.get_rect(center=(rect.centerx, rect.bottom + 10)))

    font = FontStyle.tiny()
    hp_text = font.render(f"HP {hp}", True, (230, 240, 255))
    surface.blit(hp_text, hp_text.get_rect(center=(rect.centerx, rect.bottom + 10)))


def draw_blacksmith_build_menu(surface):
    if not blacksmith_build_menu_active or 'PLAYER' not in globals() or PLAYER is None:
        return
    if not blacksmith_has_available_buildings():
        return
    spacing = BLACKSMITH_BUILD_ICON_SIZE[0] + 16
    base_x = PLAYER.centerx
    base_y = max(60, PLAYER.top - 60)
    for idx, option in enumerate(BLACKSMITH_BUILD_OPTIONS):
        available = blacksmith_can_build(option)
        icon = BLACKSMITH_TURRET_ICON if option == "turret" else BLACKSMITH_DIVINE_ICON
        icon_surface = icon.copy()
        if not available:
            dim = pygame.Surface(icon_surface.get_size(), pygame.SRCALPHA)
            dim.fill((0, 0, 0, 140))
            icon_surface.blit(dim, (0, 0))
        offset_x = (idx - (len(BLACKSMITH_BUILD_OPTIONS) - 1) / 2) * spacing
        dest_rect = icon_surface.get_rect(center=(base_x + offset_x, base_y))
        pygame.draw.rect(surface, (15, 20, 30, 180), dest_rect.inflate(18, 18), border_radius=12)
        border_color = (90, 150, 240, 220) if available else (90, 90, 90, 160)
        pygame.draw.rect(surface, border_color, dest_rect.inflate(22, 22), width=2, border_radius=14)
        surface.blit(icon_surface, dest_rect)
        font = FontStyle.tiny()
        text_color = (255, 255, 255) if available else (150, 150, 150)
        name = "포탑" if option == "turret" else "디바인스톤"
        label = font.render(name, True, text_color)
        surface.blit(label, label.get_rect(center=(dest_rect.centerx, dest_rect.bottom + 16)))


