def activate_stopwatch():
    """스탑워치 활성화 - 2초간 모든 것 정지 후 1초간 속도 회복"""
    global stopwatch_active, stopwatch_timer, stopwatch_flash_timer
    global stopwatch_original_ball_vel, stopwatch_recovery_timer, stopwatch_clock_angle
    global ball_vel, BALL, PLAYER
    global player_collision_handled, player_collision_cooldown, boss_collision_cooldown
    global current_speed
    
    # 패들과 공 사이 안전 거리 확인
    MIN_SAFE_DISTANCE = 35  # 최소 안전 거리
    if BALL and PLAYER:
        x_distance = abs(BALL.centerx - PLAYER.centerx)
        y_distance = abs(BALL.centery - PLAYER.centery)
        
        # 너무 가까우면 발동하지 않음
        if x_distance <= MIN_SAFE_DISTANCE and y_distance <= MIN_SAFE_DISTANCE:
            print(f"[스탑워치] 발동 취소 - 패들과 너무 가까움 (X:{x_distance:.0f}, Y:{y_distance:.0f})")
            return False
    
    if not stopwatch_active and BALL:
        stopwatch_active = True
        stopwatch_timer = STOPWATCH_DURATION  # 2초
        stopwatch_recovery_timer = 0
        stopwatch_flash_timer = 10  # 화면 번쩍임 효과
        stopwatch_clock_angle = 0
        
        # 타임워치 발동 사운드 재생
        try:
            play_sound_with_volume(SOUND_TIMEWATCH)  # ️ 타임워치 발동 사운드
        except:
            pass
        
        # 원래 공 속도 저장
        stopwatch_original_ball_vel = ball_vel.copy() if ball_vel else [0, 0]
        
        # 공 정지
        ball_vel = [0, 0]
        
        # 플레이어 이동 속도도 정지 (스탑워치 중 속도 누적 방지)
        current_speed = 0
        
        # 충돌 플래그 리셋 (스탑워치 시작 시 충돌 상태 초기화)
        player_collision_handled = False
        player_collision_cooldown = 0
        boss_collision_cooldown = 0
        
        # 효과음 재생
        play_active_item_sound()
        
        print("!   ...")
        return True
    
    return False

def draw_stopwatch_effect():
    """스탑워치 시계 애니메이션 그리기"""
    global stopwatch_clock_angle, stopwatch_flash_timer
    
    if not stopwatch_active:
        return
    
    # 화면 번쩍임 효과
    if stopwatch_flash_timer > 0:
        flash_surface = pygame.Surface((WIDTH, HEIGHT))
        flash_surface.fill((255, 255, 200))
        flash_surface.set_alpha(stopwatch_flash_timer * 25)
        SCREEN.blit(flash_surface, (0, 0))
        stopwatch_flash_timer -= 1
    
    # 상단에 시계 그리기
    clock_x = WIDTH // 2
    clock_y = 100
    clock_radius = 60
    
    # 시계 배경 (반투명)
    clock_bg = pygame.Surface((clock_radius * 2 + 20, clock_radius * 2 + 20), pygame.SRCALPHA)
    pygame.draw.circle(clock_bg, (0, 0, 0, 150), (clock_radius + 10, clock_radius + 10), clock_radius + 10)
    SCREEN.blit(clock_bg, (clock_x - clock_radius - 10, clock_y - clock_radius - 10))
    
    # 시계 테두리
    pygame.draw.circle(SCREEN, (180, 140, 90), (clock_x, clock_y), clock_radius, 4)
    pygame.draw.circle(SCREEN, (220, 180, 120), (clock_x, clock_y), clock_radius - 2, 2)
    
    # 시계 문자판
    pygame.draw.circle(SCREEN, (255, 255, 240), (clock_x, clock_y), clock_radius - 8)
    
    # 시간 표시 (12, 3, 6, 9)
    try:
        clock_font = pygame.font.Font(resource_path("NeoDGM.ttf"), 16)
    except:
        clock_font = pygame.font.Font(None, 16)
    
    for i, num in enumerate(['12', '3', '6', '9']):
        angle = i * math.pi / 2 - math.pi / 2
        text_x = clock_x + int((clock_radius - 20) * math.cos(angle))
        text_y = clock_y + int((clock_radius - 20) * math.sin(angle))
        
        text = clock_font.render(num, True, (80, 60, 40))
        text_rect = text.get_rect(center=(text_x, text_y))
        SCREEN.blit(text, text_rect)
    
    # 시침 (천천히 회전)
    hour_angle = stopwatch_clock_angle * 0.5
    hour_end_x = clock_x + int(30 * math.cos(hour_angle - math.pi/2))
    hour_end_y = clock_y + int(30 * math.sin(hour_angle - math.pi/2))
    pygame.draw.line(SCREEN, (40, 30, 20), (clock_x, clock_y), (hour_end_x, hour_end_y), 4)
    
    # 분침 (빠르게 회전)
    minute_angle = stopwatch_clock_angle * 2
    minute_end_x = clock_x + int(45 * math.cos(minute_angle - math.pi/2))
    minute_end_y = clock_y + int(45 * math.sin(minute_angle - math.pi/2))
    pygame.draw.line(SCREEN, (40, 30, 20), (clock_x, clock_y), (minute_end_x, minute_end_y), 2)
    
    # 초침 (매우 빠르게 회전)
    second_angle = stopwatch_clock_angle * 6
    second_end_x = clock_x + int(50 * math.cos(second_angle - math.pi/2))
    second_end_y = clock_y + int(50 * math.sin(second_angle - math.pi/2))
    pygame.draw.line(SCREEN, (255, 0, 0), (clock_x, clock_y), (second_end_x, second_end_y), 1)
    
    # 중앙 나사
    pygame.draw.circle(SCREEN, (60, 40, 20), (clock_x, clock_y), 3)
    
    # 남은 시간 텍스트 (비활성화)
    # if stopwatch_timer > 0:
    #     time_text = f"시간 정지: {stopwatch_timer / 60:.1f}초"
    # else:
    #     time_text = f"속도 회복 중: {stopwatch_recovery_timer / 60:.1f}초"
    # 
    # time_surface = clock_font.render(time_text, True, (255, 255, 255))
    # time_rect = time_surface.get_rect(center=(clock_x, clock_y + clock_radius + 30))
    # SCREEN.blit(time_surface, time_rect)
    
    # 시계 바늘 회전
    stopwatch_clock_angle += 0.1

def draw_pandora_box_effect():
    """판도라의 상자 무지개빛 애니메이션 그리기"""
    global pandora_box_rainbow_animation
    
    if not pandora_box_active:
        return
    
    # 화면 중앙에 무지개 효과 그리기
    center_x = WIDTH // 2
    center_y = HEIGHT // 2
    
    # 무지개 색상 패턴
    rainbow_colors = [
        (255, 0, 0),     # 빨강
        (255, 127, 0),   # 주황
        (255, 255, 0),   # 노랑
        (0, 255, 0),     # 초록
        (0, 0, 255),     # 파랑
        (75, 0, 130),    # 남색
        (148, 0, 211)    # 보라
    ]
    
    # 애니메이션 효과 - 회전하는 무지개 원
    for i, color in enumerate(rainbow_colors):
        # 각 색상의 각도 계산 (회전 효과)
        angle = (pandora_box_rainbow_animation * 3 + i * 360 / len(rainbow_colors)) % 360
        angle_rad = math.radians(angle)
        
        # 원의 반지름 (펄스 효과)
        pulse = math.sin(pandora_box_rainbow_animation * 0.1) * 10
        radius = 50 + pulse + i * 8
        
        # 반투명 효과
        alpha = 100 + int(55 * math.sin(pandora_box_rainbow_animation * 0.05 + i))
        
        # 원 그리기
        circle_surface = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
        pygame.draw.circle(circle_surface, (*color, alpha), (radius, radius), radius, 3)
        
        # 회전 위치 계산
        offset_x = math.cos(angle_rad) * 20
        offset_y = math.sin(angle_rad) * 20
        
        SCREEN.blit(circle_surface, 
                   (center_x - radius + offset_x, 
                    center_y - radius + offset_y))
    
    # 중앙에 빛나는 효과
    glow_radius = 30 + math.sin(pandora_box_rainbow_animation * 0.15) * 10
    glow_alpha = 150 + int(50 * math.sin(pandora_box_rainbow_animation * 0.2))
    glow_surface = pygame.Surface((glow_radius * 2, glow_radius * 2), pygame.SRCALPHA)
    pygame.draw.circle(glow_surface, (255, 255, 255, glow_alpha), 
                      (glow_radius, glow_radius), glow_radius)
    SCREEN.blit(glow_surface, (center_x - glow_radius, center_y - glow_radius))
    
    # 효과 텍스트 표시 제거 - 무지개 애니메이션만 표시

def activate_grenade():
    """수류탄 투척 함수 - 0.5초 투척 모션 후 발사"""
    global grenade_throwing, grenade_throw_timer, grenade_target_x, grenade_target_y, grenade_shake_timer
    import items
    # 화면 흔들림 타이머 초기화
    grenade_shake_timer = 0
    
    # 목표 지점 미리 계산
    grenade_target_x = BOSS.centerx + random.uniform(-30, 30)  # 보스 중심 근처 랜덤
    grenade_target_y = BOSS.centery  # 보스 패들 중앙
    
    # 투척 모션 시작
    grenade_throwing = True
    
    # 코만도암 효과 적용 (준비시간 단축)
    if items.commando_arm_obtained:
        print(f"   !   0.2")
        grenade_throw_timer = 12  # 0.2초 (60fps * 0.2)
        # 코만도암 착용시 짧은 준비 사운드 (maxtime 파라미터로 재생 시간 제한)
        SOUND_THROW_BEFORE.play(maxtime=200)  # 200ms만 재생
    else:
        # 일반 투척 시간
        grenade_throw_timer = 36  # 0.6초 (60fps * 0.6)
        print(f"   : {grenade_throw_timer/60:.1f}")
        # 일반 준비 사운드 전체 재생
        play_sound_with_volume(SOUND_THROW_BEFORE)
    # 효과음 재생 (투척 시작)
    play_active_item_sound()
    print(f"   ! {grenade_throw_timer/60:.1f}  .")
def throw_grenade():
    """실제 수류탄 투척 (모션 후 실행)"""
    global grenades, BOSS, PLAYER, grenade_target_x, grenade_target_y
    import items
    # 투척 방향 계산
    dx = grenade_target_x - PLAYER.centerx
    dy = grenade_target_y - PLAYER.centery
    distance = math.sqrt(dx**2 + dy**2)
    # 속도 정규화 (일정한 속도로 날아가도록)
    base_speed = 12  # 수류탄 기본 속도
    # 코만도암 효과 적용 (투척 속도 50% 증가)
    if items.commando_arm_obtained:
        speed = base_speed * 1.5  # 12 → 18
        print(f"  !  : {speed:.1f} (: {base_speed})")
    else:
        speed = base_speed
        print(f"   : {speed:.1f}")
    vel_x = (dx / distance) * speed if distance > 0 else 0
    vel_y = (dy / distance) * speed if distance > 0 else -speed
    grenade = {
        "x": PLAYER.centerx,
        "y": PLAYER.centery,
        "vel_x": vel_x,
        "vel_y": vel_y,
        "target_x": grenade_target_x,
        "target_y": grenade_target_y,
        "gravity": 0,  # 중력 제거 - 직선으로 날아감
        "rotation": 0  # 회전 각도
    }
    grenades.append(grenade)
    
    # 코만도암이 있으면 첫 프레임 이동을 즉시 실행
    if items.commando_arm_obtained:
        grenade["x"] += grenade["vel_x"]
        grenade["y"] += grenade["vel_y"]
        print(f"[DEBUG]  !")
    
    print(f"  !  : X={grenade_target_x:.1f}, Y={grenade_target_y:.1f}")


def activate_spider_mine():
    """스파이더지뢰 배치 시작"""
    global spider_mines

    side = "left" if PLAYER.centerx <= WIDTH / 2 else "right"
    size = 26

    floor_center_y = min(PLAYER.bottom - size // 2 + 2, HEIGHT - size // 2 - SPIDER_MINE_FLOOR_CLEARANCE)
    wall_center_x = size // 2 + SPIDER_MINE_WALL_OFFSET if side == "left" else WIDTH - (size // 2 + SPIDER_MINE_WALL_OFFSET)
    corner_center_y = max(BOSS.top + size // 2 + SPIDER_MINE_CORNER_OFFSET_Y, size // 2 + 12)
    corner_center_y = min(corner_center_y, BOSS.bottom + size)

    spawn_offset = size + 10
    start_x = PLAYER.left - spawn_offset if side == "left" else PLAYER.right + spawn_offset
    start_x = max(size // 2 + 4, min(WIDTH - size // 2 - 4, start_x))

    mine = {
        "x": float(start_x),
        "y": float(floor_center_y),
        "target_x": float(start_x),
        "target_y": float(floor_center_y),
        "wall_x": float(wall_center_x),
        "floor_y": float(floor_center_y),
        "corner_y": float(corner_center_y),
        "state": "spawn",
        "delay_timer": SPIDER_MINE_START_DELAY_FRAMES,
        "flash_timer": SPIDER_MINE_START_DELAY_FRAMES,
        "side": side,
        "size": size,
        "glow_phase": 0.0,
        "armed_elapsed": 0.0,
        "step_phase": 0.0,
        "embed_timer": 0,
        "embed_depth": 0.0,
        "embed_slam_timer": 0,
    }

    spider_mines.append(mine)
    print("🕷️ 스파이더지뢰 전개 준비! 1초 후 돌입합니다.")


def _move_spider_mine_towards(mine, target_x, target_y, speed):
    dx = target_x - mine["x"]
    dy = target_y - mine["y"]
    distance = math.hypot(dx, dy)
    if distance <= speed or distance == 0:
        mine["x"] = target_x
        mine["y"] = target_y
        return True
    mine["x"] += (dx / distance) * speed
    mine["y"] += (dy / distance) * speed
    return False


def get_spider_mine_rect(mine):
    size = mine.get("size", 26)
    center_x = mine["x"]
    center_y = mine["y"] + mine.get("embed_depth", 0.0)
    return pygame.Rect(int(center_x - size / 2), int(center_y - size / 2), size, size)


def apply_spider_mine_slow():
    """보스 이동속도 감소 효과 적용"""
    global spider_mine_slow_active, spider_mine_slow_timer, spider_mine_slow_text_timer
    spider_mine_slow_active = True
    spider_mine_slow_timer = SPIDER_MINE_SLOW_DURATION
    spider_mine_slow_text_timer = SPIDER_MINE_TEXT_DURATION
    print("🕷️ 거미지뢰 폭발! 보스 이동속도가 30% 감소합니다.")


def trigger_spider_mine_explosion(mine, reason="boss"):
    """지뢰 폭발 처리"""
    if mine.get("state") == "exploding":
        return

    mine["state"] = "exploding"
    mine["explosion_timer"] = SPIDER_MINE_EXPLOSION_DURATION
    try:
        play_sound_with_volume(SOUND_GRENADE)
    except Exception:
        pass

    impact_x = mine["x"]
    impact_y = mine["y"] + mine.get("embed_depth", 0.0)

    if reason == "boss":
        global boss_knockback_timer, boss_knockback_vel, boss_knockback_active
        global boss_knockback_offset_x, boss_knockback_offset_y, boss_stunned_timer
        global grenade_shake_timer

        boss_rect = BOSS if 'BOSS' in globals() else None
        if boss_rect:
            edge_margin = max(10, boss_rect.width // 2)
            if boss_rect.left <= edge_margin:
                knockback_direction = 1
            elif boss_rect.right >= WIDTH - edge_margin:
                knockback_direction = -1
            else:
                knockback_direction = 1 if impact_x < boss_rect.centerx else -1

            boss_knockback_timer = BLACKSMITH_TURRET_STUN_DURATION
            boss_knockback_vel = knockback_direction * BLACKSMITH_TURRET_KNOCKBACK_SPEED
            boss_knockback_active = False
            boss_knockback_offset_x = 0
            boss_knockback_offset_y = 0
            boss_stunned_timer = max(boss_stunned_timer, BLACKSMITH_TURRET_STUN_DURATION)

        grenade_shake_timer = max(grenade_shake_timer, 25)

    try:
        effects_manager.create_impact_effect(int(impact_x), int(impact_y), 90, is_player=False)
        effects_manager.spawn_star_particles(int(impact_x), int(impact_y), count=10)
        effects_manager.spawn_flame_particles(int(impact_x), int(impact_y), count=8)
        effects_manager.spawn_construction_smoke(int(impact_x), int(impact_y), count=6, spread=18)
    except Exception:
        pass

    if reason == "boss":
        apply_spider_mine_slow()


def update_spider_mines():
    """스파이더지뢰 이동 및 상태 업데이트"""
    global spider_mines, spider_mine_slow_active, spider_mine_slow_timer, spider_mine_slow_text_timer

    updated = []
    for mine in spider_mines:
        state = mine["state"]

        if state == "spawn":
            mine["delay_timer"] -= 1
            if mine["delay_timer"] <= 0:
                mine["state"] = "floor"
                mine["target_x"] = mine["wall_x"]
                mine["target_y"] = mine["floor_y"]
                mine["flash_timer"] = 30
        elif state == "floor":
            mine["step_phase"] = mine.get("step_phase", 0.0) + 0.42
            mine["y"] = mine["floor_y"]
            if _move_spider_mine_towards(mine, mine["wall_x"], mine["floor_y"], SPIDER_MINE_TRAVEL_SPEED):
                mine["state"] = "wall"
                mine["target_y"] = mine["corner_y"]
                mine["x"] = mine["wall_x"]
        elif state == "wall":
            mine["step_phase"] = mine.get("step_phase", 0.0) + 0.38
            mine["x"] = mine["wall_x"]
            if _move_spider_mine_towards(mine, mine["wall_x"], mine["corner_y"], SPIDER_MINE_CLIMB_SPEED):
                mine["state"] = "embedding"
                mine["embed_timer"] = SPIDER_MINE_EMBED_DELAY_FRAMES
                mine["x"] = mine["wall_x"]
                mine["y"] = mine["corner_y"]
        elif state == "embedding":
            mine["x"] = mine["wall_x"]
            mine["y"] = mine["corner_y"]
            mine["step_phase"] = mine.get("step_phase", 0.0) + 0.12
            mine["embed_timer"] -= 1
            if mine["embed_timer"] <= 0:
                mine["state"] = "armed"
                mine["embed_slam_timer"] = 10
                mine["embed_depth"] = SPIDER_MINE_MAX_EMBED_DEPTH
                mine["step_phase"] = 0.0
        elif state == "armed":
            mine["x"] = mine["wall_x"]
            mine["y"] = mine["corner_y"]
            mine["armed_elapsed"] = mine.get("armed_elapsed", 0.0) + 1
            mine["step_phase"] = mine.get("step_phase", 0.0) + 0.05
            if mine.get("embed_slam_timer", 0) > 0:
                mine["embed_slam_timer"] -= 1
                easing = mine["embed_slam_timer"] / 10.0
                mine["embed_depth"] = SPIDER_MINE_MAX_EMBED_DEPTH * easing
            else:
                mine["embed_depth"] = max(2.5, mine.get("embed_depth", 0.0) * 0.9)
            if mine["armed_elapsed"] >= SPIDER_MINE_SELF_DESTRUCT_TIME:
                trigger_spider_mine_explosion(mine, reason="timer")
            elif BOSS.colliderect(get_spider_mine_rect(mine)):
                trigger_spider_mine_explosion(mine)
        elif state == "exploding":
            mine["explosion_timer"] -= 1
            if mine["explosion_timer"] <= 0:
                continue

        mine["glow_phase"] = mine.get("glow_phase", 0.0) + 0.08
        if mine.get("flash_timer", 0) > 0:
            mine["flash_timer"] -= 1
        updated.append(mine)

    spider_mines = updated

    if spider_mine_slow_active:
        if spider_mine_slow_timer > 0:
            spider_mine_slow_timer -= 1
        if spider_mine_slow_timer <= 0:
            spider_mine_slow_active = False
            spider_mine_slow_timer = 0

    if spider_mine_slow_text_timer > 0:
        spider_mine_slow_text_timer -= 1


def draw_spider_mines(screen):
    """스파이더지뢰 렌더링"""
    for mine in spider_mines:
        size = mine.get("size", 26)
        state = mine["state"]
        center_x = mine["x"]
        center_y = mine["y"] + mine.get("embed_depth", 0.0)

        if state == "exploding":
            progress = 1.0 - (mine["explosion_timer"] / SPIDER_MINE_EXPLOSION_DURATION)
            max_radius = size + 30
            radius = int(size + progress * (max_radius - size))
            alpha = max(0, int(200 * (1.0 - progress)))
            explosion_surface = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)
            pygame.draw.circle(explosion_surface, (255, 160, 90, alpha), (radius, radius), radius)
            pygame.draw.circle(explosion_surface, (255, 230, 180, alpha // 2), (radius, radius), max(4, radius // 2))
            screen.blit(explosion_surface, (center_x - radius, center_y - radius))
            continue

        body_surface = pygame.Surface((size, size), pygame.SRCALPHA)
        body_color = (58, 64, 90)
        glow_strength = 0.4 + 0.4 * math.sin(mine.get("glow_phase", 0.0))
        accent_color = (
            int(80 + glow_strength * 120),
            int(40 + glow_strength * 60),
            int(120 + glow_strength * 100),
        )

        # 몸체 기본 원을 먼저 그린다
        pygame.draw.circle(body_surface, body_color, (size // 2, size // 2), size // 2 - 2)

        step_phase = mine.get("step_phase", 0.0)
        leg_amp = 4.4 if state in ("floor", "wall") else 1.6
        leg_offsets = [
            (-11, 9, 0.0),
            (-13, 3, 0.9),
            (-9, -3, 1.8),
            (11, 9, 3.0),
            (13, 3, 3.9),
            (9, -3, 4.8),
        ]
        leg_color_outer = (30, 35, 55)
        leg_color_inner = (150, 170, 220)
        contact_dir = -1 if mine["side"] == "left" else 1
        leg_visibility = 1.0
        if state == "embedding":
            embed_progress = 1.0 - (mine.get("embed_timer", 0) / max(1, SPIDER_MINE_EMBED_DELAY_FRAMES))
            leg_visibility = max(0.0, 1.0 - embed_progress)
        elif state == "armed":
            leg_visibility = 0.0
        leg_outer_width = max(1, int(round(5 * leg_visibility))) if leg_visibility > 0 else 0
        leg_inner_width = max(1, int(round(2 * leg_visibility))) if leg_visibility > 0 else 0
        for index, (dx, dy, phase_shift) in enumerate(leg_offsets):
            if leg_visibility <= 0.01:
                continue
            swing = math.sin(step_phase + phase_shift) * leg_amp
            if state in ("wall", "embedding", "armed"):
                base_x = size // 2 + dx * 0.2
                base_y = size // 2 + dy * 0.15 + 2
                tip_x = size // 2 + contact_dir * (size // 2 - 3)
                tip_y = size // 2 + dy * 0.6 + math.cos(step_phase * 0.45 + phase_shift) * 1.6
            else:
                base_x = size // 2 + dx * 0.35
                base_y = size // 2 + 3
                tip_x = size // 2 + (dx * 1.4 + swing) * leg_visibility
                tip_y = size - 4 + math.cos(step_phase * 0.5 + phase_shift) * (2.4 * leg_visibility)
            base_pos = (int(base_x), int(base_y))
            tip_pos = (int(tip_x), int(tip_y))
            if leg_outer_width > 0:
                pygame.draw.line(body_surface, leg_color_outer, base_pos, tip_pos, leg_outer_width)
            if leg_inner_width > 0:
                pygame.draw.line(body_surface, leg_color_inner, (base_pos[0], base_pos[1] - 2), (tip_pos[0], tip_pos[1] - 2), leg_inner_width)

        # 상부 장갑과 고정 링은 다리를 그린 후 얹는다
        pygame.draw.circle(body_surface, accent_color, (size // 2, size // 2 - 1), size // 2 - 5)

        if state == "armed":
            pulse = 0.6 + 0.4 * math.sin(mine.get("armed_elapsed", 0.0) * 0.18)
            core_radius = max(3, int((size // 2 - 7) * pulse))
            pygame.draw.circle(body_surface, (255, 110, 140), (size // 2, size // 2 - 2), core_radius)
        else:
            pygame.draw.circle(body_surface, (200, 90, 130), (size // 2, size // 2 - 2), max(3, size // 2 - 8))

        # 설치 대기 중/임베딩 효과
        if state == "embedding":
            embed_progress = 1.0 - (mine.get("embed_timer", 0) / max(1, SPIDER_MINE_EMBED_DELAY_FRAMES))
            halo_alpha = int(120 * embed_progress)
            halo_surface = pygame.Surface((size * 2, size * 2), pygame.SRCALPHA)
            pygame.draw.circle(halo_surface, (220, 160, 255, halo_alpha), (size, size), size)
            screen.blit(halo_surface, (center_x - size, center_y - size))

        flash_timer = mine.get("flash_timer", 0)
        armed_time = mine.get("armed_elapsed", 0.0)
        flash_interval = SPIDER_MINE_FLASH_INTERVAL
        if state == "armed":
            if armed_time >= SPIDER_MINE_SELF_DESTRUCT_FAST:
                flash_interval = max(1, SPIDER_MINE_FLASH_INTERVAL // 3)
            elif armed_time >= SPIDER_MINE_SELF_DESTRUCT_WARNING:
                flash_interval = max(2, SPIDER_MINE_FLASH_INTERVAL // 2)

        if flash_timer > 0 and (flash_timer // flash_interval) % 2 == 0:
            pygame.draw.circle(body_surface, (255, 200, 120, 170), (size // 2, size // 2 - 2), size // 2 - 4)

        render_x = int(center_x - size / 2)
        render_y = int(center_y - size / 2)
        if mine["side"] == "left":
            render_x -= 2
        else:
            render_x += 2

        screen.blit(body_surface, (render_x, render_y))


def draw_spider_mine_slow_effect(screen):
    """스파이더지뢰 둔화 시각 효과"""
    if spider_mine_slow_active or spider_mine_slow_timer > 0:
        remaining_ratio = spider_mine_slow_timer / SPIDER_MINE_SLOW_DURATION if SPIDER_MINE_SLOW_DURATION else 1.0
        intensity = 0.45 + 0.55 * max(0.0, min(1.0, remaining_ratio))
        wave_surface = create_slow_wave_surface(132, 56, (110, 170, 255), intensity=intensity)
        wave_rect = wave_surface.get_rect(midbottom=(BOSS.centerx, BOSS.top + 8))
        screen.blit(wave_surface, wave_rect)

    # 텍스트 알림 제거 (시각 효과만 유지)
def install_smoke_grenade():
    """연막탄 즉시 설치 (설치류 아이템)"""
    global smoke_grenades, PLAYER, smoke_grenade_target_x, smoke_grenade_target_y
    global current_stage, animated_bg_stage4
    
    # 즉시 목표 지점에 설치 (투척 없이 바로 도착 상태로)
    smoke_grenade = {
        "x": smoke_grenade_target_x,  # 즉시 목표 지점에
        "y": smoke_grenade_target_y,  # 즉시 목표 지점에
        "vel_x": 0,  # 이동 없음
        "vel_y": 0,  # 이동 없음
        "gravity": 0,  # 중력 없음
        "target_x": smoke_grenade_target_x,
        "target_y": smoke_grenade_target_y,
        "timer": 0,  # 도착 후 타이머
        "arrived": True,  # 이미 도착한 상태
        "rotation": 0,
        "trail": []  # 궤적 표시용 (설치류이므로 불필요하지만 호환성 유지)
    }
    smoke_grenades.append(smoke_grenade)
    print(f"  ! : X={smoke_grenade_target_x:.0f}, Y={smoke_grenade_target_y:.0f}")
    
    # Stage 4에서 화로 점화 시스템 (연막탄이 화로에 닿으면 불이 붙고 몽크 소환)
    if current_stage == 4 and animated_bg_stage4 is not None:
        # 화로 위치 가져오기
        brazier_x, brazier_y = animated_bg_stage4.get_brazier_position()
        
        # 연막탄과 화로 사이의 거리 계산
        distance_to_brazier = math.sqrt((smoke_grenade_target_x - brazier_x)**2 + 
                                       (smoke_grenade_target_y - brazier_y)**2)
        
        # 연막이 화로에 닿을 수 있는 거리인지 확인 (연막 최대 반경 180 고려)
        if distance_to_brazier <= 200:  # 연막 반경 + 화로 히트박스 여유
            print(f"    ! : {distance_to_brazier:.1f}")
            smoke_grenade['is_brazier_smoke'] = True  # 화로 연막탄 표시
def throw_flare():
    """실제 조명탄 투척 (모션 후 실행)"""
    global flares, BOSS, PLAYER, flare_target_x, flare_target_y
    import items
    # 투척 방향 계산
    dx = flare_target_x - PLAYER.centerx
    dy = flare_target_y - PLAYER.centery
    distance = math.sqrt(dx**2 + dy**2)
    # 속도 정규화 (일정한 속도로 날아가도록)
    base_speed = 9.6  # 조명탄 기본 속도
    # 코만도암 효과 적용 (투척 속도 50% 증가)
    if items.commando_arm_obtained:
        speed = base_speed * 1.5  # 9.6 → 14.4
        print(f"  !  : {speed:.1f} (: {base_speed})")
    else:
        speed = base_speed
        print(f"   : {speed:.1f}")
    vel_x = (dx / distance) * speed if distance > 0 else 0
    vel_y = (dy / distance) * speed if distance > 0 else -speed
    flare = {
        "x": PLAYER.centerx,
        "y": PLAYER.centery,
        "vel_x": vel_x,
        "vel_y": vel_y,
        "target_x": flare_target_x,
        "target_y": flare_target_y,
        "gravity": 0,  # 중력 제거 - 직선으로 날아감
        "rotation": 0,  # 회전 각도
        "timer": 0,  # 도착 후 타이머
        "exploded": False,
        "arrived": False  # 도착 여부 플래그 추가
    }
    flares.append(flare)
    
    # 코만도암이 있으면 첫 프레임 이동을 즉시 실행
    if items.commando_arm_obtained:
        flare["x"] += flare["vel_x"]
        flare["y"] += flare["vel_y"]
        if flare["gravity"] > 0:
            flare["vel_y"] += flare["gravity"]
        print(f"[DEBUG]  !")
    
    print(f"  !  : X={flare_target_x:.1f}, Y={flare_target_y:.1f}")
def activate_predictor():
    """레이저스코프 활성화 함수 - 10초간 공의 궤적 예측"""
    global predictor_active, predictor_timer, predicted_trajectory
    predictor_active = True
    predictor_timer = 600  # 10초 지속 (60fps * 10초 = 600)
    predicted_trajectory = []  # 초기화
    # 효과음 재생
    try:
        play_active_item_sound()
    except:
        pass
    print("! 레이저스코프 활성화 - 10초간 궤적 예측 !")
def calculate_trajectory():
    """공이 보스 패들에서 출발할 때 한 번만 궤적을 계산하는 함수 (보스 기술 예측 포함)"""
    global ball_vel, BALL, WIDTH, HEIGHT, PLAYER, BOSS, predicted_trajectory, last_prediction_ball_y
    global last_prediction_skill_signature
    global current_stage, boss_special_ready, boss_special_gauge, boss_special_ready_stage4, boss_special_gauge_stage4
    
    # BALL이 None인지 확인
    if BALL is None:
        return
    global meditation_active, meditation_timer, stage4_magnetic_active, stage4_magnetic_timer
    global flame_trail_active, flame_trail_phase, flame_trail_rng, power_smashing_parabola_active, power_smashing_start_time, power_smashing_rng
    global quake_active, quake_timer, tears_active, tears_timer, quake_last_used_time, last_tears_cast_time
    global QUAKE_COOLDOWN, TEARS_COOLDOWN
    global stopwatch_active, stopwatch_timer, stopwatch_recovery_timer, stopwatch_original_ball_vel, stopwatch_forced_upward

    current_skill_signature = (
        quake_active,
        quake_timer if quake_active else 0,
        tears_active,
        meditation_active,
        meditation_timer if meditation_active else 0,
        stage4_magnetic_active,
        stage4_magnetic_timer if stage4_magnetic_active else 0,
        flame_trail_active,
        flame_trail_phase if flame_trail_active else 0,
        power_smashing_parabola_active,
        power_smashing_start_time if power_smashing_parabola_active else 0,
    )

    skill_active_now = (
        quake_active
        or tears_active
        or meditation_active
        or stage4_magnetic_active
        or flame_trail_active
        or power_smashing_parabola_active
    )

    boss_launch_threshold = 160
    if BOSS is not None:
        boss_launch_threshold = max(120, BOSS.bottom + 40)

    recalc_needed = False
    skill_type_debug = "unknown"
    if ball_vel[1] > 0 and BALL.centery <= boss_launch_threshold and BALL.centery != last_prediction_ball_y:
        recalc_needed = True
        recalc_reason = "ball_launch_window"
    elif not predicted_trajectory and ball_vel[1] > 0:
        recalc_needed = True
        recalc_reason = "trajectory_empty"
    elif current_skill_signature != last_prediction_skill_signature and (ball_vel[1] > 0 or skill_active_now):
        recalc_needed = True
        recalc_reason = "skill_signature_changed"
    else:
        recalc_reason = "no_trigger"

    if DEBUG_PREDICTOR:
        print(f"[Predictor] check stage={current_stage} ball_y={BALL.centery:.1f} vy={ball_vel[1]:.2f} threshold={boss_launch_threshold} needed={recalc_needed} reason={recalc_reason}")

    if not recalc_needed:
        return
    

    last_prediction_ball_y = BALL.centery
    last_prediction_skill_signature = current_skill_signature

    freeze_frames = stopwatch_timer if stopwatch_active and stopwatch_timer > 0 else 0
    recovery_frames = stopwatch_recovery_timer if stopwatch_active and stopwatch_recovery_timer > 0 else 0
    resume_velocity = None
    if stopwatch_original_ball_vel:
        resume_velocity = [stopwatch_original_ball_vel[0], stopwatch_original_ball_vel[1]]
    else:
        recovery_frames = 0
    resume_pending = freeze_frames > 0 and resume_velocity is not None

    # 시뮬레이션용 변수
    sim_x = BALL.centerx
    sim_y = BALL.centery
    sim_vel_x = ball_vel[0]
    sim_vel_y = ball_vel[1]
    # 새로운 궤적 계산
    predicted_trajectory = []

    #  보스 기술 발동 예측 및 현재 활성 기술 감지
    skill_probability = 0.0
    skill_type = None

    # 현재 활성화된 기술 확인 (100% 확률)
    if quake_active:
        skill_probability = 1.0
        skill_type = "quake"
    elif tears_active:
        skill_probability = 1.0
        skill_type = "tears"
    elif meditation_active:
        skill_probability = 1.0
        skill_type = "meditation"
    elif stage4_magnetic_active:
        skill_probability = 1.0
        skill_type = "magnetic"
    elif flame_trail_active:
        skill_probability = 1.0
        skill_type = "flame_trail"
    elif power_smashing_parabola_active:
        skill_probability = 1.0
        skill_type = "power_smashing"
    else:
        # 기술이 활성화되지 않은 경우 예측
        # Stage별 보스 기술 예측
        if current_stage == 2:
            # 정글맨 - 정글지진
            current_time = pygame.time.get_ticks()
            time_since_last_quake = current_time - quake_last_used_time
            if time_since_last_quake >= QUAKE_COOLDOWN:
                # 쿨타임이 끝났으면 높은 확률로 발동 예측
                skill_probability = 0.6
                skill_type = "quake"
            elif time_since_last_quake >= QUAKE_COOLDOWN * 0.8:
                # 쿨타임 80% 지났으면 중간 확률
                skill_probability = 0.3
                skill_type = "quake"
        elif current_stage == 3:
            # 멘헤라걸 - 눈물샤워 (플레이어 속도 감소)
            if boss_special_ready:
                skill_probability = 0.8
                skill_type = "tears"
            elif boss_special_gauge > 70:
                skill_probability = 0.3
                skill_type = "tears"
        elif current_stage == 4:
            # 대쉬스피릿 - 자기장 또는 명상타임
            if boss_special_ready_stage4:
                skill_probability = 0.7
                if meditation_active:
                    skill_type = "meditation"
                elif stage4_magnetic_active:
                    skill_type = "magnetic"
                else:
                    skill_type = "magnetic" if random.random() < 0.6 else "meditation"
            elif boss_special_gauge_stage4 > 80:
                skill_probability = 0.4
                skill_type = "magnetic"
        elif current_stage == 5:
            # 홍련봄버 - 화염궤적
            if boss_special_ready:
                skill_probability = 0.6
                skill_type = "flame_trail"
            elif boss_special_gauge > 60:
                skill_probability = 0.2
                skill_type = "flame_trail"

    skill_type_debug = skill_type

    # 파워스매싱 예측 (모든 스테이지)
    if boss_special_gauge > 90:
        skill_probability = max(skill_probability, 0.5)
        if not skill_type:
            skill_type = "power_smashing"
    elif boss_special_gauge > 70:
        skill_probability = max(skill_probability, 0.2)
        if not skill_type:
            skill_type = "power_smashing"

    high_detail_skills = {"flame_trail", "power_smashing", "magnetic", "meditation", "quake"}
    sampling_interval = 1 if skill_type in high_detail_skills else 3

    if ball_vel[1] <= 0 and not skill_type:
        return

    # 최대 500프레임 예측 (충분한 시간)
    max_steps = 500
    random_state = random.getstate()
    base_ticks = pygame.time.get_ticks()
    sim_meditation_timer = meditation_timer if meditation_active else meditation_duration
    sim_meditation_angle = meditation_angle if meditation_active else 0
    sim_magnetic_curve = magnet_curve_angle if stage4_magnetic_active else 0
    sim_magnetic_timer = stage4_magnetic_timer if stage4_magnetic_active else 200
    base_flame_vec = globals().get("flame_trail_base_vel")
    if isinstance(base_flame_vec, pygame.math.Vector2):
        sim_flame_base_vel = (base_flame_vec.x, base_flame_vec.y)
    elif isinstance(base_flame_vec, (list, tuple)):
        sim_flame_base_vel = (base_flame_vec[0], base_flame_vec[1])
    else:
        sim_flame_base_vel = None
    flame_start_time_snapshot = globals().get("flame_trail_start_time", base_ticks)
    sim_flame_phase = flame_trail_phase if flame_trail_active else 0
    sim_flame_timer = flame_trail_timer if flame_trail_active else TWO_SECONDS_FRAMES
    sim_flame_rng = None
    if flame_trail_rng is not None:
        sim_flame_rng = random.Random()
        sim_flame_rng.setstate(flame_trail_rng.getstate())
    sim_quake_timer = quake_timer if quake_active else quake_duration
    sim_quake_restore_speed = original_ball_speed_quake[:] if quake_active else None
    sim_quake_rng = None
    if quake_rng is not None:
        sim_quake_rng = random.Random()
        sim_quake_rng.setstate(quake_rng.getstate())
    sim_power_smashing_initial_boost = power_smashing_initial_boost
    sim_power_smashing_start = power_smashing_start_time
    sim_power_smashing_direction = power_smashing_direction
    sim_power_smashing_target_speed = power_smashing_target_speed
    frame_time_ms = 1000.0 / FPS if FPS else 16.6667
    sim_power_smashing_rng = None
    if power_smashing_rng is not None:
        sim_power_smashing_rng = random.Random()
        sim_power_smashing_rng.setstate(power_smashing_rng.getstate())

    try:
        for step in range(max_steps):
                if DEBUG_PREDICTOR and step < 5:
                    print(f"[Predictor] step={step} sim=({sim_x:.1f},{sim_y:.1f}) vel=({sim_vel_x:.2f},{sim_vel_y:.2f}) freeze={freeze_frames} recov={recovery_frames}")
                if freeze_frames > 0:
                    freeze_frames -= 1
                    if freeze_frames == 0 and resume_pending:
                        sim_vel_x = resume_velocity[0]
                        sim_vel_y = resume_velocity[1]
                        resume_pending = False
                    if step % sampling_interval == 0:
                        predicted_trajectory.append((int(sim_x), int(sim_y), 1.0))
                        if DEBUG_PREDICTOR and len(predicted_trajectory) <= 5:
                            print(f"[Predictor] append(freeze) step={step} point={(int(sim_x), int(sim_y))}")
                    continue

                if resume_pending and resume_velocity:
                    sim_vel_x = resume_velocity[0]
                    sim_vel_y = resume_velocity[1]
                    resume_pending = False

                if recovery_frames > 0 and resume_velocity:
                    recovery_ratio = 1 - (recovery_frames / STOPWATCH_RECOVERY_TIME)
                    effective_ratio = max(0.3, recovery_ratio)
                    original_speed = math.hypot(resume_velocity[0], resume_velocity[1])
                    target_speed = original_speed * effective_ratio
                    dir_x, dir_y = resume_velocity
                    direction_norm = math.hypot(dir_x, dir_y)
                    if direction_norm > 0:
                        direction_x = dir_x / direction_norm
                        direction_y = dir_y / direction_norm
                    else:
                        direction_x, direction_y = 0.0, -1.0
                    if stopwatch_forced_upward and direction_y >= 0:
                        direction_y = -abs(direction_y if abs(direction_y) > 1e-3 else 0.5)
                    sim_vel_x = direction_x * target_speed
                    sim_vel_y = direction_y * target_speed
                    recovery_frames -= 1
                    if recovery_frames == 0:
                        sim_vel_x = resume_velocity[0]
                        sim_vel_y = resume_velocity[1]

                skill_active_now = False
                if skill_type == "quake" and quake_active:
                    skill_active_now = True
                elif skill_type == "meditation" and meditation_active:
                    skill_active_now = True
                elif skill_type == "magnetic" and stage4_magnetic_active:
                    skill_active_now = True
                elif skill_type == "flame_trail" and flame_trail_active:
                    skill_active_now = True
                elif skill_type == "power_smashing" and power_smashing_parabola_active:
                    skill_active_now = True

                if skill_type and (skill_active_now or step > 30):
                    if skill_type == "quake":
                        if skill_active_now:
                            if sim_quake_timer > 0:
                                sim_quake_timer -= 1
                                if sim_quake_rng:
                                    shake_x = sim_quake_rng.uniform(-3, 3)
                                    shake_y = sim_quake_rng.uniform(-2, 2)
                                else:
                                    shake_x = random.uniform(-3, 3)
                                    shake_y = random.uniform(-2, 2)
                                sim_vel_x += shake_x
                                sim_vel_y += shake_y
                                dx = PLAYER.centerx - sim_x
                                dy = PLAYER.centery - sim_y
                                distance = math.hypot(dx, dy)
                                if distance > 10:
                                    influence = 0.15 / distance
                                    sim_vel_x += dx * influence * 0.01
                                    sim_vel_y += dy * influence * 0.01
                                max_speed = 8.0
                                sim_vel_x = max(-max_speed, min(max_speed, sim_vel_x))
                                sim_vel_y = max(-max_speed, min(max_speed, sim_vel_y))
                            elif sim_quake_restore_speed:
                                sim_vel_x = sim_quake_restore_speed[0]
                                sim_vel_y = sim_quake_restore_speed[1]
                        elif step - 30 < quake_duration:
                            shake_x = random.uniform(-3, 3)
                            shake_y = random.uniform(-2, 2)
                            sim_vel_x += shake_x * 0.3
                            sim_vel_y += shake_y * 0.3
                            dx = PLAYER.centerx - sim_x
                            dy = PLAYER.centery - sim_y
                            distance = math.hypot(dx, dy)
                            if distance > 10:
                                influence = 0.15 / distance
                                sim_vel_x += dx * influence * 0.005
                                sim_vel_y += dy * influence * 0.005
                            max_speed = 8
                            sim_vel_x = max(-max_speed, min(max_speed, sim_vel_x))
                            sim_vel_y = max(-max_speed, min(max_speed, sim_vel_y))

                    elif skill_type == "tears":
                        pass

                    elif skill_type == "meditation":
                        if skill_active_now:
                            if sim_meditation_timer > 0:
                                sim_meditation_timer -= 1
                                prev_x, prev_y = sim_x, sim_y
                                sim_meditation_angle += (720.0 / meditation_duration)
                                radian_angle = math.radians(sim_meditation_angle)
                                scale = meditation_orbit_radius * 1.5
                                denominator = 1 + math.sin(radian_angle) ** 2
                                sim_x = BOSS.centerx + scale * math.cos(radian_angle) / denominator
                                sim_y = BOSS.centery + scale * math.sin(radian_angle) * math.cos(radian_angle) / denominator
                                sim_vel_x = sim_x - prev_x
                                sim_vel_y = sim_y - prev_y
                                continue
                            else:
                                angle = random.randint(-45, 45)
                                speed = BALL_BASE_SPEED * random.uniform(1.3, 1.6)
                                sim_vel_x = speed * math.sin(math.radians(angle))
                                sim_vel_y = abs(speed * math.cos(math.radians(angle)))
                        elif step < 108:
                            sim_meditation_angle += (540.0 / 108.0)
                            radian_angle = math.radians(sim_meditation_angle)
                            scale = 80 * 1.5
                            denominator = 1 + math.sin(radian_angle) ** 2
                            sim_x = BOSS.centerx + scale * math.cos(radian_angle) / denominator
                            sim_y = BOSS.centery + scale * math.sin(radian_angle) * math.cos(radian_angle) / denominator
                            if step == 107:
                                angle = random.uniform(-60, 60)
                                base_speed = math.hypot(sim_vel_x, sim_vel_y)
                                speed = min(base_speed * 1.1, BALL_BASE_SPEED * 1.2)
                                sim_vel_x = speed * math.sin(math.radians(angle))
                                sim_vel_y = speed * math.cos(math.radians(angle))
                            continue

                    elif skill_type == "magnetic":
                        if skill_active_now:
                            if sim_magnetic_timer > 0:
                                sim_magnetic_timer -= 1
                                direction_to_player_x = PLAYER.centerx - sim_x
                                direction_to_player_y = PLAYER.centery - sim_y
                                distance = math.hypot(direction_to_player_x, direction_to_player_y)
                                if distance > 0:
                                    direction_to_player_x /= distance
                                    direction_to_player_y /= distance
                                    sim_magnetic_curve += 4.1
                                    theta = math.radians(sim_magnetic_curve)
                                    rotated_x = direction_to_player_x * math.cos(theta) - direction_to_player_y * math.sin(theta)
                                    rotated_y = direction_to_player_x * math.sin(theta) + direction_to_player_y * math.cos(theta)
                                    sim_vel_x += rotated_x * 1.8
                                    sim_vel_y += rotated_y * 1.8
                                    sim_vel_x *= 1.04
                                    sim_vel_y *= 1.04
                                    current_speed = math.hypot(sim_vel_x, sim_vel_y)
                                    max_speed = BALL_BASE_SPEED * 2.2
                                    if current_speed > max_speed:
                                        scale_factor = max_speed / current_speed
                                        sim_vel_x *= scale_factor
                                        sim_vel_y *= scale_factor
                            else:
                                recover_speed = max(player_last_shot_speed, BALL_BASE_SPEED)
                                direction_length = math.hypot(sim_vel_x, sim_vel_y)
                                if direction_length == 0:
                                    sim_vel_x, sim_vel_y = 0.0, recover_speed
                                else:
                                    sim_vel_x = (sim_vel_x / direction_length) * recover_speed
                                    sim_vel_y = (sim_vel_y / direction_length) * recover_speed
                                sim_magnetic_curve = 0
                        elif step < 150:
                            direction_to_player_x = PLAYER.centerx - sim_x
                            direction_to_player_y = PLAYER.centery - sim_y
                            distance = math.hypot(direction_to_player_x, direction_to_player_y)
                            if distance > 0:
                                direction_to_player_x /= distance
                                direction_to_player_y /= distance
                                sim_magnetic_curve += 4.1
                                curve_x = direction_to_player_x * math.cos(math.radians(sim_magnetic_curve)) * 1.8
                                curve_y = direction_to_player_y * math.sin(math.radians(sim_magnetic_curve)) * 1.8
                                sim_vel_x += curve_x * 0.1
                                sim_vel_y += curve_y * 0.1
                                sim_vel_x *= 1.02
                                sim_vel_y *= 1.02

                    elif skill_type == "flame_trail":
                        if skill_active_now:
                            sim_flame_timer = max(0, sim_flame_timer - 1)
                            sim_time_ms = base_ticks + step * frame_time_ms
                            if sim_flame_phase == 0:
                                sim_flame_phase = 1
                                flame_start_time_snapshot = sim_time_ms
                                dir_x = PLAYER.centerx - sim_x
                                dir_y = PLAYER.centery - sim_y
                                length = math.hypot(dir_x, dir_y)
                                if length != 0:
                                    sim_flame_base_vel = (dir_x / length, dir_y / length)
                                else:
                                    sim_flame_base_vel = (0.0, 1.0)
                            elapsed = max(0.0, (sim_time_ms - flame_start_time_snapshot) / 1000.0)
                            prev_x, prev_y = sim_x, sim_y
                            if elapsed < 1.0:
                                sim_x += math.sin(elapsed * 25) * 2
                                sim_y += math.cos(elapsed * 30) * 1
                                sim_vel_x = sim_x - prev_x
                                sim_vel_y = sim_y - prev_y
                                continue
                            if sim_flame_phase == 1:
                                sim_flame_phase = 2
                            accel_elapsed = elapsed - 1.0
                            max_speed = 6.0
                            accel_time = 6.0
                            current_speed = max_speed * min(1.0, accel_elapsed / accel_time)
                            current_speed = max(0.001, current_speed ** 1.2)
                            amplitude_x = min(40, 10 + accel_elapsed * 6)
                            amplitude_y = min(20, 5 + accel_elapsed * 3)
                            if sim_flame_rng:
                                noise_x = sim_flame_rng.uniform(-2, 2)
                                noise_y = sim_flame_rng.uniform(-1, 1)
                            else:
                                noise_x = random.uniform(-2, 2)
                                noise_y = random.uniform(-1, 1)
                            base_vx = sim_flame_base_vel[0] if sim_flame_base_vel else 0.0
                            base_vy = sim_flame_base_vel[1] if sim_flame_base_vel else 1.0
                            sim_x += base_vx * current_speed + math.sin(accel_elapsed * 6) * amplitude_x + noise_x
                            sim_y += base_vy * current_speed + math.cos(accel_elapsed * 3) * amplitude_y + noise_y
                            sim_vel_x = sim_x - prev_x
                            sim_vel_y = sim_y - prev_y
                            continue
                        elif step < 120:
                            wave_amplitude = 50
                            wave_frequency = 0.05
                            sim_vel_x += math.sin(step * wave_frequency) * 2

                    elif skill_type == "power_smashing":
                        if skill_active_now:
                            sim_time_ms = base_ticks + step * frame_time_ms
                            elapsed_time = max(0.0, (sim_time_ms - sim_power_smashing_start) / 1000.0)

                            if sim_power_smashing_initial_boost and power_smashing_boost_duration > 0:
                                current_speed = math.hypot(sim_vel_x, sim_vel_y)
                                boost_duration = power_smashing_boost_duration / 1000.0
                                boost_progress = min(1.0, elapsed_time / boost_duration) if boost_duration else 1.0
                                if sim_power_smashing_direction == 0:
                                    initial_boosted_speed = power_smashing_target_speed * 1.8
                                else:
                                    initial_boosted_speed = power_smashing_target_speed * 2.0
                                interpolated_speed = initial_boosted_speed - (initial_boosted_speed - power_smashing_target_speed) * boost_progress
                                if current_speed > 0:
                                    speed_ratio = interpolated_speed / current_speed
                                    sim_vel_x *= speed_ratio
                                    sim_vel_y *= speed_ratio
                                if boost_progress >= 1.0:
                                    sim_power_smashing_initial_boost = False

                            horizontal_decay = max(0.8, 1.0 - elapsed_time * 0.05)
                            chaos_source = sim_power_smashing_rng or random
                            chaos_factor = math.sin(elapsed_time * 5.0) * 0.05 + chaos_source.uniform(-0.04, 0.04)
                            horizontal_force = power_smashing_arc_strength * horizontal_decay * (0.5 + chaos_factor * 0.2)
                            sim_vel_x += horizontal_force

                            if elapsed_time < 1.8:
                                base_lift = power_smashing_gravity_effect * 1.5 * (1.8 - elapsed_time) / 1.8
                                vertical_chaos = math.cos(elapsed_time * 5.0) * 0.015
                                vertical_lift = base_lift + vertical_chaos
                                sim_vel_y -= vertical_lift
                            else:
                                base_pull = power_smashing_gravity_effect * 1.2 * (elapsed_time - 1.8)
                                descent_chaos = math.sin(elapsed_time * 7.0) * 0.015
                                vertical_pull = base_pull + descent_chaos
                                sim_vel_y += vertical_pull
                        else:
                            if step < 60:
                                arc_strength = 0.3
                                sim_vel_y += arc_strength

                if step % sampling_interval == 0:
                    if skill_probability > 0.3:
                        predicted_trajectory.append((int(sim_x), int(sim_y), skill_probability))
                    else:
                        predicted_trajectory.append((int(sim_x), int(sim_y), 1.0))
                    if DEBUG_PREDICTOR and len(predicted_trajectory) <= 5:
                        print(f"[Predictor] append step={step} point={(int(sim_x), int(sim_y))} prob={skill_probability:.2f}")

                sim_x += sim_vel_x
                sim_y += sim_vel_y

                if sim_x <= BALL.width // 2 or sim_x >= WIDTH - BALL.width // 2:
                    sim_vel_x = -sim_vel_x
                    sim_x = max(BALL.width // 2, min(WIDTH - BALL.width // 2, sim_x))

                player_collision_y = PLAYER.top - BALL.height / 2
                if sim_y >= player_collision_y:
                    predicted_trajectory.append((int(sim_x), int(sim_y), 1.0))
                    break

                if sim_y > HEIGHT + LARGE_SIZE:
                    break
    finally:
        random.setstate(random_state)

        if DEBUG_PREDICTOR:
            print(f"[Predictor] post-sim len={len(predicted_trajectory)} first={predicted_trajectory[:5] if predicted_trajectory else []}")

        if len(predicted_trajectory) < 2:
            fallback_points = []
            fallback_x = BALL.centerx
            fallback_y = BALL.centery
            fallback_vx = ball_vel[0]
            fallback_vy = ball_vel[1]
            for step in range(200):
                if step % 3 == 0:
                    fallback_points.append((int(fallback_x), int(fallback_y)))
                fallback_x += fallback_vx
                fallback_y += fallback_vy
                if fallback_x <= BALL.width // 2 or fallback_x >= WIDTH - BALL.width // 2:
                    fallback_vx = -fallback_vx
                    fallback_x = max(BALL.width // 2, min(WIDTH - BALL.width // 2, fallback_x))
                if fallback_y >= HEIGHT - 40:
                    fallback_points.append((int(fallback_x), int(fallback_y)))
                    break
                if fallback_y > HEIGHT + LARGE_SIZE:
                    break
            if len(fallback_points) >= 2:
                predicted_trajectory = fallback_points
                if DEBUG_PREDICTOR:
                    print(f"[Predictor] fallback len={len(fallback_points)} first_points={fallback_points[:5]}")
            else:
                if DEBUG_PREDICTOR:
                    print(f"[Predictor] fallback insufficient points len={len(fallback_points)}")
        else:
            if DEBUG_PREDICTOR:
                print(f"[Predictor] primary len={len(predicted_trajectory)} first={predicted_trajectory[:5]}")

        if skill_type in high_detail_skills and len(predicted_trajectory) > 2:
            raw_trajectory = predicted_trajectory[:]
            smoothing_radius_map = {
                "flame_trail": 2,
                "power_smashing": 2,
                "magnetic": 2,
                "meditation": 1,
                "quake": 5,
            }
            smoothing_radius = smoothing_radius_map.get(skill_type, 2)
            smoothed_trajectory = []
            for idx, point in enumerate(predicted_trajectory):
                start = max(0, idx - smoothing_radius)
                end = min(len(predicted_trajectory) - 1, idx + smoothing_radius)

                weighted_sum_x = 0.0
                weighted_sum_y = 0.0
                weight_total = 0.0
                for j in range(start, end + 1):
                    neighbor = predicted_trajectory[j]
                    distance = abs(j - idx)
                    weight = smoothing_radius - distance + 1
                    weighted_sum_x += neighbor[0] * weight
                    weighted_sum_y += neighbor[1] * weight
                    weight_total += weight

                avg_x = int(weighted_sum_x / weight_total)
                avg_y = int(weighted_sum_y / weight_total)

                if len(point) == 3:
                    smoothed_trajectory.append((avg_x, avg_y, point[2]))
                else:
                    smoothed_trajectory.append((avg_x, avg_y))

            if len(smoothed_trajectory) >= 2:
                predicted_trajectory = smoothed_trajectory
            else:
                predicted_trajectory = raw_trajectory

        if DEBUG_PREDICTOR:
            preview = predicted_trajectory[:5]
            print(f"[Predictor] calculated len={len(predicted_trajectory)} skill={skill_type_debug} freeze={freeze_frames} recovery={recovery_frames} first_points={preview}")
def draw_predicted_trajectory():
    """레이저스코프 활성화 시 저장된 궤적을 그리는 함수"""
    global predicted_trajectory, predictor_active, ball_vel
    global quake_active, meditation_active, stage4_magnetic_active, flame_trail_active, power_smashing_parabola_active
    
    if not predictor_active:
        return
    
    # 공이 위로 향하고 있으면 궤적 지우기 (플레이어가 친 경우)
    # 하지만 공이 아래로 향하면 궤적 계산 (보스가 친 경우)
    skill_active_now = (
        quake_active
        or meditation_active
        or stage4_magnetic_active
        or flame_trail_active
        or power_smashing_parabola_active
    )
    
    # 공이 아래로 향하고 있을 때만 궤적 계산 (ball_vel[1] > 0)
    if ball_vel[1] > 0 or skill_active_now:
        # 궤적 계산 (보스가 방금 친 공의 경우)
        calculate_trajectory()
    else:
        # 플레이어가 친 경우 궤적 지우기
        predicted_trajectory = []
        if DEBUG_PREDICTOR:
            print(f"[Predictor] draw cleared because ball heading up: vy={ball_vel[1]:.2f}")
        return

    if DEBUG_PREDICTOR:
        print(f"[Predictor] draw render len={len(predicted_trajectory)} first_points={predicted_trajectory[:5]}")
    # 저장된 궤적 그리기
    if len(predicted_trajectory) > 1:
        # 전체 궤적을 하나의 Surface에 그리기
        trajectory_surface = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        # 애니메이션을 위한 오프셋 (천천히 움직이는 효과)
        time_offset = pygame.time.get_ticks() * 0.001  # 천천히 움직이도록
        for i in range(len(predicted_trajectory) - 1):
            # 확률 정보가 포함된 경우와 아닌 경우 처리
            if len(predicted_trajectory[i]) == 3:
                start_pos = predicted_trajectory[i][:2]
                probability = predicted_trajectory[i][2]
            else:
                start_pos = predicted_trajectory[i]
                probability = 1.0
            
            if len(predicted_trajectory[i + 1]) == 3:
                end_pos = predicted_trajectory[i + 1][:2]
            else:
                end_pos = predicted_trajectory[i + 1]
            
            # 선분 길이 계산
            segment_length = ((end_pos[0] - start_pos[0])**2 + (end_pos[1] - start_pos[1])**2)**0.5
            # 점선 그리기 (움직이는 효과)
            dash_length = 15  # 각 대시 길이
            gap_length = 10   # 간격 길이
            total_pattern = dash_length + gap_length
            # 선분을 따라 점선 그리기
            if segment_length > 0:
                num_dashes = int(segment_length / total_pattern) + 2
                for dash in range(num_dashes):
                    # 애니메이션 오프셋 적용
                    dash_start = (dash * total_pattern + time_offset * 30) % segment_length
                    dash_end = min(dash_start + dash_length, segment_length)
                    if dash_start < segment_length:
                        # 대시의 시작과 끝 위치 계산
                        t_start = dash_start / segment_length
                        t_end = dash_end / segment_length
                        dash_start_x = start_pos[0] + (end_pos[0] - start_pos[0]) * t_start
                        dash_start_y = start_pos[1] + (end_pos[1] - start_pos[1]) * t_start
                        dash_end_x = start_pos[0] + (end_pos[0] - start_pos[0]) * t_end
                        dash_end_y = start_pos[1] + (end_pos[1] - start_pos[1]) * t_end
                        # 확률에 따라 색상과 투명도 조절
                        # 기술별로 다른 색상 사용
                        if probability < 1.0:
                            # 보스 기술 예측 경로 (기술별 색상, 확률에 따라 투명도 조절)
                            alpha = int(200 * probability)
                            
                            # Stage별로 색상 다르게 설정
                            if current_stage == 2:  # 정글맨 - 정글지진 (녹색)
                                color = (0, 255, 0, alpha)  # 녹색
                                center_color = (100, 255, 100, int(150 * probability))
                            elif current_stage == 3 and tears_active:  # 멘헤라걸 - 눈물샤워 (하늘색)
                                color = (0, 200, 255, alpha)  # 하늘색
                                center_color = (100, 200, 255, int(150 * probability))
                            else:
                                color = (255, 255, 0, alpha)  # 노란색 (기본)
                                center_color = (255, 255, 100, int(150 * probability))
                        else:
                            # 일반 경로 (빨간색)
                            color = (255, 0, 0, 200)
                            center_color = (255, 100, 100, 150)
                        
                        # 점선 그리기
                        pygame.draw.line(trajectory_surface, color, 
                                       (dash_start_x, dash_start_y), 
                                       (dash_end_x, dash_end_y), 5)
                        # 밝은 중심선 효과
                        pygame.draw.line(trajectory_surface, center_color, 
                                       (dash_start_x, dash_start_y), 
                                       (dash_end_x, dash_end_y), 3)
            # 궤적 포인트 표시 (일정 간격으로)
            if i % 4 == 0:
                # 빨간색 발광 효과
                pygame.draw.circle(trajectory_surface, (255, 150, 150, 100), start_pos, 6)
                pygame.draw.circle(trajectory_surface, (255, 50, 50, 200), start_pos, 4)
        # 궤적 Surface를 화면에 블릿
        SCREEN.blit(trajectory_surface, (0, 0))
    # 최종 도착 예상 지점에 타겟 마커 그리기
    if predicted_trajectory:
        # 최종 지점의 확률 정보 확인
        if len(predicted_trajectory[-1]) == 3:
            final_point = predicted_trajectory[-1][:2]
            final_probability = predicted_trajectory[-1][2]
        else:
            final_point = predicted_trajectory[-1]
            final_probability = 1.0
        
        # 타겟 십자선 그리기 - 크고 명확하게
        marker_surface = pygame.Surface((80, 80), pygame.SRCALPHA)
        
        # 확률에 따라 색상 결정
        if final_probability < 1.0:
            # 기술별 타겟 색상
            if current_stage == 2:  # 정글지진 (녹색)
                marker_color = (0, 255, 0, int(200 * final_probability))
                line_color = (0, 255, 0, int(255 * final_probability))
                text_color = (0, 255, 0)
            elif current_stage == 3 and tears_active:  # 눈물샤워 (하늘색)
                marker_color = (0, 200, 255, int(200 * final_probability))
                line_color = (0, 200, 255, int(255 * final_probability))
                text_color = (0, 200, 255)
            else:  # 기본 (노란색)
                marker_color = (255, 255, 0, int(200 * final_probability))
                line_color = (255, 255, 0, int(255 * final_probability))
                text_color = (255, 255, 0)
            
            # 확률 텍스트 표시
            try:
                font = pygame.font.Font(resource_path("NeoDGM.ttf"), 16)
            except:
                font = pygame.font.Font(None, 16)
            prob_text = font.render(f"{int(final_probability * 100)}%", True, text_color)
            marker_surface.blit(prob_text, (25, 5))
        else:
            # 일반 타겟 (빨간색)
            marker_color = (255, 0, 0, 200)
            line_color = (255, 0, 0, 255)
        
        # 외부 원
        pygame.draw.circle(marker_surface, marker_color, (40, 40), 30, 3)
        # 십자선
        pygame.draw.line(marker_surface, line_color, (40, 10), (40, 70), 3)
        pygame.draw.line(marker_surface, line_color, (10, 40), (70, 40), 3)
        # 내부 점
        pygame.draw.circle(marker_surface, (255, 50, 50, 255), (40, 40), 5)
        # 빛나는 효과
        for radius in range(10, 35, 5):
            alpha = 50 - radius
            pygame.draw.circle(marker_surface, (255, 100, 100, alpha), (40, 40), radius, 1)
        SCREEN.blit(marker_surface, (final_point[0] - 40, final_point[1] - 40))

def render_throwing_item_cooldown():
    """화기류 아이템 라운드 시작 3초 제한 표시"""
    global round_start_time, active_item_slot
    
    current_time = pygame.time.get_ticks()
    time_since_round_start = current_time - round_start_time
    
    # 3초가 지나면 표시하지 않음
    if time_since_round_start >= 3000:
        return
    
    # 화기류 아이템이 있는지 확인 (투척류 + 권총)
    firearm_items = ["molotov", "grenade", "flare", "smoke_grenade", "spider_mine"]
    has_firearm_item = False
    
    # 코만도 캐릭터 권총 확인
    global selected_character_type
    if selected_character_type == "soldier":
        has_firearm_item = True
    
    # 투척류 아이템 확인
    for item in active_item_slot:
        if item.get("name") in firearm_items or item.get("effect") in firearm_items:
            has_firearm_item = True
            break
    
    # 화기류 아이템이 없으면 표시하지 않음
    if not has_firearm_item:
        return
    
    # 남은 시간 계산 (0~1 사이의 비율)
    cooldown_ratio = min(time_since_round_start / 3000, 1.0)
    remaining_time = max(0, 3.0 - time_since_round_start / 1000)
    
    # 화면 중앙 상단에 표시
    center_x = SCREEN_WIDTH // 2
    center_y = 100
    
    # 원형 쿨타임 표시 (반지름 30)
    radius = 30
    
    # 배경 원 (어두운 회색)
    pygame.draw.circle(SCREEN, (40, 40, 40, 180), (center_x, center_y), radius)
    
    # 쿨타임 아크 그리기 (시계방향)
    if cooldown_ratio < 1.0:
        # 파이 조각 모양으로 쿨타임 표시
        angle_start = -90  # 12시 방향부터 시작
        angle_end = -90 + (360 * cooldown_ratio)
        
        # 쿨타임 오버레이 (반투명 검은색)
        overlay_surface = pygame.Surface((radius * 2 + 10, radius * 2 + 10), pygame.SRCALPHA)
        
        # 남은 쿨타임 부분을 어둡게 표시
        for angle in range(int(angle_end), 270):
            x = center_x + int(radius * 0.9 * math.cos(math.radians(angle)))
            y = center_y + int(radius * 0.9 * math.sin(math.radians(angle)))
            pygame.draw.line(SCREEN, (20, 20, 20, 200), (center_x, center_y), (x, y), 2)
    
    # 테두리 원
    pygame.draw.circle(SCREEN, (100, 100, 100), (center_x, center_y), radius, 2)
    
    # 화기류 금지 아이콘 (X 표시)
    if cooldown_ratio < 1.0:
        cross_size = 15
        pygame.draw.line(SCREEN, (255, 100, 100), 
                        (center_x - cross_size, center_y - cross_size),
                        (center_x + cross_size, center_y + cross_size), 3)
        pygame.draw.line(SCREEN, (255, 100, 100),
                        (center_x + cross_size, center_y - cross_size),
                        (center_x - cross_size, center_y + cross_size), 3)
    
    # 남은 시간 텍스트
    try:
        font = pygame.font.Font(resource_path("NeoDGM.ttf"), 20)
    except:
        font = pygame.font.Font(None, 20)
    
    if remaining_time > 0:
        time_text = font.render(f"{remaining_time:.1f}초", True, (255, 200, 100))
        text_rect = time_text.get_rect(center=(center_x, center_y + radius + 20))
        SCREEN.blit(time_text, text_rect)
        
        # 안내 텍스트
        info_text = font.render("투척 준비중", True, (200, 200, 200))
        info_rect = info_text.get_rect(center=(center_x, center_y - radius - 20))
        SCREEN.blit(info_text, info_rect)

def activate_molotov():
    """화염병 투척 함수 - 0.5초 투척 모션 후 발사"""
    global molotov_throwing, molotov_throw_timer, molotov_target_x, molotov_target_y
    import items
    
    # 목표 지점 미리 계산
    molotov_target_x = BOSS.centerx + random.uniform(-50, 50)  # 보스 중심 근처 랜덤
    molotov_target_y = BOSS.bottom - 50  # 보스 패들 뒤쪽
    
    # 투척 모션 시작
    molotov_throwing = True
    
    # 코만도암 효과 적용 체크 (디버그 로그 추가)
    print(f"[DEBUG] items.commando_arm_obtained : {items.commando_arm_obtained}")
    
    # 코만도암 효과 적용 (준비시간 단축)
    if items.commando_arm_obtained:
        print(f"   !   0.2")
        molotov_throw_timer = 12  # 0.2초 (60fps * 0.2)
        # 코만도암 착용시 짧은 준비 사운드 (maxtime 파라미터로 재생 시간 제한)
        SOUND_THROW_BEFORE.play(maxtime=200)  # 200ms만 재생
    else:
        # 일반 투척 시간
        molotov_throw_timer = 36  # 0.6초 (60fps * 0.6)
        print(f"    : {molotov_throw_timer/60:.1f}")
        # 일반 준비 사운드 전체 재생
        play_sound_with_volume(SOUND_THROW_BEFORE)
    # 효과음 재생 (투척 시작)
    play_active_item_sound()
    print(f"  ! {molotov_throw_timer/60:.1f}  .")
def throw_molotov():
    """실제 화염병 투척 (모션 후 실행)"""
    global molotovs, BOSS, PLAYER, molotov_target_x, molotov_target_y
    import items
    current_time = pygame.time.get_ticks()
    print(f"[DEBUG] throw_molotov  : {current_time}ms,  molotovs : {len(molotovs)}")
    # 투척 사운드는 타이머에서 이미 재생됨
    # 방향 벡터 계산
    dx = molotov_target_x - PLAYER.centerx
    dy = molotov_target_y - PLAYER.centery
    distance = math.sqrt(dx**2 + dy**2)
    # 속도 정규화 (일정한 속도로 날아가도록)
    base_speed = 14.4  # 화염병 기본 속도
    # 코만도암 효과 적용 (투척 속도 50% 증가)
    if items.commando_arm_obtained:
        speed = base_speed * 1.5  # 14.4 → 21.6
        print(f"  !  : {speed:.1f} (: {base_speed})")
    else:
        speed = base_speed
        print(f"   : {speed:.1f}")
    vel_x = (dx / distance) * speed if distance > 0 else 0
    vel_y = (dy / distance) * speed if distance > 0 else -speed
    molotov = {
        "x": PLAYER.centerx,
        "y": PLAYER.centery,
        "vel_x": vel_x,  # 목표를 향한 X 속도
        "vel_y": vel_y,  # 목표를 향한 Y 속도
        "gravity": 0,  # 중력 제거
        "target_y": molotov_target_y,  # 보스 패들 뒤쪽 목표 지점
        "exploded": False,
        "rotation": 0  # 회전 각도 추가
    }
    molotovs.append(molotov)
    print(f"[DEBUG]   !  : {len(molotovs)}, : {pygame.time.get_ticks()}ms")
    
    # 코만도암이 있으면 첫 프레임 이동을 즉시 실행
    if items.commando_arm_obtained:
        molotov["x"] += molotov["vel_x"]
        molotov["y"] += molotov["vel_y"]
        if molotov["gravity"] > 0:
            molotov["vel_y"] += molotov["gravity"]
        print(f"[DEBUG]  !")
    
    print(f" !  : X={molotov_target_x:.1f}, Y={molotov_target_y:.1f}")

def create_brick_destruction_effect(brick_rect):
    """벽돌 부서지는 파티클 이펙트 생성 - 폭발적인 파편 효과"""
    global brick_particles
    
    # 벽돌 부서지는 사운드 재생 - rock_break.wav 제거됨
    # 대신 stonebreak2.wav 사용
    try:
        SOUND_BRICK_DESTROY.play()
    except:
        pass
    
    # 폭발 중심점
    explosion_center_x = brick_rect.centerx
    explosion_center_y = brick_rect.centery
    
    # 더 많은 파티클 생성 (15-25개) - 더 폭발적인 느낌
    particle_count = random.randint(15, 25)
    
    for i in range(particle_count):
        # 파티클 시작 위치 (벽돌 중심에서 약간 퍼짐)
        start_x = explosion_center_x + random.randint(-5, 5)
        start_y = explosion_center_y + random.randint(-5, 5)
        
        # 폭발 방향 (360도 전방향으로)
        angle = random.uniform(0, 2 * math.pi)
        
        # 폭발 속도 (더 강력하고 다양한 속도)
        speed = random.uniform(8, 20)  # 더 빠른 속도
        vel_x = math.cos(angle) * speed
        vel_y = math.sin(angle) * speed - random.uniform(0, 5)  # 약간 위로 편향
        
        # 파티클 크기 (더 다양한 크기의 파편)
        size = random.choice([
            random.randint(2, 4),    # 작은 파편 (40%)
            random.randint(4, 7),    # 중간 파편 (40%)  
            random.randint(7, 12)    # 큰 파편 (20%)
        ])
        
        # 벽돌 색상 계열 (더 다양한 색상)
        color_base = random.choice([
            (139, 69, 19),   # 갈색 벽돌
            (160, 82, 45),   # 밝은 갈색  
            (105, 105, 105), # 모르타르 회색
            (184, 134, 11),  # 노란 갈색
            (120, 50, 10),   # 어두운 갈색
            (200, 150, 100)  # 밝은 벽돌색
        ])
        
        # 색상 약간 변화
        color = tuple(max(0, min(255, c + random.randint(-40, 40))) for c in color_base)
        
        # 파티클 생성
        particle = {
            "x": start_x,
            "y": start_y,
            "vel_x": vel_x,
            "vel_y": vel_y,
            "size": size,
            "color": color,
            "life": random.randint(45, 90),  # 0.75~1.5초 생존 (더 다양한 수명)
            "rotation": random.uniform(0, 360),  # 회전각
            "angular_vel": random.uniform(-20, 20),  # 더 빠른 회전속도
            "type": "brick"  # 파티클 타입 추가
        }
        
        brick_particles.append(particle)
    
    # 추가 효과: 먼지 파티클 (폭발 연기 효과)
    dust_count = random.randint(8, 12)
    for i in range(dust_count):
        angle = random.uniform(0, 2 * math.pi)
        speed = random.uniform(3, 8)
        
        particle = {
            "x": explosion_center_x + random.randint(-10, 10),
            "y": explosion_center_y + random.randint(-10, 10),
            "vel_x": math.cos(angle) * speed,
            "vel_y": math.sin(angle) * speed - 2,
            "size": random.randint(8, 15),
            "color": (150, 150, 150),  # 회색 먼지
            "life": random.randint(20, 40),  # 짧은 수명
            "rotation": 0,
            "angular_vel": 0,
            "type": "dust"  # 먼지 타입
        }
        
        brick_particles.append(particle)

def update_brick_particles():
    """벽돌 파티클 업데이트 - 더 역동적인 물리 효과"""
    global brick_particles
    
    for particle in brick_particles[:]:
        # 파티클 타입에 따른 다른 물리 효과
        if particle.get("type") == "dust":
            # 먼지는 천천히 퍼지면서 사라짐
            particle["x"] += particle["vel_x"]
            particle["y"] += particle["vel_y"]
            particle["vel_y"] += 0.1  # 약한 중력
            particle["vel_x"] *= 0.92  # 강한 공기 저항
            particle["size"] *= 1.05  # 크기 증가 (퍼짐 효과)
        else:
            # 벽돌 파편은 더 현실적인 물리
            particle["x"] += particle["vel_x"]
            particle["y"] += particle["vel_y"]
            particle["vel_y"] += 0.8  # 더 강한 중력
            particle["vel_x"] *= 0.96  # 공기 저항
            particle["rotation"] += particle["angular_vel"]
            
            # 회전 속도 감소
            particle["angular_vel"] *= 0.98
            
            # 바닥에 닿으면 튕기기
            if particle["y"] > HEIGHT - 50:
                particle["y"] = HEIGHT - 50
                
                # 크기에 따른 다른 탄성
                if particle["size"] > 7:  # 큰 파편
                    particle["vel_y"] *= -0.2  # 덜 튕김
                    particle["vel_x"] *= 0.5   # 더 많은 마찰
                else:  # 작은 파편
                    particle["vel_y"] *= -0.4  # 더 튕김
                    particle["vel_x"] *= 0.8   # 덜 마찰
                
                particle["angular_vel"] *= 0.5
                
                # 바닥에 충돌 시 파편이 더 작게 부서질 수 있음
                if particle["size"] > 5 and random.random() < 0.3:
                    particle["size"] -= 1
            
            # 벽에 충돌
            if particle["x"] < 0 or particle["x"] > WIDTH:
                particle["vel_x"] *= -0.7
                particle["angular_vel"] *= -0.8
        
        # 수명 감소
        particle["life"] -= 1
        
        # 수명 다한 파티클 제거
        if particle["life"] <= 0 or particle.get("size", 1) <= 0:
            brick_particles.remove(particle)

def draw_brick_particles(screen):
    """벽돌 파티클 그리기 - 먼지와 파편을 다르게 렌더링"""
    for particle in brick_particles:
        # 알파 값 계산 (수명에 따라 페이드아웃)
        max_life = 90 if particle.get("type") == "brick" else 40
        alpha_ratio = particle["life"] / max_life
        alpha = int(255 * alpha_ratio)
        
        if alpha <= 0:
            continue
        
        # 파티클 타입에 따른 다른 렌더링
        if particle.get("type") == "dust":
            # 먼지는 원형으로 그리고 더 투명하게
            dust_surface = pygame.Surface((int(particle["size"]*2), int(particle["size"]*2)), pygame.SRCALPHA)
            
            # 그라데이션 효과를 위한 여러 원 그리기
            for i in range(3):
                radius = int(particle["size"] * (1 - i*0.3))
                fade_alpha = int(alpha * (0.3 - i*0.1))
                if fade_alpha > 0 and radius > 0:
                    pygame.draw.circle(dust_surface, (*particle["color"], fade_alpha), 
                                     (int(particle["size"]), int(particle["size"])), radius)
            
            screen.blit(dust_surface, (int(particle["x"] - particle["size"]), 
                                      int(particle["y"] - particle["size"])))
        else:
            # 벽돌 파편은 각진 모양으로
            size = int(particle["size"])
            if size <= 0:
                continue
                
            particle_surface = pygame.Surface((size*2, size*2), pygame.SRCALPHA)
            
            # 파편 모양 그리기 (다각형)
            if particle["size"] > 7:  # 큰 파편
                # 불규칙한 육각형
                points = [
                    (size//3, 0),
                    (size*2//3, 0),
                    (size, size//3),
                    (size*2//3, size),
                    (size//3, size),
                    (0, size*2//3)
                ]
            else:  # 작은 파편
                # 불규칙한 사각형
                points = [
                    (0, size//4),
                    (size*3//4, 0),
                    (size, size*3//4),
                    (size//4, size)
                ]
            
            # 파편 그리기
            pygame.draw.polygon(particle_surface, (*particle["color"], alpha), points)
            
            # 테두리 추가 (더 선명하게)
            if alpha > 100:
                edge_color = tuple(max(0, c - 50) for c in particle["color"])
                pygame.draw.polygon(particle_surface, (*edge_color, alpha//2), points, 1)
            
            # 회전 적용
            rotated_surface = pygame.transform.rotate(particle_surface, particle["rotation"])
            
            # 화면에 그리기
            rotated_rect = rotated_surface.get_rect()
            rotated_rect.center = (int(particle["x"]), int(particle["y"]))
            screen.blit(rotated_surface, rotated_rect)

def activate_wall():
    """벽돌 설치 함수"""
    global walls, pending_wall, wall_installing, wall_install_timer, wall_install_gauge_visible, master_obtained
    if not wall_installing:
        wall_installing = True
        #  엑티브 아이템 사용 효과음 재생
        play_active_item_sound()
        # 장인 아이템이 있으면 벽돌 길이만 증가 (설치 시간은 동일하게 유지)
        if master_obtained:
            wall_install_timer = HALF_SECOND_FRAMES  # 0.5초 (30프레임)
            wall_width = int(80 * 1.3)  # 1.3배 길이 (30% 증가)
            print(f"  !   1.3,  0.5 ( {len(walls)})")
