def handle_new_boss_skills_timer():
    """새로운 보스들의 스킬 타이머 처리"""
    global lightning_strike_active, lightning_strike_timer
    global ice_barrier_active, ice_barrier_timer
    global fire_charge_active, fire_charge_timer
    global wind_burst_active, wind_burst_timer
    global ball_vel
    if not new_boss_mode_active:
        return
    # 라이트닝 마스터 스킬 타이머 - 번개 충격 활성화 시 공 속도 증가
    if lightning_strike_active and lightning_strike_timer > 0:
        lightning_strike_timer -= 1
        # 번개 충격 효과: 공 속도 증가
        if ball_vel[1] < 0:  # 공이 위로 향할 때만 (하단에서 상단으로)
            ball_vel[0] *= 1.02  # X축 속도 증가
            ball_vel[1] *= 1.02  # Y축 속도 증가
            # 번개 효과로 공에 약간의 랜덤성 추가
            if lightning_strike_timer % 15 == 0:  # 15프레임마다
                thunder_force_x = random.uniform(-0.5, 0.5)
                thunder_force_y = random.uniform(-0.3, 0.3)
                ball_vel[0] += thunder_force_x
                ball_vel[1] += thunder_force_y
            # 속도 안전성 검사
            check_ball_speed_safety()
        if lightning_strike_timer <= 0:
            lightning_strike_active = False
            print("!")
    # 아이스 퀸 스킬 타이머 - 얼음 방벽 활성화 시 공 속도 50% 감소
    if ice_barrier_active and ice_barrier_timer > 0:
        ice_barrier_timer -= 1
        # 얼음 방벽 효과: 공 속도 감소
        if ball_vel[1] < 0:  # 공이 위로 향할 때만 (상단 보스에게 향할 때)
            ball_vel[0] *= 0.98  # X축 속도 감소
            ball_vel[1] *= 0.98  # Y축 속도 감소
        if ice_barrier_timer <= 0:
            ice_barrier_active = False
            print("!")
    # 파이어 나이트 스킬 타이머
    if fire_charge_active and fire_charge_timer > 0:
        fire_charge_timer -= 1
        if fire_charge_timer <= 0:
            fire_charge_active = False
            print("!")
    # 윈드 스피릿 스킬 타이머 - 바람 폭발 시 공을 랜덤하게 튕겨냄
    if wind_burst_active and wind_burst_timer > 0:
        wind_burst_timer -= 1
        # 바람 폭발 효과: 공에 랜덤한 힘 적용
        if wind_burst_timer == wind_burst_duration - 1:  # 스킬 발동 직후 한 번만
            wind_force_x = random.uniform(-3, 3)
            wind_force_y = random.uniform(-2, 2)
            ball_vel[0] += wind_force_x
            ball_vel[1] += wind_force_y
            print(f"  !    : ({wind_force_x:.1f}, {wind_force_y:.1f})")
        if wind_burst_timer <= 0:
            wind_burst_active = False
            print("!")

def fire_soldier_bullet():
    """코만도 캐릭터가 총알을 발사하는 함수"""
    global soldier_bullets, soldier_gun_cooldown, soldier_control_lock_timer, soldier_gun_drawn
    global soldier_gun_animation_active, soldier_gun_animation_frame, soldier_gun_animation_timer
    global soldier_gun_target_x, soldier_gun_target_y
    global soldier_ammo_count, soldier_reloading, soldier_reload_timer, special_gauge
    global round_start_time
    
    # 라운드 시작 3초 제한 체크
    current_time = pygame.time.get_ticks()
    # round_start_time이 0이거나 비정상적인 값일 경우 제한하지 않음
    if round_start_time > 0 and current_time - round_start_time < 3000:  # 3초 미만
        remaining_time = (3000 - (current_time - round_start_time)) / 1000
        print(f"🔫 화기류 사용 제한 중 (남은 시간: {remaining_time:.1f}초)")
        return False
    
    if soldier_gun_cooldown > 0:
        return  # 쿨타임 중이면 발사 불가
    
    # 재장전 중이면 발사 불가
    if soldier_reloading:
        return
    
    # 탄약이 없으면 재장전 시도 (단, UP 키가 눌려있지 않을 때만)
    if soldier_ammo_count <= 0:
        # UP 키가 눌려있으면 물자보급 시도 중이므로 재장전하지 않음
        keys = pygame.key.get_pressed()
        if not keys[pygame.K_UP]:
            start_soldier_reload()
        return
    
    # 탄약 소모
    soldier_ammo_count -= 1
    
    # 총 발사 애니메이션 시작
    soldier_gun_animation_active = True
    soldier_gun_animation_frame = 0
    soldier_gun_animation_timer = 0
    
    # 조준 대상 설정 (보스 위치)
    soldier_gun_target_x = BOSS.centerx
    soldier_gun_target_y = BOSS.centery
    
    # 총을 꺼내고 통제불능 시작
    soldier_gun_drawn = True
    soldier_control_lock_timer = SOLDIER_CONTROL_LOCK_TIME
    soldier_gun_cooldown = SOLDIER_GUN_COOLDOWN
    
    # 총 장전 사운드 재생 (버튼을 누르자마자)
    try:
        gunroad_sound = pygame.mixer.Sound(resource_path("sounds/gunroad.wav"))
        gunroad_sound.set_volume(0.7)
        gunroad_sound.play()
    except:
        pass

def start_soldier_reload():
    """코만도 탄약 재장전 시작"""
    global soldier_reloading, soldier_reload_timer, special_gauge, soldier_last_reload_bullets
    
    # 이미 재장전 중이면 무시
    if soldier_reloading:
        return
    
    # UP 키가 눌려있으면 물자보급 발동 시도 중이므로 재장전 불가
    keys = pygame.key.get_pressed()
    if keys[pygame.K_UP]:
        return
    
    # 게이지가 부족하면 재장전 불가
    if special_gauge < SOLDIER_RELOAD_GAUGE_COST:
        return
    
    # 게이지 소모
    special_gauge -= SOLDIER_RELOAD_GAUGE_COST
    
    # 재장전 시작
    soldier_reloading = True
    soldier_reload_timer = SOLDIER_RELOAD_TIME
    soldier_last_reload_bullets = 0  # 재장전 시작시 초기화
    
    # 재장전 시작 사운드 재생
    try:
        SOUND_PISTOL_RELOAD_START.play()
    except:
        pass  # 사운드 재생 실패시 무시

def update_soldier_reload():
    """코만도 재장전 업데이트"""
    global soldier_reloading, soldier_reload_timer, soldier_ammo_count, soldier_last_reload_bullets
    
    if not soldier_reloading:
        return
    
    # 재장전 타이머 감소
    soldier_reload_timer -= 1
    
    # 재장전 진행도에 따라 표시할 총알 수 계산
    progress_ratio = 1.0 - (soldier_reload_timer / SOLDIER_RELOAD_TIME)
    bullets_to_show = int(progress_ratio * soldier_max_ammo)
    
    # 새로운 총알이 추가되었을 때 사운드 재생
    if bullets_to_show > soldier_last_reload_bullets:
        try:
            reload_sound = pygame.mixer.Sound(resource_path(os.path.join("sounds", "pistolreload.wav")))
            reload_sound.set_volume(0.3)  # 볼륨을 30%로 설정
            reload_sound.play()
        except:
            pass  # 사운드 파일이 없거나 재생 실패시 무시
        soldier_last_reload_bullets = bullets_to_show
    
    # 재장전 완료
    if soldier_reload_timer <= 0:
        soldier_reloading = False
        soldier_reload_timer = 0
        soldier_ammo_count = soldier_max_ammo  # 탄약 모두 충전
        soldier_last_reload_bullets = 0  # 다음 재장전을 위해 초기화

def draw_soldier_weapon_ui(screen):
    """코만도 화기류 UI 그리기 - 현재 장착된 무기 표시"""
    import math
    import pygame
    global soldier_ammo_count, soldier_max_ammo, soldier_reloading, soldier_reload_timer
    global soldier_emergency_supply_toast_timer

    def render_weapon_label(text, color, size):
        surface = None

        if hasattr(ui_manager, 'korean_font') and ui_manager.korean_font:
            try:
                surface = ui_manager.korean_font.render(text, True, color)
            except Exception:
                surface = None

        if surface is None:
            try:
                import pygame.freetype

                font_paths = [
                    resource_path(os.path.join("fonts", "pixel", "NeoDunggeunmoPro.ttf")),
                    resource_path(os.path.join("fonts", "pixel", "네오둥근모.ttf")),
                    resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "alternative", "Pretendard-Regular.ttf")),
                    resource_path(os.path.join("fonts", "프리텐다드", "public", "static", "Pretendard-Regular.otf")),
                    resource_path(os.path.join("fonts", "NanumSquareB.ttf"))
                ]

                for font_path in font_paths:
                    if os.path.exists(font_path):
                        try:
                            korean_font = pygame.freetype.Font(font_path, size)
                            surface, _ = korean_font.render(text, color)
                            if surface:
                                break
                        except Exception:
                            continue
            except Exception:
                surface = None

        if surface is None:
            try:
                system_fonts = [
                    "AppleSDGothicNeo.ttc",
                    "Arial Unicode MS",
                    "Malgun Gothic",
                    "NanumGothic"
                ]

                for system_font in system_fonts:
                    try:
                        font = pygame.font.SysFont(system_font, size)
                        if font:
                            rendered = font.render(text, True, color)
                            if rendered:
                                surface = rendered
                                break
                    except Exception:
                        continue
            except Exception:
                surface = None

        if surface is None:
            font = pygame.font.Font(None, size)
            surface = font.render(text, True, color)

        return surface

    # 액티브 아이템 슬롯 크기 및 위치 계산
    slot_size = 60
    slot_margin = 10
    bottom_margin = 80  # 화면 하단에서 여백
    
    # 권총 아이콘 위치 (액티브 슬롯 위) - 크기를 더 줄이고 위치 조정
    weapon_size = int(slot_size * 0.8)  # 0.8배 크기로 축소
    weapon_x = slot_margin
    weapon_y = HEIGHT - bottom_margin - slot_size - weapon_size + 15  # 위치를 더 아래로 조정
    
    # 권총 아이콘 배경 (사각형)
    weapon_rect = pygame.Rect(weapon_x, weapon_y, weapon_size, weapon_size)
    
    # 강조 효과 처리
    highlight_active = soldier_controller.ui_highlight_timer > 0
    if highlight_active:
        # 강조 효과 - 반짝거리는 테두리
        pulse = int(128 + 127 * math.sin(soldier_controller.ui_highlight_timer * 0.3))  # 반짝거림
        glow_color = (255, pulse, 0)  # 황금색 반짝임
        
        # 외부 글로우 효과
        for i in range(3, 0, -1):
            glow_rect = weapon_rect.inflate(i * 4, i * 4)
            alpha = 80 - i * 20
            glow_surface = pygame.Surface((glow_rect.width, glow_rect.height), pygame.SRCALPHA)
            pygame.draw.rect(glow_surface, (*glow_color, alpha), glow_surface.get_rect(), 2)
            screen.blit(glow_surface, glow_rect.topleft)
        
        # 강조된 배경
        pygame.draw.rect(screen, (60, 60, 40), weapon_rect)
        pygame.draw.rect(screen, glow_color, weapon_rect, 4)
        
        # 타이머 감소
        soldier_controller.ui_highlight_timer -= 1
    else:
        # 일반 배경 사각형
        pygame.draw.rect(screen, (40, 40, 40), weapon_rect)
        pygame.draw.rect(screen, (100, 100, 100), weapon_rect, 3)

    if soldier_emergency_supply_toast_timer > 0:
        toast_ratio = soldier_emergency_supply_toast_timer / 90
        toast_alpha = max(0, min(255, int(255 * toast_ratio)))
        bounce_offset = int(4 * math.sin(pygame.time.get_ticks() * 0.03))
        text_x = weapon_rect.right + 16
        text_y = weapon_rect.centery + bounce_offset
        glow_surface = render_weapon_label("비상보급!", (255, 195, 90), 26)
        if glow_surface:
            glow_surface = glow_surface.copy()
            glow_surface.set_alpha(int(toast_alpha * 0.4))
            glow_rect = glow_surface.get_rect(midleft=(text_x, text_y))
            screen.blit(glow_surface, glow_rect)
        text_surface = render_weapon_label("비상보급!", (255, 255, 210), 26)
        if text_surface:
            text_surface = text_surface.copy()
            text_surface.set_alpha(toast_alpha)
            text_rect = text_surface.get_rect(midleft=(text_x, text_y))
            screen.blit(text_surface, text_rect)

    # 현재 장착된 무기 확인
    current_weapon = soldier_controller.weapons[soldier_controller.current_index] if soldier_controller.weapons else "pistol"
    
    # 바주카포가 장착된 경우 바주카포 정보 표시
    from item_effects.bazooka import get_bazooka_instance
    bazooka = get_bazooka_instance()
    
    if current_weapon == "bazooka" and bazooka.equipped:
        # 바주카포 무기 정보 표시 (슬롯 내부에 맞춘 간결한 디자인)
        base_x, base_y = weapon_rect.x, weapon_rect.y
        w, h = weapon_rect.width, weapon_rect.height

        bazooka_active = bazooka.ammo_count > 0

        tube_fill = (92, 96, 64) if bazooka_active else (88, 88, 88)
        tube_outline = (52, 56, 34) if bazooka_active else (120, 120, 120)
        muzzle_outer = (38, 38, 38) if bazooka_active else (85, 85, 85)
        muzzle_inner = (18, 18, 18) if bazooka_active else (120, 120, 120)
        rear_outer = (30, 30, 30) if bazooka_active else (90, 90, 90)
        rear_inner = (18, 18, 18) if bazooka_active else (130, 130, 130)
        scope_frame = (30, 30, 30) if bazooka_active else (100, 100, 100)
        scope_body_color = (45, 45, 45) if bazooka_active else (120, 120, 120)
        scope_glass = (90, 90, 90) if bazooka_active else (150, 150, 150)
        grip_fill = (48, 48, 48) if bazooka_active else (110, 110, 110)
        grip_outline = (24, 24, 24) if bazooka_active else (150, 150, 150)
        accent_fill = (55, 55, 55) if bazooka_active else (120, 120, 120)
        accent_outline = (28, 28, 28) if bazooka_active else (150, 150, 150)

        tube_rect = pygame.Rect(
            base_x + int(w * 0.12),
            base_y + int(h * 0.45),
            int(w * 0.76),
            max(6, int(h * 0.28))
        )
        pygame.draw.rect(screen, tube_fill, tube_rect)
        pygame.draw.rect(screen, tube_outline, tube_rect, 2)

        muzzle_radius = max(5, int(min(w, h) * 0.18))
        muzzle_center = (tube_rect.right, tube_rect.centery)
        pygame.draw.circle(screen, muzzle_outer, muzzle_center, muzzle_radius)
        pygame.draw.circle(screen, muzzle_inner, muzzle_center, muzzle_radius - 3)

        rear_radius = max(6, int(min(w, h) * 0.2))
