def create_soldier_bullet():
    """실제 총알을 생성하는 함수 (애니메이션 완료 후 호출)"""
    global soldier_bullets, soldier_gun_muzzle_x, soldier_gun_muzzle_y
    
    # 플레이어 위치에서 보스 방향으로 총알 발사
    player_center_x = PLAYER.centerx
    player_center_y = PLAYER.centery
    boss_center_x = BOSS.centerx
    boss_center_y = BOSS.centery
    
    # 방향 벡터 계산
    dx = boss_center_x - player_center_x
    dy = boss_center_y - player_center_y
    distance = math.sqrt(dx**2 + dy**2)
    
    if distance > 0:
        # 정규화된 방향 벡터
        dx_norm = dx / distance
        dy_norm = dy / distance
        
        # 총알 생성
        if soldier_gun_muzzle_x == 0 and soldier_gun_muzzle_y == 0:
            bullet_start_x = player_center_x
            bullet_start_y = player_center_y - 20
        else:
            bullet_start_x = soldier_gun_muzzle_x
            bullet_start_y = soldier_gun_muzzle_y
        bullet = {
            "x": bullet_start_x,
            "y": bullet_start_y,
            "vel_x": dx_norm * SOLDIER_BULLET_SPEED,
            "vel_y": dy_norm * SOLDIER_BULLET_SPEED,
            "active": True
        }
        soldier_bullets.append(bullet)
        
        # 총 발사 효과음 재생
        try:
            gun_sound = pygame.mixer.Sound(resource_path("sounds/gunshot.wav"))
            gun_sound.set_volume(0.5)
            gun_sound.play()
        except:
            pass
        
        print(f"🔫 총알 발사! 방향: ({dx_norm:.2f}, {dy_norm:.2f})")

def update_soldier_gun_animation():
    """코만도 총 발사 애니메이션 업데이트"""
    global soldier_gun_animation_active, soldier_gun_animation_frame, soldier_gun_animation_timer
    
    if not soldier_gun_animation_active:
        return
    
    soldier_gun_animation_timer += 1
    
    # 애니메이션 프레임 진행
    if soldier_gun_animation_timer >= 2:  # 2프레임마다 진행 (30fps 애니메이션)
        soldier_gun_animation_timer = 0
        soldier_gun_animation_frame += 1
        
        # 발사 단계에서 총알 생성
        if soldier_gun_animation_frame == SOLDIER_GUN_DRAW_FRAMES + SOLDIER_GUN_AIM_FRAMES:
            create_soldier_bullet()  # 조준 완료 후 총알 발사
        
        # 애니메이션 완료
        if soldier_gun_animation_frame >= SOLDIER_GUN_TOTAL_FRAMES:
            soldier_gun_animation_active = False
            soldier_gun_animation_frame = 0

def trigger_boss_knockback(bullet_x, bullet_y):
    """보스 패들 넉백 효과 트리거"""
    global boss_knockback_active, boss_knockback_offset_x, boss_knockback_offset_y, boss_knockback_timer
    
    # 넉백 효과 활성화
    boss_knockback_active = True
    boss_knockback_timer = BOSS_KNOCKBACK_DURATION
    
    # X축(가로)으로만 넉백 방향 계산
    boss_center_x = BOSS.centerx
    
    # 총알이 보스의 어느 쪽을 맞췄는지 계산
    bullet_relative_to_boss = bullet_x - boss_center_x
    
    # 맞은 부위의 반대 방향으로 넉백
    if bullet_relative_to_boss > 5:  # 총알이 보스 오른쪽을 맞췄음
        # 보스 오른쪽에 맞았으므로 왼쪽으로 튕겨나감
        knockback_direction_x = -1
    elif bullet_relative_to_boss < -5:  # 총알이 보스 왼쪽을 맞췄음
        # 보스 왼쪽에 맞았으므로 오른쪽으로 튕겨나감
        knockback_direction_x = 1
    else:
        # 중앙에 가까울 때는 랜덤하게 좌우로 넉백
        import random
        knockback_direction_x = random.choice([-1, 1])
    
    # X축으로만 넉백 오프셋 설정, Y축은 0
    boss_knockback_offset_x = knockback_direction_x * BOSS_KNOCKBACK_STRENGTH
    boss_knockback_offset_y = 0  # Y축 넉백 없음
    
    # 디버그 정보 출력
    print(f"🔫 코만도 총알 넉백 발동!")
    print(f"   총알 위치: X={bullet_x}, Y={bullet_y}")
    print(f"   보스 중심: X={boss_center_x}")
    print(f"   상대 위치: {bullet_relative_to_boss}")
    print(f"   넉백 방향: {knockback_direction_x} ({'왼쪽' if knockback_direction_x < 0 else '오른쪽'})")
    print(f"   넉백 강도: {BOSS_KNOCKBACK_STRENGTH}픽셀")
    print(f"   지속 시간: {BOSS_KNOCKBACK_DURATION}프레임 ({BOSS_KNOCKBACK_DURATION/60:.2f}초)")
    print(f"   최종 오프셋: X={boss_knockback_offset_x}, Y={boss_knockback_offset_y}")

def update_boss_knockback():
    """보스 패들 넉백 효과 업데이트"""
    global boss_knockback_active, boss_knockback_offset_x, boss_knockback_offset_y, boss_knockback_timer
    
    if boss_knockback_active:
        print(f"[DEBUG 넉백] 프레임 {BOSS_KNOCKBACK_DURATION - boss_knockback_timer + 1}/{BOSS_KNOCKBACK_DURATION}")
        print(f"            오프셋: X={boss_knockback_offset_x}, Y={boss_knockback_offset_y}")
        
        # 타이머 감소
        boss_knockback_timer -= 1
        
        # X축 넉백은 감쇠 없이 일정하게 유지 (Y축은 항상 0)
        # boss_knockback_offset_x는 초기값 그대로 유지
        boss_knockback_offset_y = 0  # Y축은 항상 0 유지
        
        # 넉백 종료 조건 (타이머만 체크)
        if boss_knockback_timer <= 0:
            boss_knockback_active = False
            boss_knockback_offset_x = 0
            boss_knockback_offset_y = 0
            boss_knockback_timer = 0

def create_blood_particles(x, y, bullet_vx, bullet_vy):
    """피 튀기는 파티클 생성 함수"""
    global blood_particles
    
    # 피 파티클 개수 (8~12개)
    particle_count = random.randint(8, 12)
    
    # 총알 방향의 반대 방향으로 주로 튀도록 설정
    bullet_angle = math.atan2(bullet_vy, bullet_vx)
    
    for _ in range(particle_count):
        # 기본적으로 총알이 날아온 반대 방향으로 튀지만 약간의 랜덤성 추가
        spread_angle = bullet_angle + math.pi + random.uniform(-math.pi/3, math.pi/3)
        speed = random.uniform(3, 12)
        
        # 중력의 영향을 받을 파티클 속도
        vx = math.cos(spread_angle) * speed
        vy = math.sin(spread_angle) * speed - random.uniform(2, 5)  # 위로 살짝 튀는 효과
        
        # 파티클 크기 (작은 것부터 큰 것까지)
        size = random.uniform(2, 5)
        
        # 파티클 수명 (20~40 프레임)
        life = random.randint(20, 40)
        
        blood_particles.append({
            "x": x + random.uniform(-5, 5),
            "y": y + random.uniform(-5, 5),
            "vx": vx,
            "vy": vy,
            "size": size,
            "alpha": 255,
            "life": life,
            "gravity": random.uniform(0.3, 0.6)  # 중력 효과
        })

def trigger_soldier_bullet_knockback(bullet_x, bullet_y):
    """코만도 총알의 보스 패들 넉백 효과 트리거 (라그나로크 해머 방식 참조)"""
    global boss_knockback_timer, boss_knockback_vel
    
    # 라그나로크 해머 방식의 넉백 곈4산 (홍련 화염탄 수준)
    base_power = 14  # 기본 넉백 파워 (홍련 화염탄 수준으로 조정)
    
    # 보스 위치에 따라 방향 결정 (라그나로크 해머와 동일한 로직)
    center_x = 300  # 화면 중앙
    boss_x = BOSS.x
    
    if boss_x + 50 < center_x:  # 보스가 왼쪽에 있으면
        horizontal_velocity = base_power  # 오른쪽으로 넉백
    else:  # 보스가 오른쪽에 있으면
        horizontal_velocity = -base_power  # 왼쪽으로 넉백
    
    # 랜덤 추가 넉백 (10-20%)
    import random
    random_factor = 1.0 + random.uniform(0.1, 0.2)
    horizontal_velocity *= random_factor
    
    # 라그나로크 해머 넉백 시스템 활용
    boss_knockback_timer = 18  # 0.3초간 넉백 효과 지속 (화염탄과 동일한 거리)
    boss_knockback_vel = horizontal_velocity
    
    print(f"[DEBUG] 코만도 총알 넉백 - timer: {boss_knockback_timer}, vel: {boss_knockback_vel:.2f}")

def update_soldier_bullets():
    """코만도 총알 업데이트"""
    global soldier_bullets
    
    # 비활성 총알 제거
    soldier_bullets = [b for b in soldier_bullets if b["active"]]
    
    # 각 총알 업데이트
    for bullet in soldier_bullets:
        if bullet["active"]:
            # 위치 업데이트
            bullet["x"] += bullet["vel_x"]
            bullet["y"] += bullet["vel_y"]
            
            # 화면 밖으로 나가면 비활성화
            if (bullet["x"] < -50 or bullet["x"] > WIDTH + 50 or 
                bullet["y"] < -50 or bullet["y"] > HEIGHT + 50):
                bullet["active"] = False
            
            # 보스와의 충돌 검사
            bullet_rect = pygame.Rect(bullet["x"] - SOLDIER_BULLET_SIZE, 
                                     bullet["y"] - SOLDIER_BULLET_SIZE,
                                     SOLDIER_BULLET_SIZE * 2, 
                                     SOLDIER_BULLET_SIZE * 2)
            
            if bullet_rect.colliderect(BOSS):
                bullet["active"] = False
                global boss_stunned_timer, leg_shot_active, leg_shot_timer, leg_shot_text_timer
                global head_shot_active, head_shot_timer, head_shot_text_timer
                
                # 헤드샷과 레그샷 중 하나만 발동 (도핑 효과 반영)
                shot_roll = random.random()
                head_chance, leg_chance = get_soldier_shot_probabilities()
                if shot_roll < head_chance:
                    # 헤드샷 발동 (1.5초 스턴)
                    head_shot_active = True
                    head_shot_timer = HEAD_SHOT_DURATION  # 1.5초간 스턴
                    head_shot_text_timer = HEAD_SHOT_TEXT_DURATION  # 1초간 텍스트 표시
                    boss_stunned_timer = HEAD_SHOT_DURATION  # 별 효과를 위한 타이머 (1.5초)
                    print("💥 헤드샷! 보스 1.5초간 스턴!")
                elif shot_roll < head_chance + leg_chance:
                    # 레그샷 발동 (헤드샷이 발동하지 않은 경우에만)
                    leg_shot_active = True
                    leg_shot_timer = LEG_SHOT_DURATION  # 3초간 지속
                    leg_shot_text_timer = LEG_SHOT_TEXT_DURATION  # 1초간 텍스트 표시
                    print("🎯 레그샷! 보스 이동속도 30% 감소!")
                else:
                    # 일반 명중 (0.5초 스턴)
                    boss_stunned_timer = 30  # 0.5초 스턴 (수류탄과 동일한 시각 효과)
                
                # 라그나로크 해머 방식의 넉백 효과 적용
                trigger_soldier_bullet_knockback(bullet["x"], bullet["y"])
                
                # 피 튀기는 파티클 효과 추가
                create_blood_particles(bullet["x"], bullet["y"], bullet["vel_x"], bullet["vel_y"])
                
                # 타격 효과음
                try:
                    hit_sound = pygame.mixer.Sound(resource_path("sounds/bullet_hit.wav"))
                    hit_sound.set_volume(0.6)
                    hit_sound.play()
                except:
                    pass
                
                # 타격 이펙트 생성
                for _ in range(10):
                    impact_particles.append({
                        "x": bullet["x"],
                        "y": bullet["y"],
                        "vx": random.uniform(-5, 5),
                        "vy": random.uniform(-5, 5),
                        "size": random.uniform(3, 6),
                        "alpha": 255,
                        "color": SOLDIER_BULLET_COLOR,
                        "life": 30
                    })
                
                print("💥 총알이 보스에게 명중! 보스 스턴!")
                
                # 코만도 권총으로 보스 명중 시 게이지 25+ 증가
                global special_gauge, special_ready
                gauge_increase = 30  # 기본 30 증가
                
                # 헤드샷/레그샷 시 추가 보너스
                if shot_roll < head_chance:
                    gauge_increase = 50  # 헤드샷 시 50 증가
                    print("🎯 헤드샷 보너스! 게이지 50 증가!")
                elif shot_roll < head_chance + leg_chance:
                    gauge_increase = 40  # 레그샷 시 40 증가  
                    print("🎯 레그샷 보너스! 게이지 40 증가!")
                else:
                    print("🎯 코만도 권총 명중! 게이지 30 증가!")
                
                # 게이지 증가 적용
                old_gauge = special_gauge
                special_gauge += gauge_increase
                current_max = get_max_gauge()
                if special_gauge > current_max:
                    special_gauge = current_max
                
                # 필살기 준비 상태 업데이트
                if special_gauge >= 350:
                    special_ready = True
                
                print(f"코만도 권총 게이지 충전: {old_gauge} → {special_gauge} (+{gauge_increase})")
                
                # 넉백 효과 트리거 - 기존 시스템 사용 (boss_knockback_vel을 설정하는 함수)
                trigger_soldier_bullet_knockback(bullet["x"], bullet["y"])


def apply_ak47_boss_hit_effect(hit_event):
    """AK-47 탄환이 보스를 적중했을 때의 후속 효과 적용"""
    global boss_stunned_timer, boss_knockback_timer, boss_knockback_vel, BOSS

    vel_x = hit_event.get("vel_x", 0.0)
    bullet_x = hit_event.get("bullet_x")

    # 보스에게 짧은 스턴과 좌우 넉백 부여
    boss_stunned_timer = max(boss_stunned_timer, AK47_STUN_FRAMES)
    boss_knockback_timer = max(boss_knockback_timer, AK47_KNOCKBACK_FRAMES)

    # 방향 결정: 탄환이 보스의 어느 쪽에서 충돌했는지 기준
    direction = 1
    try:
        boss_center = BOSS.centerx
        if bullet_x is not None:
            direction = 1 if bullet_x <= boss_center else -1
        elif vel_x != 0:
            direction = 1 if vel_x > 0 else -1
    except Exception:
        # BOSS 참조가 불가하면 속도 부호로만 결정
        direction = 1 if vel_x >= 0 else -1

    knockback_strength = AK47_KNOCKBACK_BASE + abs(vel_x) * AK47_KNOCKBACK_SCALE
    boss_knockback_vel = knockback_strength * direction


def update_blood_particles():
    """피 파티클 업데이트"""
    global blood_particles
    
    particles_to_remove = []
    
    for particle in blood_particles:
        # 중력 적용
        particle["vy"] += particle["gravity"]
        
        # 위치 업데이트
        particle["x"] += particle["vx"]
        particle["y"] += particle["vy"]
        
        # 수명 감소
        particle["life"] -= 1
        
        # 알파값 감소 (서서히 사라지는 효과)
        particle["alpha"] = int(255 * (particle["life"] / 40))
        
        # 크기도 조금씩 작아지게
        if particle["life"] < 10:
            particle["size"] *= 0.95
        
        # 수명이 다했거나 화면 밖으로 나가면 제거
        if particle["life"] <= 0 or particle["y"] > HEIGHT + 50:
            particles_to_remove.append(particle)
    
    # 제거할 파티클들 삭제
    for particle in particles_to_remove:
        blood_particles.remove(particle)

def draw_blood_particles(screen):
    """피 파티클 그리기"""
    for particle in blood_particles:
        if particle["alpha"] > 0 and particle["size"] > 0.5:
            # 피의 색상 (진한 빨간색에서 어두운 빨간색으로 변화)
            life_ratio = particle["life"] / 40
            red = int(200 + 55 * life_ratio)  # 200-255
            green = int(20 * life_ratio)       # 0-20
            blue = int(20 * life_ratio)        # 0-20
            
            # 반투명 효과를 위해 Surface 생성
            particle_surface = pygame.Surface((int(particle["size"] * 2), int(particle["size"] * 2)), pygame.SRCALPHA)
            pygame.draw.circle(particle_surface, (red, green, blue, particle["alpha"]), 
                             (int(particle["size"]), int(particle["size"])), 
                             int(particle["size"]))
            
            # 화면에 그리기
            screen.blit(particle_surface, 
                       (int(particle["x"] - particle["size"]), 
                        int(particle["y"] - particle["size"])))

def draw_soldier_bullets(screen):
    """코만도 총알 그리기"""
    for bullet in soldier_bullets:
        if bullet["active"]:
            # 총알 본체
            pygame.draw.circle(screen, SOLDIER_BULLET_COLOR, 
                             (int(bullet["x"]), int(bullet["y"])), 
                             SOLDIER_BULLET_SIZE)
            
            # 총알 광택 효과
            pygame.draw.circle(screen, (255, 255, 200), 
                             (int(bullet["x"] - 2), int(bullet["y"] - 2)), 
                             SOLDIER_BULLET_SIZE // 2)


def create_slow_wave_surface(width, height, base_color=(170, 120, 255), intensity=1.0, wave_count=3):
    """보라색 물결형 이동 저하 이펙트 서피스 생성"""
    surface = pygame.Surface((width, height), pygame.SRCALPHA)
    if intensity <= 0:
        return surface

    # 파형은 최대 3개까지만 사용해 단순한 레이어 유지
    effective_waves = max(1, min(3, wave_count))
    time_value = pygame.time.get_ticks() * 0.006
    base_y = height * 0.82

    for wave_index in range(effective_waves):
        layer_strength = intensity * (1.0 - wave_index * 0.35)
        if layer_strength <= 0:
            continue

        alpha = max(0, min(255, int(120 * layer_strength)))
        color = (
            min(255, int(base_color[0] + wave_index * 8)),
            max(0, int(base_color[1] - wave_index * 6)),
            min(255, int(base_color[2] + wave_index * 6)),
            alpha,
        )
        amplitude = 2.4 * layer_strength
        frequency = 1.4 + wave_index * 0.3
        phase_offset = wave_index * 0.9
        y_offset = base_y - wave_index * 5

        points = []
        for x in range(0, width + 1, 3):
            progress = x / max(1, width)
            angle = time_value + phase_offset + progress * math.tau * frequency
            wave_offset = abs(math.sin(angle)) * amplitude
            y = min(height - 2, y_offset + wave_offset)
            points.append((x, y))

        if len(points) > 1:
            pygame.draw.lines(surface, color, False, points, 2)

    # 간단한 하이라이트 타원으로 중심 강조
    glow_alpha = int(50 * intensity)
    if glow_alpha > 0:
        glow_rect = pygame.Rect(0, 0, width, int(height * 0.45))
        glow_rect.center = (width // 2, int(height * 0.45))
        pygame.draw.ellipse(surface, (base_color[0], base_color[1], base_color[2], glow_alpha), glow_rect, 1)

    return surface


def draw_leg_shot_effect(screen):
    """레그샷 텍스트 효과 그리기 - 작고 임팩트 있는 애니메이션"""
    global leg_shot_text_timer, leg_shot_active, leg_shot_timer

    if leg_shot_active or leg_shot_timer > 0:
        remaining_ratio = leg_shot_timer / LEG_SHOT_DURATION if LEG_SHOT_DURATION else 1.0
        wave_intensity = 0.5 + 0.5 * max(0.0, min(1.0, remaining_ratio))
        wave_surface = create_slow_wave_surface(120, 56, (180, 110, 255), intensity=wave_intensity)
        wave_rect = wave_surface.get_rect(midbottom=(BOSS.centerx, BOSS.top + 6))
        screen.blit(wave_surface, wave_rect)
    
    if leg_shot_text_timer > 0:
        try:
            # 작은 폰트 사용 (20pt)
            font = pygame.freetype.Font(resource_path(os.path.join("fonts", "pixel", "NeoDunggeunmoPro.ttf")), 20)
            
            # 애니메이션 진행도 (0.0 ~ 1.0)
            progress = 1.0 - (leg_shot_text_timer / LEG_SHOT_TEXT_DURATION)
            
            # 다이나믹한 애니메이션 계산 (회전 제거)
            if progress < 0.1:  # 0~0.1초: 급격한 확대
                scale = 0.5 + (progress * 15)  # 0.5에서 2.0까지
                alpha = 255
            elif progress < 0.3:  # 0.1~0.3초: 안정화
                scale = 2.0 - ((progress - 0.1) * 5)  # 2.0에서 1.0으로
                alpha = 255
            elif progress < 0.7:  # 0.3~0.7초: 유지
                scale = 1.0
                alpha = 255
            else:  # 0.7~1.0초: 페이드 아웃
                scale = 1.0 - ((progress - 0.7) * 1.0)  # 축소하며 사라짐
                alpha = int(255 * (1.0 - progress) / 0.3)
            
            # 텍스트 렌더링
            text_surface, text_rect = font.render("레그샷!", (255, 255, 255))
            
            # 발광 효과를 위한 배경
            glow_surface = pygame.Surface((text_surface.get_width() + 20, text_surface.get_height() + 20), pygame.SRCALPHA)
            
            # 초록색 발광 효과 (여러 겹)
            for i in range(3):
                glow_alpha = alpha // (i + 2)
                glow_size = 5 * (3 - i)
                pygame.draw.ellipse(glow_surface, (50, 255, 50, glow_alpha), 
                                  (10 - glow_size, 10 - glow_size, 
                                   text_surface.get_width() + glow_size * 2, 
                                   text_surface.get_height() + glow_size * 2))
            
            # 텍스트를 glow surface 중앙에 배치
            glow_surface.blit(text_surface, (10, 10))
            
            # 스케일만 적용 (회전 없이)
            if scale != 1.0:
                glow_surface = pygame.transform.scale(glow_surface, 
                                                    (int(glow_surface.get_width() * scale), 
                                                     int(glow_surface.get_height() * scale)))
            
            # 알파값 적용
            glow_surface.set_alpha(alpha)
            
            # 화면에 그리기 (보스 패들 왼쪽 하단)
            # 보스 패들의 왼쪽 하단 위치 계산
            text_x = BOSS.left - 30  # 보스 왼쪽에서 30픽셀 왼쪽
            text_y = BOSS.bottom - 20  # 보스 하단에서 20픽셀 위
            final_rect = glow_surface.get_rect(center=(text_x, text_y))
            screen.blit(glow_surface, final_rect)
            
            # 임팩트 라인 효과 (초반에만)
            if progress < 0.2:
                line_brightness = int(255 * (1.0 - progress * 5))
                for angle in range(0, 360, 45):
                    end_x = text_x + math.cos(math.radians(angle)) * 50 * (1 + progress * 2)
                    end_y = text_y + math.sin(math.radians(angle)) * 50 * (1 + progress * 2)
                    pygame.draw.line(screen, (line_brightness, line_brightness // 2, line_brightness // 2), 
                                   (text_x, text_y), 
                                   (end_x, end_y), 2)
            
        except Exception as e:
            print(f"레그샷 텍스트 렌더링 오류: {e}")

