def is_player_in_smoke():
    """플레이어가 연막 안에 있는지 확인하는 함수"""
    global smoke_zones, PLAYER
    
    # 기존 연막탄 연기 체크
    for smoke_zone in smoke_zones:
        if smoke_zone["opacity"] > 50:  # 연막이 충분히 진할 때만
            # 플레이어와 연막 중심 사이의 타원형 거리 계산
            dx = PLAYER.centerx - smoke_zone["x"]
            dy = PLAYER.centery - smoke_zone["y"]
            radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
            radius_y = smoke_zone["radius"]
            # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
            if radius_x > 0 and radius_y > 0:
                ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
            else:
                ellipse_distance = float('inf')
            if ellipse_distance <= 1:
                return True
    
    # 테크니컬조끼 연막 체크
    if check_technical_vest_smoke_collision(PLAYER.centerx, PLAYER.centery):
        return True
    
    return False
def handle_wall():
    """벽돌 설치 및 관리 함수"""
    global walls, pending_wall, wall_installing, wall_install_timer, wall_install_gauge_visible
    global boss_stunned_timer, boss_knockback_vel, explosion_zones, grenades
    global boss_confused_timer, flares, flare_zones, last_hit_by
    global spider_mines, spider_mine_slow_active, spider_mine_slow_timer, spider_mine_slow_text_timer
    global boss_current_health, boss_max_health  #  체력형 보스 체력 변수
    global boss_fire_hit_count, boss_fire_hit_timer  #  보스 화염 타격 카운터
    global special_gauge, special_ready  # 게이지 관련 변수 추가
    # 설치 중인 경우
    if wall_installing:
        wall_install_timer -= 1
        if wall_install_timer <= 0:
            wall_install_timer = 0
            wall_installing = False
            wall_install_gauge_visible = False  # 설치 게이지 숨기기
            if pending_wall is not None:
                walls.append(pending_wall)
                pending_wall = None
            print("!    .")
    # 파괴된 벽돌들 제거 (부서지는 이펙트 생성)
    destroyed_walls = [wall for wall in walls if wall["hit_count"] >= 2]
    for wall in destroyed_walls:
        # 벽돌 부서지는 파티클 이펙트 생성
        create_brick_destruction_effect(wall["rect"])
    walls = [wall for wall in walls if wall["hit_count"] < 2]
    # 스파이더지뢰 이동 업데이트
    update_spider_mines()
    # 수류탄 업데이트
    global grenade_shake_timer, boss_stunned_timer, boss_knockback_vel, explosion_zones
    for grenade in grenades[:]:
        # 중력 적용
        if grenade["gravity"] > 0:
            grenade["vel_y"] += grenade["gravity"]
        grenade["x"] += grenade["vel_x"]
        grenade["y"] += grenade["vel_y"]
        grenade["rotation"] += 15  # 회전 (화염병보다 빠름)
        # 목표 지점에 도달했는지 체크
        if abs(grenade["x"] - grenade["target_x"]) < 30 and abs(grenade["y"] - grenade["target_y"]) < 30:
            # 폭발 효과 - 화염병보다 넓은 범위
            import items
            # 코만도암 효과: 폭발 범위 10% 증가
            base_radius = 150  # 폭발 반경 (120에서 150으로 증가)
            if items.commando_arm_obtained:
                explosion_radius = int(base_radius * 1.1)  # 10% 증가
                print(f"  !   : {explosion_radius} (: {base_radius})")
            else:
                explosion_radius = base_radius
            
            explosion_zone = {
                "x": grenade["x"],
                "y": grenade["y"],
                "radius": explosion_radius,  # 코만도암 효과 적용된 폭발 반경
                "duration": 15,  # 폭발 효과 지속 시간 (짧음)
                "active": True
            }
            # 화면 흔들림 효과 시작 (폭발하면 무조건 흔들림)
            grenade_shake_timer = 40  # 40프레임 동안 흔들림 (2배로 증가)
            play_sound_with_volume(SOUND_GRENADE)  #  수류탄 폭발 사운드 재생
            print(f"  !   : {grenade_shake_timer}")
            # 보스가 폭발 범위 내에 있는지 체크
            boss_center_x = BOSS.centerx
            boss_center_y = BOSS.centery
            distance = calculate_distance((boss_center_x, boss_center_y), (grenade["x"], grenade["y"]))
            if distance < explosion_zone["radius"]:
                # 보스 스턴 및 넉백 효과
                boss_stunned_timer = 120  # 2초 스턴
                # 화염병처럼 넉백 효과 (튕겨나가는 느낌)
                knockback_power = 40  # 넉백 강도 조정
                if grenade["x"] < WIDTH / 2:
                    # 수류탄이 왼쪽에서 터지면 보스를 오른쪽으로 넉백
                    boss_knockback_vel = knockback_power
                else:
                    # 수류탄이 오른쪽에서 터지면 보스를 왼쪽으로 넉백
                    boss_knockback_vel = -knockback_power
                #  체력형 보스 수류탄 데미지 적용
                if current_stage in boss_health_stages:
                    boss_current_health = max(0, boss_current_health - 3)  # 수류탄 데미지 3
                    print(f"  !   -{3} (: {boss_current_health}/{boss_max_health})")
                else:
                    print(f"  !")
                
                # 코만도 캐릭터의 수류탄 보스 명중 시 게이지 50+ 증가
                global special_gauge, special_ready, selected_character_type
                if selected_character_type == "soldier":
                    gauge_increase = 50  # 기본 50 증가
                    
                    # 코만도암 착용 시 추가 보너스
                    if items.commando_arm_obtained:
                        gauge_increase = 70  # 코만도암 착용 시 70 증가
                        print("🎯 코만도암 보너스! 수류탄 게이지 70 증가!")
                    else:
                        print("💥 수류탄 명중! 게이지 50 증가!")
                    
                    # 게이지 증가 적용
                    old_gauge = special_gauge
                    special_gauge += gauge_increase
                    current_max = get_max_gauge()
                    if special_gauge > current_max:
                        special_gauge = current_max
                    
                    # 필살기 준비 상태 업데이트
                    if special_gauge >= 350:
                        special_ready = True
                    
                    print(f"수류탄 게이지 충전: {old_gauge} → {special_gauge} (+{gauge_increase})")
                
                #  Stage 5 홍련 수류탄 피격 효과 - 100% 확률
                if current_stage == 5:
                    stage5_boss_hurt_active = True
                    stage5_boss_hurt_timer = 18  # 0.3초 (60 FPS 기준)
                    
                    # 피격 사운드 재생 (3개 중 랜덤)
                    if SOUND_STAGE5_HURTS:
                        play_sound_with_volume(random.choice(SOUND_STAGE5_HURTS))
                    
                    #  트레이드 별 2개 드롭
                    for i in range(2):
                        trade_point_system.spawn_star(
                            BOSS.centerx + random.randint(-50, 50),
                            BOSS.centery + random.randint(-20, 20),
                            source_type="hongryun_grenade"
                        )
                    
                    print(f" Stage 5   ! (100% )   2 !")
            
            #  폭발 범위 내의 바위들 파괴 (스테이지 2)
            if current_stage == 2 and animated_bg_stage2 is not None:
                rocks_to_destroy = []
                for rock in animated_bg_stage2.crisis_rocks:
                    if not rock['falling']:  # 떨어진 바위만 체크
                        rock_center_x = rock['x']
                        rock_center_y = rock['y']
                        rock_distance = calculate_distance((rock_center_x, rock_center_y), (grenade["x"], grenade["y"]))
                        if rock_distance < explosion_zone["radius"]:
                            rocks_to_destroy.append(rock)
                
                # 폭발 범위 내의 모든 바위 파괴
                for rock in rocks_to_destroy:
                    # 황금 바위인 경우 Star Point 별 생성
                    if rock.get('is_golden', False):
                        trade_point_system.spawn_star(rock['x'], rock['y'], "golden_rock")
                        print(f"    ! Star Point  !")
                    
                    animated_bg_stage2.destroy_rock(rock)
                    animated_bg_stage2.crisis_rocks.remove(rock)
                    
                if rocks_to_destroy:
                    print(f"    {len(rocks_to_destroy)} !")
            
            #  폭발 범위 내의 까마귀들 파괴 (스테이지 4)
            if current_stage == 4 and animated_bg_stage4 is not None:
                crow_positions = animated_bg_stage4.get_crow_positions()
                crows_to_destroy = []
                
                for crow_data in crow_positions:
                    crow_distance = calculate_distance((crow_data['x'], crow_data['y']), (grenade["x"], grenade["y"]))
                    if crow_distance < explosion_zone["radius"]:
                        crows_to_destroy.append(crow_data)
                
                # 폭발 범위 내의 모든 까마귀 파괴 및 Star Point 별 생성
                for crow_data in sorted(crows_to_destroy, key=lambda x: x['index'], reverse=True):  # 역순으로 제거
                    if animated_bg_stage4.catch_crow(crow_data['index']):
                        # Star Point 별 생성
                        trade_point_system.spawn_star(crow_data['x'], crow_data['y'], "crow")
                        print(f"    ! Star Point  !")
                
                if crows_to_destroy:
                    print(f"    {len(crows_to_destroy)} !")
            
            # 현실감 있는 수류탄 폭발 효과
            # 1. 폭발 파편 효과 (다양한 크기와 속도)
            for _ in range(50):  # 파편 수 증가
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(5.0, 15.0)  # 더 빠른 파편
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed
                tear_particles.append([
                    grenade["x"] + random.uniform(-10, 10),
                    grenade["y"] + random.uniform(-10, 10),
                    vx, vy,
                    255,  # alpha
                    random.randint(3, 8)  # 다양한 크기의 파편
                ])
            # 2. 연기 효과 (회색 파티클)
            for _ in range(TILE_SIZE):
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(1.0, 4.0)  # 느린 연기
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed - 0.5  # 위로 올라가는 연기
                tear_particles.append([
                    grenade["x"] + random.uniform(-30, 30),
                    grenade["y"] + random.uniform(-30, 30),
                    vx, vy,
                    180,  # alpha
                    random.randint(15, 25)  # 큰 연기 입자
                ])
            # 3. 폭발 섬광 효과 (노란색/주황색 불꽃)
            for _ in range(20):
                angle = random.uniform(0, FULL_ROTATION)
                speed = random.uniform(8.0, 12.0)
                vx = math.cos(math.radians(angle)) * speed
                vy = math.sin(math.radians(angle)) * speed
                tear_particles.append([
                    grenade["x"],
                    grenade["y"],
                    vx, vy,
                    255,  # alpha
                    random.randint(10, 15)  # 섬광 크기
                ])
            explosion_zones.append(explosion_zone)
            grenades.remove(grenade)
            # 폭발 효과음
            try:
                play_wall_sound()
            except:
                pass
            print(f"  ! : X={explosion_zone['x']:.1f}, Y={explosion_zone['y']:.1f}, : {explosion_zone['radius']}")
    # 폭발 지역 업데이트 (지속시간 감소)
    explosion_zones = [zone for zone in explosion_zones if zone["duration"] > 0]
    for zone in explosion_zones:
        zone["duration"] -= 1
    # 연막탄 업데이트
    for smoke_grenade in smoke_grenades[:]:
        if not smoke_grenade["arrived"]:
            # 포물선 궤적으로 비행
            smoke_grenade["vel_y"] += smoke_grenade["gravity"]  # 중력 적용
            smoke_grenade["x"] += smoke_grenade["vel_x"]
            smoke_grenade["y"] += smoke_grenade["vel_y"]
            smoke_grenade["rotation"] += 15  # 더 빠른 회전
            # 궤적 추가 (흔적 효과)
            if len(smoke_grenade["trail"]) > 10:
                smoke_grenade["trail"].pop(0)
            smoke_grenade["trail"].append((smoke_grenade["x"], smoke_grenade["y"]))
            # 목표 지점 도달 체크 (바닥에 닿으면)
            if smoke_grenade["y"] >= smoke_grenade["target_y"]:
                smoke_grenade["arrived"] = True
                smoke_grenade["y"] = smoke_grenade["target_y"]
                print(f"  ! 1")
                # 착지 효과음
                try:
                    play_paddle_sound()
                except:
                    pass
        elif smoke_grenade["timer"] < 60:  # 1초 대기
            smoke_grenade["timer"] += 1
            # 1초 후 연막 생성
            if smoke_grenade["timer"] >= 60:
                # 연막 지역 생성
                import items
                # 코만도암 효과: 연막탄 지속시간 50% 증가
                base_duration = 600  # 10초 지속 (9초 + 1초 페이드아웃)
                if items.commando_arm_obtained:
                    smoke_duration = int(base_duration * 1.5)  # 50% 증가 (15초)
                    print(f"  !  : {smoke_duration/60:.1f} (: {base_duration/60:.1f})")
                else:
                    smoke_duration = base_duration
                
                smoke_zone = {
                    "x": smoke_grenade["x"],
                    "y": smoke_grenade["target_y"],
                    "radius": 0,  # 초기 반경 0에서 시작
                    "max_radius": 180,  # 최대 세로 반경
                    "radius_x": 0,  # 가로 반경 (별도 관리)
                    "max_radius_x": 240,  # 최대 가로 반경 (240픽셀)
                    "duration": smoke_duration,  # 코만도암 효과 적용된 지속시간
                    "particles": [],  # 연막 파티클들
                    "opacity": 0,  # 초기 투명도
                    "expansion_rate": 5,  # 세로 확장 속도
                    "expansion_rate_x": 6.7  # 가로 확장 속도 (240/36 프레임)
                }
                # 화로 연막탄인 경우 플래그 전달
                if 'is_brazier_smoke' in smoke_grenade:
                    smoke_zone['is_brazier_smoke'] = True
                # 초기 연막 파티클 생성 (중앙에서 시작, 가로로 더 넓게)
                for i in range(40):  # 파티클 수 증가
                    angle = random.uniform(0, 2 * math.pi)
                    dist = random.uniform(0, 10)
                    particle = {
                        "x": smoke_zone["x"] + math.cos(angle) * dist * 2,  # 가로로 2배
                        "y": smoke_zone["y"] + math.sin(angle) * dist,
                        "size": random.uniform(20, 40),  # 더 큰 파티클
                        "vel_x": math.cos(angle) * random.uniform(1.0, 3.0),  # 가로로 더 빠르게 퍼짐
                        "vel_y": random.uniform(-0.5, -0.2),
                        "lifetime": random.uniform(80, 150)
                    }
                    smoke_zone["particles"].append(particle)
                smoke_zones.append(smoke_zone)
                smoke_grenades.remove(smoke_grenade)
                # 연막 분출 효과음 (이미 사용 시 재생했으므로 제거)
                # 연막이 생성되는 시각적 효과만 표시
                print(f"  ! 9 .")
    # 연막 지역 업데이트
    for smoke_zone in smoke_zones[:]:
        smoke_zone["duration"] -= 1
        # 연막 반경 점진적 확대 (타원형)
        if smoke_zone["radius"] < smoke_zone["max_radius"]:
            smoke_zone["radius"] = min(smoke_zone["max_radius"], 
                                      smoke_zone["radius"] + smoke_zone["expansion_rate"])
        if "radius_x" in smoke_zone and smoke_zone["radius_x"] < smoke_zone["max_radius_x"]:
            smoke_zone["radius_x"] = min(smoke_zone["max_radius_x"], 
                                        smoke_zone["radius_x"] + smoke_zone["expansion_rate_x"])
        
        # Stage 4에서 화로 점화 체크 (연막이 확장되면서 화로에 닿는지 확인)
        if (current_stage == 4 and animated_bg_stage4 and 
            smoke_zone.get('is_brazier_smoke', False) and 
            not smoke_zone.get('brazier_checked', False)):
            # 연막이 충분히 확장되었을 때 화로 점화 체크
            if smoke_zone["radius"] >= 50:  # 어느 정도 확장된 후 체크
                # 디버그: 화로 위치와 연막 위치 출력
                brazier_x, brazier_y = animated_bg_stage4.get_brazier_position()
                distance = math.sqrt((smoke_zone["x"] - brazier_x)**2 + (smoke_zone["y"] - brazier_y)**2)
                print(f"   - :({smoke_zone['x']:.0f},{smoke_zone['y']:.0f}),"
                      f"화로위치:({brazier_x},{brazier_y}), 연막반경:{smoke_zone['radius']:.0f}, "
                      f"거리:{distance:.1f}")
                
                lit = animated_bg_stage4.check_smoke_touches_brazier(
                    smoke_zone["x"], smoke_zone["y"], smoke_zone["radius"])
                if lit:
                    print(f"     !")
                    smoke_zone['has_lit_brazier'] = True
                else:
                    print(f"    -")
                smoke_zone['brazier_checked'] = True  # 중복 체크 방지
        # 투명도 조절 (서서히 나타났다가 사라짐)
        if smoke_zone["duration"] > 540:  # 처음 1초: 페이드인
            smoke_zone["opacity"] = min(150, smoke_zone["opacity"] + 5)
        elif smoke_zone["duration"] > 60:  # 중간 8초: 유지
            smoke_zone["opacity"] = 150
        else:  # 마지막 1초: 페이드아웃
            smoke_zone["opacity"] = max(0, smoke_zone["opacity"] - 3)
        # 파티클 추가 생성 (지속적인 연기 효과, 타원형)
        if smoke_zone["duration"] > 60 and len(smoke_zone["particles"]) < 60:  # 파티클 수 증가
            if random.random() < 0.5:  # 50% 확률로 새 파티클
                angle = random.uniform(0, 2 * math.pi)
                # 타원형 분포
                radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
                radius_y = smoke_zone["radius"]
                dist_x = random.uniform(0, radius_x * 0.7)
                dist_y = random.uniform(0, radius_y * 0.7)
                particle = {
                    "x": smoke_zone["x"] + math.cos(angle) * dist_x,
                    "y": smoke_zone["y"] + math.sin(angle) * dist_y,
                    "size": random.uniform(30, 50),  # 더 큰 파티클
                    "vel_x": math.cos(angle) * random.uniform(0.3, 1.2),  # 가로로 더 활발한 움직임
                    "vel_y": random.uniform(-0.2, -0.05),
                    "lifetime": random.uniform(40, 80)
                }
                smoke_zone["particles"].append(particle)
        # 파티클 업데이트
        for particle in smoke_zone["particles"][:]:
            particle["x"] += particle["vel_x"]
            particle["y"] += particle["vel_y"]
            particle["lifetime"] -= 1
            particle["size"] *= 0.99  # 서서히 작아짐
            if particle["lifetime"] <= 0 or particle["size"] < 5:
                smoke_zone["particles"].remove(particle)
        # 공이 연막 안에 있는지 체크 (타원형)
        dx = BALL.centerx - smoke_zone["x"]
        dy = BALL.centery - smoke_zone["y"]
        radius_x = smoke_zone.get("radius_x", smoke_zone["radius"])
        radius_y = smoke_zone["radius"]
        # 타원 방정식: (x/a)^2 + (y/b)^2 <= 1
        if radius_x > 0 and radius_y > 0:
            ellipse_distance = (dx / radius_x) ** 2 + (dy / radius_y) ** 2
        else:
            ellipse_distance = float('inf')
        if ellipse_distance <= 1 and smoke_zone["opacity"] > 50:
            # 보스가 친 공만 연막 효과 적용 (플레이어가 친 공은 무시)
            if last_hit_by == "boss":
                # 현재 공 속도 계산
                current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                
                # 공속이 25 이상일 때만 연막 효과 적용
                if current_speed >= 25:
                    # 처음 진입 시 원래 속도 저장 및 즉시 60%로 감속
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        smoke_zone["original_speed"] = current_speed  # 원래 속도 저장
                        
                        # 즉시 60%로 감속 (40% 감소)
                        speed_factor = 0.6
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                        
                        new_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                        print(f"     !  60% ! ({current_speed:.1f} → {new_speed:.1f})")
                    # 이미 연막 안에 있는 경우 60% 속도 유지
                    else:
                        # 60% 속도 유지 (더 이상 감속하지 않음)
                        pass
                elif current_speed > 15.0:
                    # 15~25 구간은 기존 점진적 감속 유지
                    speed_reduction = 0.97  # 매 프레임마다 3% 감속
                    ball_vel[0] *= speed_reduction
                    ball_vel[1] *= speed_reduction
                    # 최소 속도 보장
                    min_speed = 2.0
                    current_speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
                    if current_speed < min_speed and current_speed > 0:
                        speed_factor = min_speed / current_speed
                        ball_vel[0] *= speed_factor
                        ball_vel[1] *= speed_factor
                    # 처음 진입 시에만 메시지 출력
                    if not hasattr(smoke_zone, "affecting_ball"):
                        smoke_zone["affecting_ball"] = True
                        print(f"     !   ... ( : {current_speed:.1f})")
                else:
                    # 느린 공은 디버프 적용 안함
                    if not hasattr(smoke_zone, "slow_ball_ignored"):
                        smoke_zone["slow_ball_ignored"] = True
                        print(f"     ! ( : {current_speed:.1f} <= 15.0)")
            else:
                # 플레이어가 친 공은 연막 효과 무시
                if not hasattr(smoke_zone, "player_ball_ignored"):
                    smoke_zone["player_ball_ignored"] = True
                    print(f"      !")
        else:
            # 연막을 벗어나면 플래그 제거
            if hasattr(smoke_zone, "affecting_ball"):
                del smoke_zone["affecting_ball"]
                print(f"")
            if hasattr(smoke_zone, "original_speed"):
                del smoke_zone["original_speed"]
            if hasattr(smoke_zone, "slow_ball_ignored"):
                del smoke_zone["slow_ball_ignored"]
            if hasattr(smoke_zone, "player_ball_ignored"):
                del smoke_zone["player_ball_ignored"]
        # 지속시간 종료 체크
        if smoke_zone["duration"] <= 0:
            # Stage 4에서 화로를 통해 소환된 몽크가 있으면 30초 후 귀환 타이머 시작
            if current_stage == 4 and animated_bg_stage4 and smoke_zone.get('has_lit_brazier', False):
                animated_bg_stage4.trigger_smoke_grenade_monk_return()
                print(f"  !  30   .")
            smoke_zones.remove(smoke_zone)
    # 조명탄 업데이트
    for flare in flares[:]:
        if not flare["arrived"]:
            # 아직 날아가는 중이면 이동
            flare["x"] += flare["vel_x"]
            flare["y"] += flare["vel_y"]
            flare["rotation"] += 12  # 회전
            # 목표 지점에 도달했는지 체크 (거리 기반으로 체크)
            dist_to_target = math.sqrt((flare["x"] - flare["target_x"])**2 + 
                                      (flare["y"] - flare["target_y"])**2)
            if dist_to_target < 10:  # 목표 지점에 충분히 가까워졌을 때
                flare["arrived"] = True
                flare["x"] = flare["target_x"]  # 정확한 위치에 고정
                flare["y"] = flare["target_y"]
                print(f"  ! 1.5  .")
        elif not flare["exploded"]:
            # 도착 후 타이머 증가
            flare["timer"] += 1
            # 1.5초(90프레임) 후 폭발
            if flare["timer"] >= 90:
                flare["exploded"] = True
                #  조명탄 폭발 사운드 재생
                try:
                    play_sound_with_volume(SOUND_FLASHBOMB)
                except:
                    pass  # 사운드 재생 실패 시 무시
                # 섬광 효과 생성 (0.15초 = 9프레임)
                import items
                # 코만도암 효과: 폭발 범위 10% 증가
                base_radius = 180  # 조명 반경
                if items.commando_arm_obtained:
                    flare_radius = int(base_radius * 1.1)  # 10% 증가
                    print(f"  !   : {flare_radius} (: {base_radius})")
                else:
                    flare_radius = base_radius
                
                flare_zone = {
                    "x": flare["x"],
                    "y": flare["y"],
                    "radius": flare_radius,  # 코만도암 효과 적용된 조명 반경
                    "duration": 9,  # 0.15초 섬광 (60fps * 0.15)
                    "intensity": 1.0,
                    "flash": True  # 섬광 효과 플래그
                }
                flare_zones.append(flare_zone)
                # 보스가 폭발 범위 내에 있는지 체크
                boss_distance = calculate_distance(get_center_pos(BOSS), (flare["x"], flare["y"]))
                if boss_distance <= flare_radius:  # 폭발 반경 내에 있으면
                    boss_confused_timer = THREE_SECONDS_FRAMES  # 3초간 보스 혼란
                    print(f"  !  3  !")
                    
                    # 코만도 캐릭터의 조명탄 보스 명중 시 게이지 50+ 증가
                    if selected_character_type == "soldier":
                        gauge_increase = 50  # 기본 50 증가
                        
                        # 코만도암 착용 시 추가 보너스
                        if items.commando_arm_obtained:
                            gauge_increase = 70  # 코만도암 착용 시 70 증가
                            print("🎯 코만도암 보너스! 조명탄 게이지 70 증가!")
                        else:
                            print("💡 조명탄 명중! 게이지 50 증가!")
                        
                        # 게이지 증가 적용
                        old_gauge = special_gauge
                        special_gauge += gauge_increase
                        current_max = get_max_gauge()
                        if special_gauge > current_max:
                            special_gauge = current_max
                        
                        # 필살기 준비 상태 업데이트
                        if special_gauge >= 350:
                            special_ready = True
                        
                        print(f"조명탄 게이지 충전: {old_gauge} → {special_gauge} (+{gauge_increase})")
                else:
                    print(f"  ! : {boss_distance:.0f}")
                flares.remove(flare)
                # 효과음
                try:
                    play_wall_sound()
                except:
                    pass
                print(f"  !  5  !")
    # 조명 지대 업데이트 (섬광 효과)
    for zone in flare_zones[:]:
        zone["duration"] -= 1
        if zone.get("flash", False):
            # 섬광 효과: 빠르게 깜빡임 (0.15초 = 9프레임)
            if zone["duration"] > 6:  # 처음 0.05초는 최대 밝기
                zone["intensity"] = 1.0
            elif zone["duration"] > 3:  # 다음 0.05초는 어두워짐
                zone["intensity"] = 0.3
            else:  # 마지막 0.05초는 다시 밝아짐
                zone["intensity"] = 0.8
        else:
            zone["intensity"] = zone["duration"] / 9.0  # 일반 페이드 아웃
        if zone["duration"] <= 0:
            flare_zones.remove(zone)
    # 보스 혼란 타이머 감소
    if boss_confused_timer > 0:
        boss_confused_timer -= 1
    # 화염병 업데이트
    if molotovs and random.random() < 0.1:  # 10% 확률로 디버그 출력
        print(f"[DEBUG]   : {len(molotovs)}, : {pygame.time.get_ticks()}ms")
    for molotov in molotovs[:]:
        # 중력 적용 (gravity가 0이면 적용 안함)
        if molotov["gravity"] > 0:
            molotov["vel_y"] += molotov["gravity"]
        molotov["x"] += molotov["vel_x"]
        molotov["y"] += molotov["vel_y"]
        molotov["rotation"] += 10  # 회전
        # 목표 지점에 도달했는지 체크 (화염병이 목표 Y좌표에 도달하면 폭발)
        if molotov["y"] <= molotov["target_y"]:
            # 폭발 효과 - 불길이 번지는 효과
            import items
            # 코만도암 효과: 폭발 범위 10% 증가
            base_width = 150  # 화염 지대 너비
            base_height = 60  # 화염 지대 높이
            if items.commando_arm_obtained:
                fire_width = int(base_width * 1.1)  # 10% 증가
                fire_height = int(base_height * 1.1)  # 10% 증가
                print(f"  !   : {fire_width}x{fire_height} (: {base_width}x{base_height})")
            else:
                fire_width = base_width
                fire_height = base_height
            
            fire_zone = {
                "x": molotov["x"],
                "y": molotov["target_y"],  # 목표 지점에 생성
                "width": fire_width,  # 코만도암 효과 적용된 화염 지대 너비
                "height": fire_height,  # 코만도암 효과 적용된 화염 지대 높이
                "duration": 150,  # 2.5초 (60fps * 2.5)
                "flames": [],  # 개별 불꽃 파티클들
                "spread_timer": 0  # 불길 번짐 타이머
            }
            # 초기 불꽃 파티클 생성 (불길이 번지는 효과)
            for i in range(15):
                flame = {
                    "x": molotov["x"] + random.uniform(-30, 30),
                    "y": molotov["target_y"] + random.uniform(-10, 10),
                    "size": random.uniform(8, 20),
                    "lifetime": random.uniform(20, 40),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
            fire_zones.append(fire_zone)
            molotovs.remove(molotov)
            # 폭발 효과음
            try:
                play_sound_with_volume(SOUND_FIREBOMB)  #  화염병 폭발 사운드 재생
            except:
                pass
            print(f"  !    : X={fire_zone['x']:.1f}, Y={fire_zone['y']:.1f}")
    # 화염 지대 업데이트
    for fire_zone in fire_zones[:]:
        fire_zone["duration"] -= 1
        fire_zone["spread_timer"] += 1
        # push_timer가 없으면 초기화
        if "push_timer" not in fire_zone:
            fire_zone["push_timer"] = 0
        fire_zone["push_timer"] += 1

        # 불길 번짐 효과 - 지속적으로 새 불꽃 추가
        if fire_zone["spread_timer"] % 5 == 0 and len(fire_zone["flames"]) < 30:
            for i in range(3):
                flame = {
                    "x": fire_zone["x"] + random.uniform(-fire_zone["width"]/2, fire_zone["width"]/2),
                    "y": fire_zone["y"] + random.uniform(-fire_zone["height"]/2, fire_zone["height"]/2),
                    "size": random.uniform(10, 25),
                    "lifetime": random.uniform(15, 30),
                    "color_phase": random.uniform(0, 1)
                }
                fire_zone["flames"].append(flame)
        # 불꽃 파티클 업데이트
        for flame in fire_zone["flames"][:]:
            flame["lifetime"] -= 1
            flame["size"] *= 0.97  # 서서히 작아짐
            flame["y"] -= random.uniform(0.1, 0.5)  # 위로 살짝 올라감
            flame["x"] += random.uniform(-0.5, 0.5)  # 좌우로 흔들림
            if flame["lifetime"] <= 0 or flame["size"] < 2:
                fire_zone["flames"].remove(flame)
        # 보스가 화염 지대 안에 있는지 체크 (이동속도 감소용)
        boss_center_x = BOSS.centerx
        boss_center_y = BOSS.centery
        # 사각형 영역 체크 (불길이 번진 영역 + 패들 크기 고려) - 범위 50% 축소
        # X축 거리 체크 - 보스가 화염 지대 폭 안에 있는지
        x_in_range = abs(boss_center_x - fire_zone["x"]) < (fire_zone["width"]/4 + PADDLE_WIDTH/2)  # width/2 → width/4로 축소
        # Y축 거리 체크 - 보스와 화염 지대 사이 거리
        y_distance = abs(boss_center_y - fire_zone["y"])
        # 보스가 화염 지대 근처에 있으면 (Y축으로 60픽셀 이내)  # 120 → 60으로 축소
        y_in_range = y_distance < 60
        in_fire_zone = x_in_range and y_in_range
        #  화염 지대 내 보스 이동속도 50% 감소 효과 설정
        #  Stage 5 홍련은 화염병에 면역
        if in_fire_zone:
            if current_stage != 5:  # Stage 5 홍련은 화염병 속도 감소에 면역
                # 전역 변수로 보스 속도 감소 플래그 설정 (handle_boss에서 참조)
                fire_zone["boss_in_fire"] = True
                global boss_speed_reduction_active, boss_speed_reduction_factor
                boss_speed_reduction_active = True
                boss_speed_reduction_factor = 0.5  # 50% 감소 = 50%만 유지
            else:
                # Stage 5 홍련은 화염병 효과에 면역
                fire_zone["boss_in_fire"] = False
        else:
            # 보스가 화염 지대를 벗어났을 때
            fire_zone["boss_in_fire"] = False
        # 0.5초마다 보스를 화염 지대 밖으로 밀어내기 (스턴 없이 튕김)
        #  Stage 5 홍련은 화염병 넉백에도 면역
        if fire_zone["push_timer"] >= 30:  # 30프레임 = 0.5초 (9프레임에서 변경)
            fire_zone["push_timer"] = 0
            if in_fire_zone and current_stage != 5:  # Stage 5 홍련은 넉백에 면역
                # 스턴 없이 즉시 밀어내기 - 화염 지대 중심으로부터 반대 방향으로
                push_force = 60  # 매우 강한 밀어내기 힘 (35에서 60으로 대폭 증가)
                # 화염 지대 중심으로부터의 방향에 따라 밀어내기
                if boss_center_x < fire_zone["x"]:
                    # 보스가 화염 지대 왼쪽에 있으면 왼쪽으로 밀기
                    BOSS.x -= push_force
                else:
                    # 보스가 화염 지대 오른쪽에 있으면 오른쪽으로 밀기
                    BOSS.x += push_force
                # 화면 경계 체크
                BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
                #  체력형 보스 화염 데미지 적용 (1초마다 1회씩만 카운트, 3회마다 체력 감소)
                if current_stage in boss_health_stages and boss_fire_hit_timer <= 0:
                    boss_fire_hit_count += 1
                    boss_fire_hit_timer = FPS  # 1초 쿨다운 (60프레임)
                    if boss_fire_hit_count >= 3:
                        boss_current_health = max(0, boss_current_health - 1)  # 3회마다 체력 1 감소
                        boss_fire_hit_count = 0  # 카운터 리셋
                        print(f"  !   -1 (: {boss_current_health}/{boss_max_health})")
                    else:
                        print(f"   {boss_fire_hit_count}/3")
                # 시각적 피드백용 작은 흔들림 효과
                if random.random() < 0.3:  # 30% 확률로 작은 흔들림
                    BOSS.x += random.randint(-3, 3)
                    BOSS.x = max(0, min(WIDTH - PADDLE_WIDTH, BOSS.x))
        # 지속시간 종료 체크
        if fire_zone["duration"] <= 0:
            # 화염 효과음 관련 코드 제거됨 (SOUND_FLAME 사용 안 함)
            fire_zones.remove(fire_zone)
    #  모든 화염 지대를 체크한 후, 보스가 어떤 화염 지대에도 없으면 속도 감소 효과 리셋
    if len(fire_zones) == 0 or not any(zone.get("boss_in_fire", False) for zone in fire_zones):
        boss_speed_reduction_active = False
        boss_speed_reduction_factor = 1.0  # 정상 속도로 복구

def deactivate_whip():
    """상모돌리기 완전 비활성화 - 사운드 정지 보장"""
    global whip_active, whip_timer, whip_wave_particles
    whip_active = False
    whip_timer = 0
    whip_sound.stop()  # 반드시 사운드 정지
    whip_wave_particles.clear()
    print("[DEBUG] 상모돌리기 완전 비활성화 - 사운드 정지 완료")

def activate_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_original_ball_speed, whip_wave_particles
    print(f"[DEBUG] 상모돌리기 활성화 시작!")
    print(f"  - 현재 공 속도: X={ball_vel[0]:.2f}, Y={ball_vel[1]:.2f}")
    print(f"  - 현재 공 위치: X={BALL.centerx}, Y={BALL.centery}")
    print(f"  - 파워스매싱 상태: freeze={power_smashing_freeze_active}, parabola={power_smashing_parabola_active}")
    
    whip_active = True
    whip_timer = whip_duration
    whip_wave_phase = 0  # 사인 파형 초기화
    #  상모돌리기 발동 전 공 속도 저장 (Y축만 원래 속도 유지)
    whip_original_ball_speed = [0, ball_vel[1]]  # X축은 0으로 설정
    print(f"  !   : {whip_original_ball_speed}")
    
    #  파동 파티클 초기화 - 보스에서 플레이어를 향해 나아가는 파동
    whip_wave_particles = []
    
    # 효과음이 처음 발동될 때만 플레이 (무한 반복하지 않고 제한된 시간 동안만)
    whip_sound.play(loops=0)  # 한 번만 재생하고 타이머로 제어
    
    #  X축 속도를 거의 0으로 설정 (일직선 아래로)
    ball_vel[0] = 0
    
    # Y축 속도 조정 (적당한 속도로 아래로)
    ball_vel[1] = abs(ball_vel[1]) * 0.75
    
    #  공이 무조건 플레이어 쪽(아래)으로 향하도록 Y 속도 보정
    if ball_vel[1] < 0:  # 공이 위쪽으로 가고 있다면
        ball_vel[1] = abs(ball_vel[1])  # 아래쪽으로 방향 전환
    # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
    if abs(ball_vel[1]) < 8:
        ball_vel[1] = 8
def handle_whip():
    global whip_active, whip_timer, whip_wave_phase, whip_hit_by_player, whip_wave_particles
    global whip_deactivation_active, whip_deactivation_timer, whip_rotation_speed
    global boss_stunned_after_whip, boss_stunned_after_whip_timer
    
    # 보스 통제불능 상태 처리 (회전 종료 후)
    if boss_stunned_after_whip:
        if boss_stunned_after_whip_timer > 0:
            boss_stunned_after_whip_timer -= 1
        else:
            boss_stunned_after_whip = False
    
    # 강제 해제 모션 처리
    if whip_deactivation_active:
        # 강제 해제 시작 시 사운드 즉시 중지
        if whip_deactivation_timer == whip_deactivation_duration:
            whip_sound.stop()
            
        if whip_deactivation_timer > 0:
            whip_deactivation_timer -= 1
            # 회전 속도를 점차 감소 (이징 효과 적용)
            progress = 1.0 - (whip_deactivation_timer / whip_deactivation_duration)
            # 이징 함수 (ease-out cubic)
            eased_progress = 1.0 - pow(1.0 - progress, 3)
            whip_rotation_speed = (1.0 - eased_progress) * 20.0  # 20에서 0으로 감소 (더 빠른 회전)
            
            # 남은 파동 파티클 업데이트 (점차 사라짐)
            for particle in whip_wave_particles[:]:
                particle['alpha'] -= 8  # 천천히 사라짐 (1.2초 동안)
                particle['radius'] += 3
                if particle['alpha'] <= 0:
                    whip_wave_particles.remove(particle)
        else:
            # 강제 해제 모션 완료 - 통제불능 상태 시작
            whip_deactivation_active = False
            whip_rotation_speed = 0.0
            whip_wave_particles.clear()
            
            # 0.5초 통제불능 상태 시작
            boss_stunned_after_whip = True
            boss_stunned_after_whip_timer = 30  # 0.5초
    
    if whip_active:
        if whip_timer > 0:
            whip_timer -= 1  # 타이머 감소 (효과음의 지속시간)
            old_wave_phase = whip_wave_phase
            whip_wave_phase += 0.3  # 사인 함수로 진폭 파형 진행
            
            # 공이 한 바퀴 돌 때마다 효과음 재생 (사인파가 2π를 넘을 때)
            if int(old_wave_phase / (2 * math.pi)) < int(whip_wave_phase / (2 * math.pi)):
                whip_sound.play()
                print(f"[DEBUG] 상모돌리기 효과음 재생 - 회전수: {int(whip_wave_phase / (2 * math.pi))}")
            
            # 진폭 계산 (사인 함수에 의해 -1에서 1 사이의 값을 가짐)
            wave = math.sin(whip_wave_phase) * 15  # 진폭을 15로 감소 (좌우 흔들림 최소화)
            # 볼륨 조정 제거 - 사운드가 계속 재생되는 문제 방지
            # 공의 속도에 진폭 적용 (X축만 약간 물결치도록)
            # 파워스매싱이 활성화되어 있지 않을 때만 상모돌리기 효과 적용
            if not power_smashing_parabola_active and not power_smashing_freeze_active:
                old_vel_x = ball_vel[0]
                ball_vel[0] = wave  # 원래 속도 무시하고 파동만 적용 (중앙 기준)
                if whip_timer % 30 == 0:  # 0.5초마다 디버그 출력
                    print(f"[DEBUG] 상모돌리기 파동 적용: X속도 {old_vel_x:.2f} → {ball_vel[0]:.2f}")
            else:
                if whip_timer % 30 == 0:  # 0.5초마다 디버그 출력
                    print(f"[DEBUG] 상모돌리기 파동 스킵 (파워스매싱 활성화): freeze={power_smashing_freeze_active}, parabola={power_smashing_parabola_active}")
            
            #  파동 파티클 생성 (10프레임마다)
            if whip_timer % 10 == 0:
                # 보스 위치에서 플레이어 방향으로 파동 생성
                whip_wave_particles.append({
                    'x': BOSS.centerx,
                    'y': BOSS.centery,
                    'radius': 10,
                    'alpha': 255,
                    'speed': 8  # 파동이 퍼지는 속도
                })
            
            # 파동 파티클 업데이트
            for particle in whip_wave_particles[:]:
                # 파동이 플레이어 패들 방향으로 이동
                direction_to_player_y = PLAYER.centery - particle['y']
                direction_to_player_x = PLAYER.centerx - particle['x']
                distance = math.sqrt(direction_to_player_x**2 + direction_to_player_y**2)
                
                if distance > 0:
                    # 정규화된 방향 벡터
                    dir_x = direction_to_player_x / distance
                    dir_y = direction_to_player_y / distance
                    
                    # 파동 이동
                    particle['y'] += dir_y * particle['speed']
                    particle['x'] += dir_x * particle['speed'] * 0.3  # X축은 덜 움직임
                    particle['radius'] += 2  # 파동이 퍼짐
                    particle['alpha'] -= 8  # 점점 투명해짐
                    
                    # 알파값이 0이 되면 제거
                    if particle['alpha'] <= 0:
                        whip_wave_particles.remove(particle)
            
            #  플레이어가 반격한 경우와 아닌 경우를 구분
            if not whip_hit_by_player:
                # 플레이어가 아직 반격하지 않은 경우: 공은 아래쪽(플레이어 방향)으로
                if ball_vel[1] < 0:  # 만약 공이 위로 가려고 하면
                    ball_vel[1] = abs(whip_original_ball_speed[1]) if whip_original_ball_speed[1] != 0 else 10
                # 최소 Y 속도 보장 (너무 수평으로 가지 않도록)
                if abs(ball_vel[1]) < 5:
                    ball_vel[1] = 5
            else:
                # 플레이어가 반격한 경우: 공은 위쪽(보스 방향)으로 유지
                if ball_vel[1] > 0:  # 만약 공이 아래로 가려고 하면
                    ball_vel[1] = -abs(ball_vel[1])  # 위쪽으로 유지
                # 최소 Y 속도 보장
                if abs(ball_vel[1]) < 8:
                    ball_vel[1] = -8
        else:
            # 상모돌리기 효과 완전 종료
            deactivate_whip()  # 통합된 비활성화 함수 사용
def activate_balloon():
    """풍선 스킬 활성화"""
    global balloon_active, balloon_timer, balloons, balloon_used_this_round
    balloon_active = True
    balloon_timer = -1  # -1은 라운드 끝까지 지속
    balloons = []  # 풍선 리스트 초기화
    balloon_used_this_round = True  # 이번 라운드에 사용됨 표시
    # 화면에 3-5개의 풍선 생성
    balloon_colors = [
        (255, 100, 100),  # 빨간색
        (100, 255, 100),  # 초록색
        (100, 100, 255),  # 파란색
        (255, 255, 100),  # 노란색
        (255, 100, 255),  # 마젠타
        (100, 255, 255),  # 시안
    ]
    for i in range(random.randint(3, 5)):
        x = random.randint(100, WIDTH-100)
        y = random.randint(100, HEIGHT-100)
        radius = random.randint(25, 35)
        color = random.choice(balloon_colors)
        # 랜덤한 방향과 속도 설정
        speed = random.uniform(1.5, 3.0)
        angle = random.uniform(0, 2 * math.pi)
        vx = math.cos(angle) * speed
        vy = math.sin(angle) * speed
        balloons.append({
            "x": x, 
            "y": y, 
            "radius": radius, 
            "color": color,
            "vx": vx,
            "vy": vy,
            "bounce": 0  # 튀는 애니메이션용
        })
    show_speech("풍선 놀이!", duration=60)
def handle_balloon():
    """풍선 스킬 처리"""
    global balloon_active, balloon_timer, balloons
    if balloon_active:
        # 타이머가 -1이면 라운드 끝까지 지속
        if balloon_timer > 0:
            balloon_timer -= 1
        elif balloon_timer == 0:
            # 풍선 스킬 종료
            # balloon_active = False  # Stage 1 보스 풍선파티 스킬 제거됨
            balloons.clear()
            return
        # 풍선 움직임과 벽 충돌 처리
        for balloon in balloons:
            # 풍선 위치 업데이트
            balloon["x"] += balloon["vx"]
            balloon["y"] += balloon["vy"]
            # 튀는 애니메이션
            balloon["bounce"] += 0.2
            balloon["y"] += int(math.sin(balloon["bounce"]) * 1)
            # 벽 충돌 감지 및 튕김 처리
            if balloon["x"] - balloon["radius"] <= 0:  # 왼쪽 벽
                balloon["x"] = balloon["radius"]
                balloon["vx"] = abs(balloon["vx"])  # 오른쪽으로 튕김
            elif balloon["x"] + balloon["radius"] >= WIDTH:  # 오른쪽 벽
                balloon["x"] = WIDTH - balloon["radius"]
                balloon["vx"] = -abs(balloon["vx"])  # 왼쪽으로 튕김
            if balloon["y"] - balloon["radius"] <= 0:  # 위쪽 벽
                balloon["y"] = balloon["radius"]
                balloon["vy"] = abs(balloon["vy"])  # 아래쪽으로 튕김
            elif balloon["y"] + balloon["radius"] >= HEIGHT:  # 아래쪽 벽
                balloon["y"] = HEIGHT - balloon["radius"]
                balloon["vy"] = -abs(balloon["vy"])  # 위쪽으로 튕김
def draw_balloons():
    """풍선 그리기"""
    if not balloon_active:
        return
    for balloon in balloons:
        x, y = balloon["x"], balloon["y"]
        radius = balloon["radius"]
        color = balloon["color"]
        # 풍선 몸체
        draw.circle(color, (int(x), int(y)), radius)
        # 풍선 테두리
        draw.circle(WHITE, (int(x), int(y)), radius, 2)
        # 풍선 줄 (위쪽으로)
        line_start = (int(x), int(y - radius))
        line_end = (int(x), int(y - radius - DEFAULT_RADIUS))
        draw.line((100, 100, 100), line_start, line_end, 2)
        # 풍선 하이라이트 (반짝이는 효과)
        highlight_x = int(x - radius // 3)
        highlight_y = int(y - radius // 3)
        draw.circle(WHITE, (highlight_x, highlight_y), radius // 4)
        # 풍선 움직임 방향 표시 (작은 화살표)
        arrow_length = 8
        arrow_x = int(x + balloon["vx"] * arrow_length)
        arrow_y = int(y + balloon["vy"] * arrow_length)
        draw.line(WHITE, (int(x), int(y)), (arrow_x, arrow_y), 2)
def check_balloon_collisions():
    """풍선과 공의 충돌 감지"""
    if not balloon_active or not balloons:
        return
    for balloon in balloons[:]:  # 복사본으로 순회
        # 풍선의 중심점과 공의 중심점 사이의 거리 계산
        dx = BALL.centerx - balloon["x"]
        dy = BALL.centery - balloon["y"]
        distance = math.sqrt(dx*dx + dy*dy)
        # 충돌 감지 (공 반지름 + 풍선 반지름)
        collision_distance = BALL_RADIUS + balloon["radius"]
        if distance <= collision_distance:
            print(f"  !  : 30")
            #  풍선 터지는 효과음 재생
            play_sound_with_volume(SOUND_BALLOON_BOOM)
            # 풍선 터뜨리기 효과
            effects_manager.create_balloon_pop_effect(balloon["x"], balloon["y"], balloon["color"])
            # 풍선 제거
            balloons.remove(balloon)
            # 현재 공의 각도 계산
            current_angle = math.atan2(ball_vel[1], ball_vel[0])
            # 30도(약 0.524 라디안) 랜덤하게 휘어지기
            angle_change = random.uniform(-0.524, 0.524)  # -30도 ~ +30도
            new_angle = current_angle + angle_change
            # 새로운 속도 계산 (현재 속도 유지)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            ball_vel[0] = math.cos(new_angle) * speed
            ball_vel[1] = math.sin(new_angle) * speed
            # 속도 정규화 제거 - 현재 속도 그대로 유지
            # 충돌 후 즉시 반환 (한 번에 하나의 풍선만 처리)
            return

def activate_spinning_top():
    """Stage 1 보스 팽이치기 스킬 활성화"""
    global spinning_top_active, spinning_top_timer, spinning_tops, spinning_top_used_this_round, whip_animation_timer
    
    spinning_top_active = True
    spinning_top_timer = spinning_top_duration
    spinning_top_used_this_round = True
    whip_animation_timer = 36  # 0.6초 채찍 애니메이션
    
    # 2개의 팽이 생성
    spinning_tops = []
    for i in range(2):
        offset_x = -30 if i == 0 else 30  # 좌우로 약간 떨어뜨려서 생성
        # 15% 확률로 황금 팽이 생성 (각각 독립적으로)
        is_golden = random.random() < 0.15
        spinning_tops.append({
            "x": BOSS.centerx + offset_x,
            "y": BOSS.centery + 40,  # 보스 아래쪽
            "vx": random.uniform(-0.5, 0.5),  # 초기 좌우 속도
            "vy": 0.4,  # 천천히 아래로
            "rotation": random.uniform(0, 360),  # 랜덤 시작 회전
            "rotation_speed": 20,  # 회전 속도
            "tilt": 0,  # 기울기
            "alpha": 255,  # 투명도
            "whip_phase": "preparing",  # 채찍 애니메이션 단계
            "zigzag_timer": i * 10,  # 서로 다른 지그재그 타이밍
            "speed_boost": 0,  # 충돌 시 속도 부스트
            "boost_timer": 0,  # 부스트 지속 시간
            "is_golden": is_golden,  # 황금 팽이 여부
            "star_spawned": False  # 별을 이미 생성했는지 여부
        })
        if is_golden:
            print(f"   ! ( {i+1})")
    
    # 채찍 효과음 재생
    whip_sound.play(maxtime=600)  # 0.6초 재생
    
    print(f"  ! 2  !")

def handle_spinning_top():
    """팽이 업데이트 처리"""
    global spinning_top_active, spinning_top_timer, spinning_tops, whip_animation_timer, top_collision_cooldown, golden_top_star_cooldown
    
    if not spinning_top_active or not spinning_tops:
        return
    
    # 충돌 쿨다운 감소
    if top_collision_cooldown > 0:
        top_collision_cooldown -= 1
    
    # 황금 팽이 별 생성 쿨다운 감소
    if golden_top_star_cooldown > 0:
        golden_top_star_cooldown -= 1
    
    if spinning_top_timer > 0:
        spinning_top_timer -= 1
        
        # 채찍 애니메이션 단계 (처음 0.6초)
        if whip_animation_timer > 0:
            whip_animation_timer -= 1
            if whip_animation_timer == 18:  # 0.3초 시점에 팽이 회전 시작
                for top in spinning_tops:
                    top["whip_phase"] = "spinning"
            return  # 채찍 애니메이션 중에는 팽이가 움직이지 않음
        
        # 팽이끼리 충돌 체크
        if len(spinning_tops) == 2 and top_collision_cooldown <= 0:
            top1, top2 = spinning_tops[0], spinning_tops[1]
            dx = top1["x"] - top2["x"]
            dy = top1["y"] - top2["y"]
            distance = math.sqrt(dx*dx + dy*dy)
            
            # 충돌 판정 (두 팽이가 가까워졌을 때)
            if distance < 40:  # 충돌 거리
                # 충돌 효과
                create_impact_effect(
                    (top1["x"] + top2["x"]) / 2,
                    (top1["y"] + top2["y"]) / 2,
                    [0, 0], is_player=False
                )
                
                # 효과음
                play_sound_with_volume(SOUND_PADDLE)
                
                # 400% 속도 부스트 (0.3초)
                angle = math.atan2(dy, dx)
                boost_speed = 8.0  # 400% 속도
                
                # 서로 반대 방향으로 튕겨나감
                top1["vx"] = math.cos(angle) * boost_speed
                top1["vy"] = math.sin(angle) * boost_speed * 0.3  # y축은 약하게
                top1["speed_boost"] = 4.0
                top1["boost_timer"] = 18  # 0.3초
                
                top2["vx"] = -math.cos(angle) * boost_speed
                top2["vy"] = -math.sin(angle) * boost_speed * 0.3
                top2["speed_boost"] = 4.0
                top2["boost_timer"] = 18
                
                # 충돌 쿨다운 설정
                top_collision_cooldown = 60  # 1초 쿨다운
                
                # 황금 팽이 충돌 시 트레이드 별 생성
                if golden_top_star_cooldown <= 0:
                    # 둘 중 하나라도 황금 팽이면 별 생성
                    if (top1.get("is_golden", False) and not top1.get("star_spawned", False)) or \
                       (top2.get("is_golden", False) and not top2.get("star_spawned", False)):
                        if trade_point_system:
                            # 충돌 지점의 중간 위치에 별 생성
                            star_x = (top1["x"] + top2["x"]) / 2
                            star_y = (top1["y"] + top2["y"]) / 2
                            trade_point_system.spawn_star(star_x, star_y, "golden_top")
                            
                            # 황금 팽이 표시 업데이트
                            if top1.get("is_golden", False):
                                top1["star_spawned"] = True
                            if top2.get("is_golden", False):
                                top2["star_spawned"] = True
                            
                            golden_top_star_cooldown = 30  # 0.5초 쿨타임
                            print(f"   !   !")
                
                print(f"  !   !")
        
        # 각 팽이 업데이트
        for i, top in enumerate(spinning_tops):
            if spinning_top_timer > 30:  # 쓰러지기 전까지
                # 부스트 타이머 처리
                if top["boost_timer"] > 0:
                    top["boost_timer"] -= 1
                    if top["boost_timer"] == 0:
                        # 원래 속도로 복귀
                        top["speed_boost"] = 0
                        top["vx"] *= 0.25  # 원래 속도로
                        top["vy"] = 0.6  # 원래 하강 속도
                
                # 회전
                top["rotation"] += top["rotation_speed"]
                
                # 지그재그 움직임 타이머 증가
                top["zigzag_timer"] += 1
                
                # 부스트 상태가 아닐 때만 일반 움직임
                if top["boost_timer"] <= 0:
                    # 예측불가능한 좌우 움직임
                    if top["zigzag_timer"] % random.randint(20, 40) == 0:
                        top["vx"] = random.uniform(-2.0, 2.0)
                    
                    # 부드러운 좌우 움직임을 위한 사인파
                    wave_x = math.sin(top["zigzag_timer"] * 0.1) * 0.5
                    top["x"] += top["vx"] + wave_x
                    top["y"] += top["vy"]
                else:
                    # 부스트 중일 때는 빠른 속도로 이동
                    top["x"] += top["vx"]
                    top["y"] += top["vy"]
                
                # 화면 경계 체크
                if top["x"] < 40 or top["x"] > WIDTH - 40:
                    top["vx"] *= -1  # 방향 반전
                    top["x"] = max(40, min(WIDTH - 40, top["x"]))
                
                # 천천히 하강 (부스트 상태가 아닐 때)
                if top["y"] < HEIGHT - 100 and top["boost_timer"] <= 0:
                    top["vy"] = 0.6  # 일정한 하강 속도
                
            elif spinning_top_timer > 0:  # 마지막 0.5초 - 쓰러지는 애니메이션
                # 회전 속도 감소
                top["rotation_speed"] *= 0.92
                
                # 기울어짐
                top["tilt"] = 90 * (1 - spinning_top_timer / 30)  # 0도에서 90도로
                
                # 페이드아웃
                top["alpha"] = int(255 * (spinning_top_timer / 30))
    else:
        # 스킬 종료
        spinning_top_active = False
        spinning_tops = []
        print("!")

def check_spinning_top_collision():
    """팽이와 공의 충돌 체크"""
    global ball_vel, golden_top_star_cooldown, trade_point_system
    
    if not spinning_top_active or not spinning_tops:
        return False
    
    # 채찍 애니메이션 중에도 충돌 체크를 해야 함 (삭제)
    
    # 각 팽이와 공의 충돌 체크
    for top in spinning_tops:
        # 쓰러진 상태에서는 충돌 없음
        if top.get("tilt", 0) > 45:
            continue
        
        # 팽이 히트박스 (원형)
        top_radius = 20  # 줄어든 크기에 맞춰 히트박스도 감소
        ball_center = (BALL.centerx, BALL.centery)
        top_center = (top["x"], top["y"])
        
        # 거리 계산
        dx = ball_center[0] - top_center[0]
        dy = ball_center[1] - top_center[1]
        distance = math.sqrt(dx*dx + dy*dy)
        
        # 충돌 판정
        if distance < top_radius + BALL_RADIUS:
            # 황금 팽이인 경우 트레이드 별 생성 (쿨타임 체크)
            if top.get("is_golden", False) and not top.get("star_spawned", False) and golden_top_star_cooldown <= 0:
                if trade_point_system:
                    # 팽이 위치에서 트레이드 별 생성
                    trade_point_system.spawn_star(top["x"], top["y"], "golden_top")
                    top["star_spawned"] = True  # 이 팽이에서 별 생성 완료
                    golden_top_star_cooldown = 30  # 0.5초 쿨타임 (60 FPS)
                    print(f"   !   !")
            
            # 무작위 방향으로 반사
            random_angle = random.uniform(0, 2 * math.pi)
            speed = math.sqrt(ball_vel[0]**2 + ball_vel[1]**2)
            
            ball_vel[0] = math.cos(random_angle) * speed
            ball_vel[1] = math.sin(random_angle) * speed
            
            # 팽이에 튕김 효과 추가 (하프 대쉬 정도의 거리)
            # 충돌 반대 방향으로 밀려남
            if distance > 0:  # 0으로 나누기 방지
                push_angle = math.atan2(-dy, -dx)  # 공의 반대 방향
            else:
                push_angle = random.uniform(0, 2 * math.pi)
            
            # 하프 대쉬 거리 정도의 순간 가속 (약 30-40픽셀)
            push_speed = 12.0  # 순간적으로 빠른 속도
            top["vx"] = math.cos(push_angle) * push_speed
            top["vy"] = math.sin(push_angle) * push_speed * 0.5  # y축은 약간 약하게
            top["speed_boost"] = 3.0  # 속도 부스트 상태
            top["boost_timer"] = 12  # 0.2초간 지속 (짧게)
            
            # 충돌 효과 생성
            create_impact_effect(top_center[0], top_center[1], [0, 0], is_player=False)
            
            # 효과음 재생
            play_sound_with_volume(SOUND_PADDLE)
            
            print(f"  !  !  : {math.degrees(random_angle):.0f}°")
            return True
    
    return False

def draw_whip_waves(screen):
    """상모돌리기 파동 효과 그리기"""
    global whip_wave_particles
    
    if not whip_active or not whip_wave_particles:
        return
    
    # 파동 그리기
    for particle in whip_wave_particles:
        # 파동 색상 (보라색 계열)
        color = (180, 100, 255)
        alpha = particle['alpha']
        
        if alpha > 0:
            # 파동 원 그리기
            wave_surface = pygame.Surface((particle['radius'] * 2, particle['radius'] * 2), pygame.SRCALPHA)
            pygame.draw.circle(wave_surface, (*color, alpha // 2), 
                             (particle['radius'], particle['radius']), 
                             particle['radius'], 3)
            
            # 내부 원 (더 밝게)
            if particle['radius'] > 5:
                pygame.draw.circle(wave_surface, (*color, alpha), 
                                 (particle['radius'], particle['radius']), 
                                 max(1, particle['radius'] - 5), 2)
            
            screen.blit(wave_surface, 
                       (particle['x'] - particle['radius'], 
                        particle['y'] - particle['radius']))

def draw_spinning_top(screen):
    """팽이 그리기"""
    if not spinning_top_active or not spinning_tops:
        return
    
    # 채찍 애니메이션 그리기 (처음 0.6초)
    if whip_animation_timer > 0:
        # 각 팽이에 대한 채찍 그리기
        for top in spinning_tops:
            whip_start = (BOSS.centerx, BOSS.centery)
            whip_end = (top["x"], top["y"])
        
            # 채찍 곡선 효과
            control_x = (whip_start[0] + whip_end[0]) / 2 + math.sin(whip_animation_timer * 0.5) * 30
            control_y = (whip_start[1] + whip_end[1]) / 2 - 20
            
            # 채찍 그리기 (베지어 곡선처럼)
            for i in range(10):
                t = i / 10
                x1 = whip_start[0] * (1-t)**2 + control_x * 2*t*(1-t) + whip_end[0] * t**2
                y1 = whip_start[1] * (1-t)**2 + control_y * 2*t*(1-t) + whip_end[1] * t**2
                t2 = (i+1) / 10
                x2 = whip_start[0] * (1-t2)**2 + control_x * 2*t2*(1-t2) + whip_end[0] * t2**2
                y2 = whip_start[1] * (1-t2)**2 + control_y * 2*t2*(1-t2) + whip_end[1] * t2**2
                
                thickness = 3 - int(i * 0.3)  # 끝으로 갈수록 얇아짐
                pygame.draw.line(screen, (139, 69, 19), (x1, y1), (x2, y2), thickness)
    
    # 각 팽이 그리기
    for top in spinning_tops:
        # 황금 팽이 은은한 빛 효과
        if top.get("is_golden", False):
            # 시간에 따라 부드럽게 변하는 빛 효과
            glow_time = pygame.time.get_ticks() / 1000.0
            glow_intensity = (math.sin(glow_time * 2) + 1) * 0.3 + 0.4  # 0.4 ~ 1.0 사이에서 부드럽게 변화
            
            # 외부 광원 효과 (가장 큰 원)
            glow_surface = pygame.Surface((120, 120), pygame.SRCALPHA)
            glow_center = (60, 60)
            for i in range(20):
                alpha = int(15 * (1 - i/20) * glow_intensity)  # 매우 투명하게
                radius = 60 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(glow_surface, (255, 215, 0, alpha), glow_center, radius)
            screen.blit(glow_surface, (top["x"] - 60, top["y"] - 60))
            
            # 중간 광원 효과
            mid_glow_surface = pygame.Surface((80, 80), pygame.SRCALPHA)
            mid_glow_center = (40, 40)
            for i in range(15):
                alpha = int(25 * (1 - i/15) * glow_intensity)  # 조금 더 진하게
                radius = 40 - i * 2
                if radius > 0 and alpha > 0:
                    pygame.draw.circle(mid_glow_surface, (255, 223, 0, alpha), mid_glow_center, radius)
            screen.blit(mid_glow_surface, (top["x"] - 40, top["y"] - 40))
            
            # 작은 반짝임 파티클 효과
            if random.random() < 0.3:  # 30% 확률로 반짝임 생성
                for _ in range(2):
                    particle_offset_x = random.randint(-30, 30)
                    particle_offset_y = random.randint(-30, 30)
                    particle_size = random.randint(1, 3)
                    particle_alpha = int(random.uniform(100, 200) * glow_intensity)
                    particle_color = (255, random.randint(200, 255), 0, particle_alpha)
                    
                    particle_surface = pygame.Surface((particle_size * 4, particle_size * 4), pygame.SRCALPHA)
                    pygame.draw.circle(particle_surface, particle_color, 
                                     (particle_size * 2, particle_size * 2), particle_size)
                    screen.blit(particle_surface, 
                              (top["x"] + particle_offset_x - particle_size * 2, 
                               top["y"] + particle_offset_y - particle_size * 2))
        
        # 팽이 표면 생성 (작은 크기)
        size = 50  # 팽이 크기
        top_surface = pygame.Surface((size, size), pygame.SRCALPHA)
        center = size // 2
        
        # 팽이 회전 변환 준비
        if top.get("tilt", 0) > 0:
            # 쓰러지는 효과를 위한 변형
            tilt_factor = top["tilt"] / 90
            height_scale = 1 - tilt_factor * 0.5
        else:
            height_scale = 1
    
        # 팽이 몸체 (둥근 모양)
        # 아래쪽 (나무 부분 - 원뿔 형태)
        wood_color = (160, 82, 45, top["alpha"])  # 나무색
        for i in range(10):
            y_offset = center + i * height_scale
            if y_offset < size - 3:
                width = 18 - i * 1.5
                if width > 0:
                    pygame.draw.circle(top_surface, wood_color, 
                                     (center, int(y_offset)), int(width))
        
        # 윗쪽 (회전하는 색상 패턴 - 둥근 원판)
        if top.get("is_golden", False):
            # 황금 팽이는 금색 계열로
            pattern_colors = [
                (255, 215, 0, top["alpha"]),    # 금색
                (255, 223, 0, top["alpha"]),    # 밝은 금색
                (218, 165, 32, top["alpha"]),   # 골든로드
            ]
        else:
            # 일반 팽이
            pattern_colors = [
                (100, 200, 200, top["alpha"]),  # 청록색
                (220, 100, 100, top["alpha"]),  # 빨간색
                (255, 200, 50, top["alpha"]),   # 노란색
            ]
        
        # 부스트 상태일 때 색상 변화
        if top.get("boost_timer", 0) > 0:
            # 부스트 중일 때 밝게 빛나는 효과
            boost_glow = int(128 * (top["boost_timer"] / 18))
            pattern_colors = [
                (min(255, c[0] + boost_glow), 
                 min(255, c[1] + boost_glow), 
                 min(255, c[2] + boost_glow), 
                 c[3]) for c in pattern_colors
            ]
        
        # 회전 효과를 위한 색상 블렌딩
        rotation_phase = (top["rotation"] / 10) % 3
        color_index = int(rotation_phase)
        next_color_index = (color_index + 1) % 3
        blend_factor = rotation_phase - color_index
        
        # 색상 보간
        current_color = pattern_colors[color_index]
        next_color = pattern_colors[next_color_index]
        blended_color = (
            int(current_color[0] * (1 - blend_factor) + next_color[0] * blend_factor),
            int(current_color[1] * (1 - blend_factor) + next_color[1] * blend_factor),
            int(current_color[2] * (1 - blend_factor) + next_color[2] * blend_factor),
            top["alpha"]
        )
        
        # 팽이 상단 원판 (둥근 모양)
        pygame.draw.circle(top_surface, blended_color, 
                          (center, int(center * height_scale - 5)), 18)
        pygame.draw.circle(top_surface, pattern_colors[(color_index + 2) % 3], 
                          (center, int(center * height_scale - 5)), 12)
        pygame.draw.circle(top_surface, pattern_colors[color_index], 
                          (center, int(center * height_scale - 5)), 6)
        
        # 팽이 축 (중심 막대)
        axis_color = (60, 30, 15, top["alpha"])  # 진한 나무색
        pygame.draw.line(top_surface, axis_color, 
                        (center, center * height_scale - 5), 
                        (center, center + 30 * height_scale), 3)
        
        # 화면에 그리기
        screen.blit(top_surface, 
                    (top["x"] - center, top["y"] - center))
        
        # 그림자 효과
        shadow_size = 30 + int(top.get("tilt", 0) / 4)
        shadow_surface = pygame.Surface((shadow_size, 12), pygame.SRCALPHA)
        shadow_alpha = top["alpha"] // 4
        if top.get("tilt", 0) > 0:  # 쓰러질 때 그림자 옅어짐
            shadow_alpha = shadow_alpha * (1 - top["tilt"] / 90)
        shadow_color = (0, 0, 0, int(shadow_alpha))
        pygame.draw.ellipse(shadow_surface, shadow_color, shadow_surface.get_rect())
        screen.blit(shadow_surface, 
                    (top["x"] - shadow_size // 2, top["y"] + 25))

def apply_red_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 붉은 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 붉은 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 빨간색 오버레이 색상 계산
    red_factor = min(255, 255 + int(intensity * 0.8))
    green_factor = max(0, 255 - int(intensity * 0.2))
    blue_factor = max(0, 255 - int(intensity * 0.2))
    overlay.fill((red_factor, green_factor, blue_factor, 90))  # 투명도 90
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)
def apply_blue_overlay(surface, intensity):
    """
    투명하지 않은 픽셀에만 파란색 효과를 적용하는 함수 (최적화 버전)
    :param surface: pygame.Surface (RGBA)
    :param intensity: 0~255 사이의 파란색 정도
    """
    #  성능 최적화: 매우 큰 표면에서는 효과 비활성화
    if surface.get_width() > 300 or surface.get_height() > 300:
        return
    #  성능 최적화: 블렌딩 모드를 사용한 효율적인 색상 적용
    # 임시 표면을 생성하고 블렌딩 모드 사용
    overlay = pygame.Surface(surface.get_size(), pygame.SRCALPHA)
    # 파란색 오버레이 색상 계산
    blue_factor = min(255, int(intensity * 0.5))
    red_factor = max(0, 255 - int(intensity * 0.3))
    green_factor = max(0, 255 - int(intensity * 0.1))
    overlay.fill((red_factor, green_factor, blue_factor, 80))  # 투명도 80
    #  블렌드 모드를 사용하여 효율적으로 색상 적용
    surface.blit(overlay, (0, 0), special_flags=pygame.BLEND_MULT)


def apply_ai_glitch_effect(surface: pygame.Surface, time_now: int) -> pygame.Surface:
    """AI 필 활성화 동안 패들에 사이버 글리치 효과를 적용."""
    width, height = surface.get_size()
    if width == 0 or height == 0:
        return surface

    glitched = surface.copy()
    slice_height = max(4, height // 9)
    base_phase = time_now * 0.015

    for idx, y in enumerate(range(0, height, slice_height)):
        rect = pygame.Rect(0, y, width, min(slice_height, height - y))
        segment = surface.subsurface(rect).copy()
        horizontal_shift = int(math.sin(base_phase + idx * 0.6) * 5)

        tint_alpha = 50 + (idx % 3) * 25
        tint_surface = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
        tint_surface.fill((40, 220, 255, min(180, tint_alpha)))
        segment.blit(tint_surface, (0, 0), special_flags=pygame.BLEND_ADD)

        glitched.blit(segment, (horizontal_shift, y), special_flags=pygame.BLEND_RGBA_ADD)

    original_alpha = surface.get_alpha()
    if original_alpha is not None:
        glitched.set_alpha(original_alpha)

    return glitched
def update_water_trail():
    """물자국 업데이트 함수"""
    global water_trail_positions, water_trail_timer
    # 디버프가 활성화되어 있을 때만 물자국 생성
    if player_slow_timer > 0:
        water_trail_timer += 1
        # 일정 간격으로 물자국 생성 (패들 바닥 중앙)
        if water_trail_timer >= 10:  # 10프레임마다 생성
            water_trail_positions.append((PLAYER.centerx, PLAYER.bottom + 5, 100))  # 초기 투명도 100
            water_trail_timer = 0
    # 물자국 점점 사라지게 하기 (시간이 지나면 투명도 감소)
    water_trail_positions = [(x, y, alpha - 3) for x, y, alpha in water_trail_positions if alpha > 0]
def draw_water_trail():
    """물자국 그리기 함수"""
    for x, y, alpha in water_trail_positions:
        if alpha > 0:
            # 물자국 크기와 색상
            size = random.randint(8, 15)
            color = (100, DEFAULT_ALPHA, 255, min(alpha, 100))  # 푸른 물빛, 최대 투명도 100
            # 물자국 그리기 (타원형)
            water_surface = pygame.Surface((size, size//2), pygame.SRCALPHA)
            pygame.draw.ellipse(water_surface, color, (0, 0, size, size//2))
            SCREEN.blit(water_surface, (x - size//2, y - size//4))
def draw_pachinko():
    """라스베가스 스타일 슬롯머신 그리기 함수"""
    if not pachinko_active:
        return
    # 라스베가스 스타일 배경 (화려한 그라데이션)
    for y in range(HEIGHT):
        ratio = y / HEIGHT
        r = int(20 + ratio * 30)
        g = int(10 + ratio * 20)
        b = int(40 + ratio * 50)
        draw.line((r, g, b), (0, y), (WIDTH, y))
    # 메인 컨테이너 (라스베가스 카지노 스타일)
    container_width = 500
    container_height = 600
    container_x = (WIDTH - container_width) // 2
    container_y = (HEIGHT - container_height) // 2 - 20
    # 컨테이너 글로우 효과 (골드)
    for i in range(10):
        glow_alpha = 60 - i * 6
        glow_surface = pygame.Surface((container_width + i*6, container_height + i*6), pygame.SRCALPHA)
        glow_surface.fill((255, 215, 0, glow_alpha))
        SCREEN.blit(glow_surface, (container_x - i*3, container_y - i*3))
    # 메인 컨테이너
    main_container = pygame.Rect(container_x, container_y, container_width, container_height)
    draw.rect((25, 15, 5), main_container)
    draw.rect((255, 215, 0), main_container, 4)
    # 내부 컨테이너
    inner_container = pygame.Rect(container_x + 20, container_y + 20, container_width - 40, container_height - 40)
    draw.rect((15, 10, 5), inner_container)
    draw.rect((255, 200, 0), inner_container, 3)
    # 제목 영역
    title_area = pygame.Rect(container_x + 30, container_y + 30, container_width - 60, 80)
    draw.rect((30, 20, 10), title_area)
    draw.rect((255, 215, 0), title_area, 3)
    # 제목 텍스트
    # 픽셀 폰트 타이틀
    title_font = FontStyle.title()  # 48pt 픽셀 폰트
    title_text = title_font.render(" 슬롯머신", True, (255, 215, 0))
    title_rect = title_text.get_rect(center=(container_x + container_width // 2, container_y + 70))
    SCREEN.blit(title_text, title_rect)
    # 슬롯 영역
    slot_area_x = container_x + 50
    slot_area_y = container_y + 150
    slot_area_width = container_width - 100
    slot_area_height = 300
    # 슬롯 배경
    slot_bg_rect = pygame.Rect(slot_area_x - 10, slot_area_y - 10, slot_area_width + 20, slot_area_height + 20)
    draw.rect((20, 15, 10), slot_bg_rect)
    draw.rect((255, 215, 0), slot_bg_rect, 3)
    # 3개 슬롯 그리기
    slot_width = (slot_area_width - 40) // 3
    slot_height = slot_area_height
    for reel_idx in range(3):
        reel_x = slot_area_x + reel_idx * (slot_width + 20)
        reel_y = slot_area_y
        # 릴 배경
        reel_rect = pygame.Rect(reel_x, reel_y, slot_width, slot_height)
        draw.rect((10, 8, 5), reel_rect)
        draw.rect((255, 200, 0), reel_rect, 2)
        # 릴 내부 아이템들 그리기 (세로 스크롤)
        item_size = 60
        visible_items = 5  # 한 번에 보이는 아이템 개수
        for i in range(visible_items):
            item_y = reel_y + i * (slot_height // visible_items) + 10
            item_y -= slot_positions[reel_idx]  # 스크롤 적용
            # 화면 안에 있는 아이템만 그리기
            if item_y + item_size > reel_y and item_y < reel_y + slot_height:
                # 아이템 인덱스 계산
                item_idx = (int(slot_positions[reel_idx] // 8) + i) % 30
                if item_idx < len(slot_reels[reel_idx]):
                    item = slot_reels[reel_idx][item_idx]
                    # 아이템 배경
                    item_rect = pygame.Rect(reel_x + 5, item_y, item_size, item_size)
                    draw.rect((25, 20, 15), item_rect)
                    draw.rect((255, 180, 0), item_rect, 2)
                    # 아이템 아이콘
                    if "icon" in item and item["icon"]:
                        icon = pygame.transform.scale(item["icon"], (50, 50))
                        icon_x = reel_x + 8
                        icon_y = item_y + 5
                        SCREEN.blit(icon, (icon_x, icon_y))
                    else:
                        # 아이콘이 없으면 원으로 그리기
                        center_x = reel_x + slot_width // 2
                        center_y = item_y + item_size // 2
                        draw.circle(item["color"], (center_x, center_y), 20)
        # 중앙 선택 표시 (골드 글로우)
        center_y = reel_y + slot_height // 2
        center_rect = pygame.Rect(reel_x - 5, center_y - 35, slot_width + 10, 70)
        # 글로우 효과
        for i in range(3):
            glow_alpha = 100 - i * 30
            glow_surface = pygame.Surface((slot_width + 10 + i*4, 70 + i*4), pygame.SRCALPHA)
            glow_surface.fill((255, 215, 0, glow_alpha))
            glow_x = reel_x - 5 - i*2
            glow_y = center_y - 35 - i*2
            SCREEN.blit(glow_surface, (glow_x, glow_y))
        draw.rect((255, 215, 0), center_rect, 4)
    # 결과 표시
    if pachinko_phase == 3 and slot_final_result:
        # 당첨 애니메이션
        global slot_win_animation
        slot_win_animation += 1
        # 결과 영역
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 화려한 배경
        for i in range(result_height):
            ratio = i / result_height
            r = int(50 + ratio * 100)
            g = int(30 + ratio * 80)
            b = int(10 + ratio * 40)
            draw.line((r, g, b), (result_x, result_y + i), (result_x + result_width, result_y + i))
        draw.rect((255, 215, 0), (result_x, result_y, result_width, result_height), 4)
        # 당첨 아이템 표시
        if "icon" in slot_final_result and slot_final_result["icon"]:
            icon = pygame.transform.scale(slot_final_result["icon"], (80, 80))
            icon_x = result_x + 30
            icon_y = result_y + 20
            SCREEN.blit(icon, (icon_x, icon_y))
        # 당첨 메시지
        item_name = get_item_name_korean(slot_final_result['name'])
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 32pt 픽셀 폰트
        result_text = f" JACKPOT! {item_name} "
        text = result_font.render(result_text, True, WHITE)
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, WHITE)
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    elif pachinko_phase == 3 and not slot_final_result:
        # 꽝 결과
        result_width = 400
        result_height = 120
        result_x = (WIDTH - result_width) // 2
        result_y = container_y + container_height + 20
        # 어두운 배경
        draw.rect((30, 20, 10), (result_x, result_y, result_width, result_height))
        draw.rect((100, 100, 100), (result_x, result_y, result_width, result_height), 3)
        # 꽝 메시지
        # 픽셀 폰트
        result_font = FontStyle.subtitle()  # 36pt 픽셀 폰트
        result_text = " 아쉽게도 꽝입니다... "
        text = result_font.render(result_text, True, (200, 200, 200))
        text_rect = text.get_rect(center=(result_x + result_width // 2, result_y + 60))
        SCREEN.blit(text, text_rect)
        # 계속하기 안내
        continue_font = FontStyle.body()  # 24pt 픽셀 폰트
        continue_text = " SPACE를 눌러 계속... "
        text_small = continue_font.render(continue_text, True, (200, 200, 200))
        text_small_rect = text_small.get_rect(center=(result_x + result_width // 2, result_y + 100))
        SCREEN.blit(text_small, text_small_rect)
    # 안내 텍스트
    if pachinko_phase == 0:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 슬롯머신 시작! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_spinning and not slot_slowdown_mode:
        # 픽셀 폰트
        guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
        guide_text = " SPACE를 눌러 첫 번째 릴 멈추기! "
        text = guide_font.render(guide_text, True, (255, 215, 0))
        text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
        SCREEN.blit(text, text_rect)
    elif slot_slowdown_mode:
        if slot_stop_order == 0:
            # 픽셀 폰트
            guide_font = FontStyle.menu()  # 28pt 픽셀 폰트
            guide_text = " SPACE를 눌러 두 번째 릴 멈추기! "
            text = guide_font.render(guide_text, True, (255, 215, 0))
            text_rect = text.get_rect(center=(WIDTH // 2, container_y + container_height + 80))
