    # 화면 흔들림 효과 계산
    quake_offset_y = random.randint(-5, 5) if quake_active else 0
    # 바주카포 폭발 화면 흔들림
    bazooka_offset_x = 0
    bazooka_offset_y = 0
    if bazooka_screen_shake_timer > 0:
        # 흔들림 강도 계산 (바주카포는 더 강력)
        intensity = bazooka_screen_shake_timer / 25.0
        bazooka_offset_x = random.randint(-int(10 * intensity), int(10 * intensity))
        bazooka_offset_y = random.randint(-int(8 * intensity), int(8 * intensity))
        bazooka_screen_shake_timer -= 1
    
    #  수류탄 폭발 화면 흔들림
    grenade_offset_x = 0
    grenade_offset_y = 0
    if grenade_shake_timer > 0:
        # 흔들림 강도 계산 (시간이 지날수록 약해짐)
        intensity = grenade_shake_timer / 15.0
        grenade_offset_x = random.randint(-int(8 * intensity), int(8 * intensity))
        grenade_offset_y = random.randint(-int(6 * intensity), int(6 * intensity))
        grenade_shake_timer -= 1
    # 최종 화면 흔들림 오프셋
    total_offset_x = bazooka_offset_x + grenade_offset_x
    total_offset_y = quake_offset_y + bazooka_offset_y + grenade_offset_y
    # 헤르메스의 신발 별가루 파티클 업데이트 및 렌더링
    def update_and_draw_hermes_particles():
        """헤르메스의 신발 별가루 파티클 업데이트 및 렌더링"""
        global hermes_star_particles
        import random
        import math
        
        # 파티클 업데이트
        particles_to_remove = []
        for particle in hermes_star_particles:
            # 위치 업데이트
            particle['x'] += particle['vx']
            particle['y'] += particle['vy']
            # 수명 감소
            particle['life'] -= 1
            if particle['life'] <= 0:
                particles_to_remove.append(particle)
        
        # 죽은 파티클 제거
        for particle in particles_to_remove:
            hermes_star_particles.remove(particle)
        
        # 파티클 렌더링 (패들 뒤에 그려짐)
        for particle in hermes_star_particles:
            # 페이드 효과를 위한 알파값 계산
            alpha = int(255 * (particle['life'] / particle['max_life']))
            
            # 반짝이는 효과를 위한 색상 변화
            time_offset = pygame.time.get_ticks() / 100 + particle['color_offset']
            r = min(255, 200 + int(55 * abs(math.sin(time_offset))))
            g = min(255, 200 + int(55 * abs(math.cos(time_offset))))
            b = 255  # 파란색 계열 유지
            
            # 별 모양 그리기 (작은 십자가 + 대각선)
            center_x = int(particle['x'])
            center_y = int(particle['y'])
            size = particle['size']
            
            # 반짝이는 효과를 위해 크기도 약간 변화
            twinkle_size = size + int(math.sin(time_offset * 2) * 1)
            
            # 별 그리기 (페이드 효과 적용)
            if alpha > 20:  # 너무 투명하면 그리지 않음
                # 중심 점
                pygame.draw.circle(SCREEN, (r, g, b), (center_x, center_y), max(1, twinkle_size//2))
                # 십자 모양
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - twinkle_size, center_y), 
                               (center_x + twinkle_size, center_y), 1)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x, center_y - twinkle_size), 
                               (center_x, center_y + twinkle_size), 1)
                # 대각선 (더 작게)
                small_size = max(1, twinkle_size // 2)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - small_size, center_y - small_size), 
                               (center_x + small_size, center_y + small_size), 1)
                pygame.draw.line(SCREEN, (r, g, b), 
                               (center_x - small_size, center_y + small_size), 
                               (center_x + small_size, center_y - small_size), 1)
    
    # 화면 흔들림을 적용하여 오브젝트 그리기
    def draw_with_shake(surface, pos):
        """  화면 흔들림을 적용하여 그리기"""
        SCREEN.blit(surface, (pos[0] + total_offset_x, pos[1] + total_offset_y))
    def draw_rect_with_shake(color, rect, width=0):
        """ 화면 흔들림을 적용하여 사각형 그리기"""
        shaken_rect = pygame.Rect(rect.x + total_offset_x, rect.y + total_offset_y, rect.width, rect.height)
        draw.rect(color, shaken_rect, width)
    def draw_circle_with_shake(color, pos, radius, width=0):
        """  화면 흔들림을 적용하여 원 그리기"""
        draw.circle(color, (int(pos[0] + total_offset_x), int(pos[1] + total_offset_y)), radius, width)
    # === 보스 이미지 선택 + 스테이지별 전용 사이즈 적용 ===
